// Veeam Report CRUD handlers
func HandleGetVeeamReports(w http.ResponseWriter, r *http.Request) {
	// Ensure table exists
	_, err := database.DB.Exec(`
		CREATE TABLE IF NOT EXISTS veeam_reports (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			name TEXT NOT NULL,
			server_name TEXT NOT NULL,
			report_data TEXT,
			private_key TEXT,
			created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
		)
	`)
	if err != nil {
		log.Printf("Error creating veeam_reports table: %v", err)
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	// Migrate: Add private_key column if it doesn't exist
	if err := migrateVeeamReportsTable(); err != nil {
		log.Printf("Warning: Failed to migrate veeam_reports table: %v", err)
	}

	rows, err := database.DB.Query(`
		SELECT id, name, server_name,
		       CASE WHEN report_data IS NOT NULL AND report_data != '' THEN 1 ELSE 0 END as has_data,
		       created_at, updated_at 
		FROM veeam_reports 
		ORDER BY created_at DESC
	`)
	if err != nil {
		log.Printf("Error querying veeam_reports: %v", err)
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var reports []map[string]interface{}
	for rows.Next() {
		var id int
		var name, serverName sql.NullString
		var hasData int
		var createdAt, updatedAt string

		err := rows.Scan(&id, &name, &serverName, &hasData, &createdAt, &updatedAt)
		if err != nil {
			continue
		}

		report := map[string]interface{}{
			"id":         id,
			"name":       name.String,
			"serverName": serverName.String,
			"hasData":    hasData == 1,
			"createdAt":  createdAt,
			"updatedAt":  updatedAt,
		}

		reports = append(reports, report)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(reports)
}

func HandleGetSingleVeeamReport(w http.ResponseWriter, r *http.Request) {
	path := strings.TrimPrefix(r.URL.Path, "/api/veeam-reports/")
	reportID := strings.Split(path, "/")[0]

	if reportID == "" {
		http.Error(w, "Missing report ID", http.StatusBadRequest)
		return
	}

	var rawJSON sql.NullString
	var privateKey sql.NullString
	err := database.DB.QueryRow(`
		SELECT report_data, private_key 
		FROM veeam_reports 
		WHERE id = ?
	`, reportID).Scan(&rawJSON, &privateKey)

	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "Report not found", http.StatusNotFound)
		} else {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
		return
	}

	if !rawJSON.Valid || rawJSON.String == "" {
		http.Error(w, "Report data not found", http.StatusNotFound)
		return
	}

	var data map[string]interface{}
	if err := json.Unmarshal([]byte(rawJSON.String), &data); err != nil {
		http.Error(w, "Invalid report data", http.StatusInternalServerError)
		return
	}

	// Check if data is encrypted and decrypt if needed
	if utils.IsEncryptedPayload(data) {
		if !privateKey.Valid || privateKey.String == "" {
			http.Error(w, "Private key not found for encrypted report", http.StatusBadRequest)
			return
		}

		decryptedData, err := utils.DecryptData(rawJSON.String, privateKey.String)
		if err != nil {
			log.Printf("Error decrypting report data: %v", err)
			http.Error(w, "Failed to decrypt report data", http.StatusInternalServerError)
			return
		}

		if err := json.Unmarshal([]byte(decryptedData), &data); err != nil {
			http.Error(w, "Invalid decrypted report data", http.StatusInternalServerError)
			return
		}
	}

	json.NewEncoder(w).Encode(data)
}

func HandleCreateVeeamReport(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name       string `json:"name"`
		ServerName string `json:"serverName"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if req.Name == "" {
		http.Error(w, "Report name is required", http.StatusBadRequest)
		return
	}

	if req.ServerName == "" {
		http.Error(w, "Server name is required", http.StatusBadRequest)
		return
	}

	result, err := database.DB.Exec(`
		INSERT INTO veeam_reports (name, server_name)
		VALUES (?, ?)
	`, req.Name, req.ServerName)

	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	id, _ := result.LastInsertId()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"success": true,
		"id":      id,
	})
}

