// HandleAuditVeeam performs a comprehensive audit of Veeam Backup & Replication
func HandleAuditVeeam(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		ReportID      int    `json:"reportId"`
		ServerName    string `json:"serverName"`
		ServerAddress string `json:"serverAddress"`
		Username      string `json:"username"`
		Password      string `json:"password"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	if req.ReportID == 0 {
		http.Error(w, "Report ID is required", http.StatusBadRequest)
		return
	}

	// Generate PowerShell script to audit Veeam
	auditScript := generateVeeamAuditScript()

	// Execute the script (local execution for now)
	cmd := exec.Command("powershell", "-Command", auditScript)
	output, err := cmd.CombinedOutput()
	if err != nil {
		log.Printf("Error executing Veeam audit script: %v, Output: %s", err, string(output))
		http.Error(w, "Failed to execute audit: "+err.Error(), http.StatusInternalServerError)
		return
	}

	// Parse the JSON output
	var auditData map[string]interface{}
	if err := json.Unmarshal(output, &auditData); err != nil {
		log.Printf("Error parsing audit output: %v, Raw output: %s", err, string(output))
		http.Error(w, "Failed to parse audit results", http.StatusInternalServerError)
		return
	}

	// Add metadata
	auditData["auditDate"] = time.Now().Format(time.RFC3339)
	auditData["serverName"] = req.ServerName
	if req.ServerAddress != "" {
		auditData["serverAddress"] = req.ServerAddress
	}

	// Convert to JSON string
	reportDataJSON, err := json.Marshal(auditData)
	if err != nil {
		http.Error(w, "Error encoding report data", http.StatusInternalServerError)
		return
	}

	// Update report with data
	_, err = database.DB.Exec(`
		UPDATE veeam_reports 
		SET report_data = ?, updated_at = CURRENT_TIMESTAMP
		WHERE id = ?
	`, string(reportDataJSON), req.ReportID)

	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"success": true,
		"data":    auditData,
	})
}

// HandleGenerateVeeamReportScript generates a PowerShell script for Veeam auditing
func HandleGenerateVeeamReportScript(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		ReportID  *int  `json:"reportId"`
		Obfuscate *bool `json:"obfuscate"`
		Encrypt   *bool `json:"encrypt"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	obfuscate := true
	if req.Obfuscate != nil {
		obfuscate = *req.Obfuscate
	}
	encrypt := true
	if req.Encrypt != nil {
		encrypt = *req.Encrypt
	}

	var publicKeyPEM string
	if encrypt {
		// Check if report already has a private key (to preserve compatibility with existing encrypted data)
		var existingPrivateKey sql.NullString
		if req.ReportID != nil && *req.ReportID > 0 {
			err := database.DB.QueryRow(`
				SELECT private_key 
				FROM veeam_reports 
				WHERE id = ?
			`, *req.ReportID).Scan(&existingPrivateKey)
			if err != nil && err != sql.ErrNoRows {
				log.Printf("Warning: Failed to check for existing private key: %v", err)
			}
		}

		var privateKey *rsa.PrivateKey
		if existingPrivateKey.Valid && existingPrivateKey.String != "" {
			// Use existing private key to maintain compatibility with previously encrypted data
			block, _ := pem.Decode([]byte(existingPrivateKey.String))
			if block == nil {
				log.Printf("Warning: Failed to decode existing private key, generating new one")
				// Fall through to generate new key
			} else {
				var parseErr error
				privateKey, parseErr = x509.ParsePKCS1PrivateKey(block.Bytes)
				if parseErr != nil {
					log.Printf("Warning: Failed to parse existing private key, generating new one: %v", parseErr)
					// Fall through to generate new key
				}
			}
		}

		// Generate new key pair only if no valid existing key was found
		if privateKey == nil {
			var err error
			privateKey, err = rsa.GenerateKey(rand.Reader, 2048)
			if err != nil {
				http.Error(w, "Failed to generate encryption keys: "+err.Error(), http.StatusInternalServerError)
				return
			}

			// Encode private key to PEM format
			privateKeyPEMBytes := pem.EncodeToMemory(&pem.Block{
				Type:  "RSA PRIVATE KEY",
				Bytes: x509.MarshalPKCS1PrivateKey(privateKey),
			})

			// Store private key in database if report ID is provided
			if req.ReportID != nil && *req.ReportID > 0 {
				_, err = database.DB.Exec(`
					UPDATE veeam_reports 
					SET private_key = ? 
					WHERE id = ?
				`, string(privateKeyPEMBytes), *req.ReportID)
				if err != nil {
					log.Printf("Warning: Failed to store private key: %v", err)
				}
			}
		}

		// Get public key in PEM format
		publicKeyDER, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
		if err != nil {
			http.Error(w, "Failed to encode public key: "+err.Error(), http.StatusInternalServerError)
			return
		}
		publicKeyPEMBytes := pem.EncodeToMemory(&pem.Block{
			Type:  "PUBLIC KEY",
			Bytes: publicKeyDER,
		})
		publicKeyPEM = string(publicKeyPEMBytes)
	}

	// Generate script with appropriate options
	script := generateVeeamAuditScriptForLocal(publicKeyPEM, encrypt)

	if obfuscate {
		script = scripts.ObfuscatePowerShellScript(script)
	}

	response := map[string]interface{}{"script": script}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

// HandleImportVeeamReport imports JSON data from a file
func HandleImportVeeamReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Parse multipart form
	err := r.ParseMultipartForm(10 << 20) // 10 MB max
	if err != nil {
		http.Error(w, "Error parsing form: "+err.Error(), http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "Error retrieving file: "+err.Error(), http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Check file extension
	if !strings.HasSuffix(strings.ToLower(header.Filename), ".json") {
		http.Error(w, "File must be a JSON file", http.StatusBadRequest)
		return
	}

	// Read file content
	fileBytes, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Error reading file: "+err.Error(), http.StatusInternalServerError)
		return
	}

	// Remove UTF-8 BOM if present
	fileBytes = bytes.TrimPrefix(fileBytes, []byte{0xEF, 0xBB, 0xBF})
	fileBytes = bytes.TrimSpace(fileBytes)

	// Get report ID from form
	reportID := r.FormValue("reportId")
	if reportID == "" {
		http.Error(w, "Report ID required", http.StatusBadRequest)
		return
	}

	rawJSON := strings.TrimSpace(string(fileBytes))

	// Parse JSON - try plain first, then encrypted
	var reportData map[string]interface{}
	var plainCandidate map[string]interface{}
	if err := json.Unmarshal([]byte(rawJSON), &plainCandidate); err == nil {
		if !utils.IsEncryptedPayload(plainCandidate) {
			reportData = plainCandidate
		}
	}

	if reportData == nil {
		// Encrypted payload path - requires private key from the report
		var privateKeyPEM sql.NullString
		err = database.DB.QueryRow(`
			SELECT private_key 
			FROM veeam_reports 
			WHERE id = ?
		`, reportID).Scan(&privateKeyPEM)

		if err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Report not found", http.StatusNotFound)
			} else {
				http.Error(w, "Error retrieving private key: "+err.Error(), http.StatusInternalServerError)
			}
			return
		}

		if !privateKeyPEM.Valid || privateKeyPEM.String == "" {
			http.Error(w, "Private key not found for this report. The encrypted data must be imported using the script generated for this specific report. Please regenerate the script and run it again.", http.StatusBadRequest)
			return
		}

		decryptedData, err := utils.DecryptData(rawJSON, privateKeyPEM.String)
		if err != nil {
			log.Printf("Error decrypting imported data: %v", err)
			http.Error(w, "Failed to decrypt data. The encrypted file may have been generated with a different key pair. Please ensure you are importing data from the script generated for this specific report: "+err.Error(), http.StatusBadRequest)
			return
		}

		if err := json.Unmarshal([]byte(decryptedData), &reportData); err != nil {
			http.Error(w, "Invalid JSON after decryption: "+err.Error(), http.StatusBadRequest)
			return
		}
	}

	// Convert report data to JSON string (always store as plain JSON after decryption)
	reportDataJSON, err := json.Marshal(reportData)
	if err != nil {
		http.Error(w, "Error encoding report data: "+err.Error(), http.StatusInternalServerError)
		return
	}

	// Update report with data
	_, err = database.DB.Exec(`
		UPDATE veeam_reports 
		SET report_data = ?, updated_at = CURRENT_TIMESTAMP
		WHERE id = ?
	`, string(reportDataJSON), reportID)

	if err != nil {
		http.Error(w, "Error updating report: "+err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"success": true,
		"message": "Report imported successfully",
	})
}

// generateVeeamAuditScript generates a PowerShell script to audit Veeam Backup & Replication
// This is the old function that executes directly - kept for backward compatibility
func generateVeeamAuditScript() string {
	var script bytes.Buffer

	script.WriteString("$ErrorActionPreference = 'Stop'\n")
	script.WriteString("$ProgressPreference = 'SilentlyContinue'\n\n")

	script.WriteString("function Update-Progress {\n")
	script.WriteString("    param([int]$Step, [string]$Activity, [string]$Status)\n")
	script.WriteString("    $percent = [math]::Round(($Step / $totalSteps) * 100)\n")
	script.WriteString("    Write-Host \"[$percent%] $Status\"\n")
	script.WriteString("}\n\n")

	script.WriteString("$totalSteps = 20\n")
	script.WriteString("$currentStep = 0\n\n")

	script.WriteString("$result = @{}\n\n")

	script.WriteString("try {\n")
	script.WriteString("    # Veeam Backup & Replication Information\n")
	script.WriteString("    Update-Progress -Step ($currentStep++) -Activity \"Checking Veeam Installation\" -Status \"Verifying Veeam Backup & Replication installation\"\n")
	script.WriteString("    $veeamInfo = @{\n")
	script.WriteString("        'installed' = $false\n")
	script.WriteString("        'version' = 'N/A'\n")
	script.WriteString("        'serverName' = 'N/A'\n")
	script.WriteString("        'connected' = $false\n")
	script.WriteString("        'error' = $null\n")
	script.WriteString("    }\n")
	script.WriteString("    \n")
	script.WriteString("    try {\n")
	script.WriteString("        # Check if Veeam is installed by checking registry\n")
	script.WriteString("        $veeamRegPath = 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication'\n")
	script.WriteString("        $veeamInstalled = Test-Path $veeamRegPath\n")
	script.WriteString("        \n")
	script.WriteString("        if ($veeamInstalled) {\n")
	script.WriteString("            $veeamInfo['installed'] = $true\n")
	script.WriteString("            \n")
	script.WriteString("            # Get Veeam version\n")
	script.WriteString("            try {\n")
	script.WriteString("                $corePath = Get-ItemProperty -Path $veeamRegPath -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                    $depDLLPath = Join-Path -Path $corePath.CorePath -ChildPath 'Packages\\VeeamDeploymentDll.dll'\n")
	script.WriteString("                    if (Test-Path $depDLLPath) {\n")
	script.WriteString("                        $file = Get-Item -Path $depDLLPath\n")
	script.WriteString("                        $veeamInfo['version'] = $file.VersionInfo.ProductVersion\n")
	script.WriteString("                        $veeamInfo['fixes'] = $file.VersionInfo.Comments\n")
	script.WriteString("                    }\n")
	script.WriteString("                }\n")
	script.WriteString("            } catch {}\n")
	script.WriteString("            \n")
	script.WriteString("            # Try to load Veeam PowerShell module/snap-in\n")
	script.WriteString("            $veeamModuleLoaded = $false\n")
	script.WriteString("            try {\n")
	script.WriteString("                # PowerShell 7+ only supports modules, not PSSnapins\n")
	script.WriteString("                if ($PSVersionTable.PSVersion.Major -ge 6) {\n")
	script.WriteString("                    if (!(Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue)) {\n")
	script.WriteString("                        Import-Module -Name Veeam.Backup.Powershell -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                    }\n")
	script.WriteString("                    if (Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                        $veeamModuleLoaded = $true\n")
	script.WriteString("                    }\n")
	script.WriteString("                } else {\n")
	script.WriteString("                    # Windows PowerShell 5.1 - try PSSnapin first, then module\n")
	script.WriteString("                    if (!(Get-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue)) {\n")
	script.WriteString("                        Add-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                    }\n")
	script.WriteString("                    if (Get-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                        $veeamModuleLoaded = $true\n")
	script.WriteString("                    } elseif (!(Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue)) {\n")
	script.WriteString("                        Import-Module -Name Veeam.Backup.Powershell -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                        if (Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                            $veeamModuleLoaded = $true\n")
	script.WriteString("                        }\n")
	script.WriteString("                    }\n")
	script.WriteString("                }\n")
	script.WriteString("            } catch {\n")
	script.WriteString("                $veeamInfo['error'] = \"Failed to load Veeam module: $($_.Exception.Message)\"\n")
	script.WriteString("            }\n")
	script.WriteString("            \n")
	script.WriteString("            if ($veeamModuleLoaded) {\n")
	script.WriteString("                try {\n")
	script.WriteString("                    # Disconnect any existing connections\n")
	script.WriteString("                    Disconnect-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                    \n")
	script.WriteString("                    # Try to connect to local VBR server\n")
	script.WriteString("                    $vbrServer = 'localhost'\n")
	script.WriteString("                    try {\n")
	script.WriteString("                        Connect-VBRServer -Server $vbrServer -ErrorAction Stop\n")
	script.WriteString("                        $veeamInfo['connected'] = $true\n")
	script.WriteString("                        $veeamInfo['serverName'] = $vbrServer\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get VBR Server Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Server Information\" -Status \"Gathering VBR server and configuration details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $vbrServers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['servers'] = @($vbrServers | Select-Object -Property Name, Type, IsUnavailable, @{n='Cores';e={try{$_.GetPhysicalHost().hardwareinfo.CoresCount}catch{'N/A'}}}, @{n='CPUCount';e={try{$_.GetPhysicalHost().hardwareinfo.CPUCount}catch{'N/A'}}}, @{n='RAM';e={try{[math]::Round($_.GetPhysicalHost().hardwareinfo.PhysicalRamTotal / 1GB, 2)}catch{'N/A'}}})\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Backup Server & Config DB Info\n")
	script.WriteString("                            $backupServerInfo = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get Veeam Version\n")
	script.WriteString("                                $veeamVersion = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Method 1: Try CVersion class\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $version = [Veeam.Backup.Core.CVersion]::Get()\n")
	script.WriteString("                                        if ($version) {\n")
	script.WriteString("                                            $veeamVersion = $version.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Method 2: Try registry\n")
	script.WriteString("                                    if ($veeamVersion -eq 'N/A') {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $corePath = Get-ItemProperty -Path 'HKLM:\\Software\\Veeam\\Veeam Backup and Replication\\' -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                                                $depDLLPath = Join-Path -Path $corePath.CorePath -ChildPath 'Packages\\VeeamDeploymentDll.dll'\n")
	script.WriteString("                                                if (Test-Path $depDLLPath) {\n")
	script.WriteString("                                                    $file = Get-Item -Path $depDLLPath\n")
	script.WriteString("                                                    if ($file.VersionInfo.ProductVersion) {\n")
	script.WriteString("                                                        $veeamVersion = $file.VersionInfo.ProductVersion\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Method 3: Try Get-VBRServerVersion\n")
	script.WriteString("                                    if ($veeamVersion -eq 'N/A') {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $version = Get-VBRServerVersion -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($version) {\n")
	script.WriteString("                                                $veeamVersion = $version.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Get local VBR server (backup server)\n")
	script.WriteString("                                $backupServer = $null\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $backupServer = Get-VBRServer | Where-Object { $_.Type -eq 'VBRServer' -or $_.Name -eq 'localhost' -or $_.Name -eq $env:COMPUTERNAME } | Select-Object -First 1\n")
	script.WriteString("                                    if (-not $backupServer) {\n")
	script.WriteString("                                        $backupServer = $vbrServers | Select-Object -First 1\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($backupServer) {\n")
	script.WriteString("                                    $serverName = $backupServer.Name\n")
	script.WriteString("                                    $cores = 'N/A'\n")
	script.WriteString("                                    $ram = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $physicalHost = $backupServer.GetPhysicalHost()\n")
	script.WriteString("                                        if ($physicalHost -and $physicalHost.hardwareinfo) {\n")
	script.WriteString("                                            $cores = $physicalHost.hardwareinfo.CoresCount\n")
	script.WriteString("                                            # PhysicalRamTotal is in bytes, convert to GB\n")
	script.WriteString("                                            $ram = [math]::Round($physicalHost.hardwareinfo.PhysicalRamTotal / 1GB, 2)\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check Proxy Role\n")
	script.WriteString("                                    $proxyRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($proxies) {\n")
	script.WriteString("                                            $proxyRole = ($proxies | Where-Object { $_.Host.Id -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check Repository/Gateway Role\n")
	script.WriteString("                                    $repoGatewayRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $repositories = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($repositories) {\n")
	script.WriteString("                                            $repoGatewayRole = ($repositories | Where-Object { $_.HostId -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check WAN Accelerator Role\n")
	script.WriteString("                                    $wanAccRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $wanAccelerators = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($wanAccelerators) {\n")
	script.WriteString("                                            $wanAccRole = ($wanAccelerators | Where-Object { $_.HostId -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Domain Joined status\n")
	script.WriteString("                                    $isDomainJoined = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $computerSystem = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($computerSystem) {\n")
	script.WriteString("                                            $isDomainJoined = ($computerSystem.PartOfDomain -eq $true)\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Database Info\n")
	script.WriteString("                                    $dbType = 'N/A'\n")
	script.WriteString("                                    $dbName = 'N/A'\n")
	script.WriteString("                                    $dbServer = 'N/A'\n")
	script.WriteString("                                    $dbPort = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $dbTypePath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations' -Name 'SqlActiveConfiguration' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($dbTypePath) {\n")
	script.WriteString("                                            $dbType = $dbTypePath.SqlActiveConfiguration\n")
	script.WriteString("                                            if ($dbType -eq 'PostgreSql') {\n")
	script.WriteString("                                                $pgDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlHostName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $pgDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $pgDbPort = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlPort' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($pgDbHost) { $dbServer = $pgDbHost.SqlHostName }\n")
	script.WriteString("                                                if ($pgDbName) { $dbName = $pgDbName.SqlDatabaseName }\n")
	script.WriteString("                                                if ($pgDbPort -and $pgDbPort.PSObject.Properties['SqlPort']) {\n")
	script.WriteString("                                                    $portValue = $pgDbPort.SqlPort\n")
	script.WriteString("                                                    if ($portValue) { $dbPort = $portValue.ToString() + '/TCP' }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($dbType -eq 'MsSql') {\n")
	script.WriteString("                                                $msDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $msDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($msDbHost) { $dbServer = $msDbHost.SqlServerName }\n")
	script.WriteString("                                                if ($msDbName) { $dbName = $msDbName.SqlDatabaseName }\n")
	script.WriteString("                                                $dbPort = '1433/TCP'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Connection Ports\n")
	script.WriteString("                                    $backupServerPort = 'N/A'\n")
	script.WriteString("                                    $secureConnectionsPort = 'N/A'\n")
	script.WriteString("                                    $cloudServerPort = 'N/A'\n")
	script.WriteString("                                    $cloudServicePort = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $portsPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($portsPath) {\n")
	script.WriteString("                                            if ($portsPath.BackupServerPort) { $backupServerPort = 'Backup Server Port: ' + $portsPath.BackupServerPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.SecureConnectionsPort) { $secureConnectionsPort = 'Secure Connections Port: ' + $portsPath.SecureConnectionsPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.CloudServerPort) { $cloudServerPort = 'Cloud Server Port: ' + $portsPath.CloudServerPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.CloudServicePort) { $cloudServicePort = 'Cloud Service Port: ' + $portsPath.CloudServicePort.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Install Path\n")
	script.WriteString("                                    $installPath = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $corePath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                                            $installPath = $corePath.CorePath\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Audit Logs Path\n")
	script.WriteString("                                    $auditLogsPath = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $auditPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'AuditPath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($auditPath) {\n")
	script.WriteString("                                            if ($auditPath.AuditPath) { $auditLogsPath = $auditPath.AuditPath }\n")
	script.WriteString("                                            elseif ($auditPath.PSObject.Properties['AuditPath']) { $auditLogsPath = $auditPath.PSObject.Properties['AuditPath'].Value }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Compress Old Audit Logs\n")
	script.WriteString("                                    $compressOldAuditLogs = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $compressPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'CompressOldAuditLogs' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($compressPath) {\n")
	script.WriteString("                                            if ($compressPath.PSObject.Properties['CompressOldAuditLogs']) {\n")
	script.WriteString("                                                $compressValue = $compressPath.CompressOldAuditLogs\n")
	script.WriteString("                                                $compressOldAuditLogs = ($compressValue -eq 1 -or $compressValue -eq $true)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get FIPS Compliant Mode\n")
	script.WriteString("                                    $fipsCompliantMode = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $fipsPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'FipsCompliantMode' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($fipsPath) {\n")
	script.WriteString("                                            if ($fipsPath.PSObject.Properties['FipsCompliantMode']) {\n")
	script.WriteString("                                                $fipsValue = $fipsPath.FipsCompliantMode\n")
	script.WriteString("                                                $fipsCompliantMode = if ($fipsValue -eq 1 -or $fipsValue -eq $true) { 'Enabled' } else { 'Disabled' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Linux host authentication\n")
	script.WriteString("                                    $linuxHostAuth = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $linuxAuthPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'LinuxHostAuthentication' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($linuxAuthPath) {\n")
	script.WriteString("                                            if ($linuxAuthPath.PSObject.Properties['LinuxHostAuthentication']) {\n")
	script.WriteString("                                                $authValue = $linuxAuthPath.LinuxHostAuthentication\n")
	script.WriteString("                                                if ($authValue -eq 0) { $linuxHostAuth = 'Add unknown host to the list automatically' }\n")
	script.WriteString("                                                elseif ($authValue -eq 1) { $linuxHostAuth = 'Add unknown host to the list manually' }\n")
	script.WriteString("                                                else { $linuxHostAuth = 'N/A' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Logging Level\n")
	script.WriteString("                                    $loggingLevel = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $logLevelPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'LoggingLevel' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($logLevelPath) {\n")
	script.WriteString("                                            $loggingLevel = $logLevelPath.LoggingLevel.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Hardware & Software Inventory\n")
	script.WriteString("                                    $systemInventory = @{}\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $computer = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $bios = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $processor = Get-CimInstance Win32_Processor | Select-Object -First 1 -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $timezone = (Get-TimeZone -ErrorAction SilentlyContinue).DisplayName\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get License Info\n")
	script.WriteString("                                        $licenseType = 'N/A'\n")
	script.WriteString("                                        $partialProductKey = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $license = Get-CimInstance -ClassName SoftwareLicensingProduct -ErrorAction SilentlyContinue | Where-Object { $_.PartialProductKey -and $_.Name -like '*Windows*' } | Select-Object -First 1\n")
	script.WriteString("                                            if ($license) {\n")
	script.WriteString("                                                $licenseType = $license.Name\n")
	script.WriteString("                                                $partialProductKey = $license.PartialProductKey\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Install Type\n")
	script.WriteString("                                        $installType = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $serverGuiShell = Get-WindowsFeature -Name Server-Gui-Shell -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($serverGuiShell) {\n")
	script.WriteString("                                                $installType = if ($serverGuiShell.InstallState -eq 'Installed') { 'Server' } else { 'Server Core' }\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $installType = 'Server'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {\n")
	script.WriteString("                                            $installType = 'Server'\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get BIOS Type\n")
	script.WriteString("                                        $biosType = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $biosType = if ($bios.SMBIOSBIOSVersion -like '*UEFI*' -or ($bios.BiosCharacteristics -and $bios.BiosCharacteristics -contains 12)) { 'Uefi' } else { 'Legacy' }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($os -and $computer -and $bios -and $processor) {\n")
	script.WriteString("                                            $systemInventory = @{\n")
	script.WriteString("                                                'name' = $computer.Name\n")
	script.WriteString("                                                'windowsProductName' = $os.Caption\n")
	script.WriteString("                                                'windowsCurrentVersion' = $os.Version\n")
	script.WriteString("                                                'windowsBuildNumber' = $os.BuildNumber\n")
	script.WriteString("                                                'windowsInstallType' = $installType\n")
	script.WriteString("                                                'activeDirectoryDomain' = $computer.Domain\n")
	script.WriteString("                                                'windowsInstallationDate' = if ($os.InstallDate) { $os.InstallDate.ToString('MM/dd/yyyy HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                                'timeZone' = if ($timezone) { $timezone } else { 'N/A' }\n")
	script.WriteString("                                                'licenseType' = $licenseType\n")
	script.WriteString("                                                'partialProductKey' = $partialProductKey\n")
	script.WriteString("                                                'manufacturer' = $computer.Manufacturer\n")
	script.WriteString("                                                'model' = $computer.Model\n")
	script.WriteString("                                                'serialNumber' = $bios.SerialNumber\n")
	script.WriteString("                                                'biosType' = $biosType\n")
	script.WriteString("                                                'biosVersion' = $bios.Version\n")
	script.WriteString("                                                'processorManufacturer' = $processor.Manufacturer\n")
	script.WriteString("                                                'processorModel' = $processor.Name\n")
	script.WriteString("                                                'numberOfCpuCores' = $processor.NumberOfCores\n")
	script.WriteString("                                                'numberOfLogicalCores' = $processor.NumberOfLogicalProcessors\n")
	script.WriteString("                                                'physicalMemoryGB' = [math]::Round($computer.TotalPhysicalMemory / 1GB, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Local Disks\n")
	script.WriteString("                                    $localDisks = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $disks = Get-Disk -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($disks) {\n")
	script.WriteString("                                            $localDisks = @($disks | ForEach-Object {\n")
	script.WriteString("                                                $disk = $_\n")
	script.WriteString("                                                $partitionStyle = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $partitionStyle = $disk.PartitionStyle.ToString()\n")
	script.WriteString("                                                    if ($partitionStyle -eq 'GPT') { $partitionStyle = '2' }\n")
	script.WriteString("                                                    elseif ($partitionStyle -eq 'MBR') { $partitionStyle = '1' }\n")
	script.WriteString("                                                    elseif ($partitionStyle -eq 'Raw') { $partitionStyle = '0' }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'diskNumber' = $disk.Number\n")
	script.WriteString("                                                    'model' = if ($disk.Model) { $disk.Model.Trim() } else { 'N/A' }\n")
	script.WriteString("                                                    'serialNumber' = if ($disk.SerialNumber) { $disk.SerialNumber.Trim() } else { 'N/A' }\n")
	script.WriteString("                                                    'partitionStyle' = $partitionStyle\n")
	script.WriteString("                                                    'diskSize' = [math]::Round($disk.Size / 1GB, 2)\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Host Volumes\n")
	script.WriteString("                                    $hostVolumes = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $volumes = Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -or $_.FileSystemLabel }\n")
	script.WriteString("                                        if ($volumes) {\n")
	script.WriteString("                                            $hostVolumes = @($volumes | ForEach-Object {\n")
	script.WriteString("                                                $vol = $_\n")
	script.WriteString("                                                $healthStatus = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    if ($vol.HealthStatus) {\n")
	script.WriteString("                                                        $healthStatus = $vol.HealthStatus.ToString()\n")
	script.WriteString("                                                        if ($healthStatus -eq 'Healthy') { $healthStatus = '0' }\n")
	script.WriteString("                                                        elseif ($healthStatus -eq 'Warning') { $healthStatus = '1' }\n")
	script.WriteString("                                                        elseif ($healthStatus -eq 'Unhealthy') { $healthStatus = '2' }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'driveLetter' = if ($vol.DriveLetter) { $vol.DriveLetter } else { '' }\n")
	script.WriteString("                                                    'fileSystemLabel' = if ($vol.FileSystemLabel) { $vol.FileSystemLabel } else { '' }\n")
	script.WriteString("                                                    'fileSystem' = if ($vol.FileSystem) { $vol.FileSystem } else { 'N/A' }\n")
	script.WriteString("                                                    'size' = [math]::Round($vol.Size / 1GB, 2)\n")
	script.WriteString("                                                    'freeSpace' = [math]::Round($vol.SizeRemaining / 1GB, 2)\n")
	script.WriteString("                                                    'healthStatus' = $healthStatus\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Network Adapters\n")
	script.WriteString("                                    $networkAdapters = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $adapters = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }\n")
	script.WriteString("                                        if ($adapters) {\n")
	script.WriteString("                                            $networkAdapters = @($adapters | ForEach-Object {\n")
	script.WriteString("                                                $adapter = $_\n")
	script.WriteString("                                                $linkSpeed = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $linkSpeed = $adapter.LinkSpeed\n")
	script.WriteString("                                                    if ($linkSpeed) {\n")
	script.WriteString("                                                        $linkSpeed = $linkSpeed.ToString()\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'adapterName' = if ($adapter.Name) { $adapter.Name } else { 'N/A' }\n")
	script.WriteString("                                                    'adapterDescription' = if ($adapter.InterfaceDescription) { $adapter.InterfaceDescription } else { 'N/A' }\n")
	script.WriteString("                                                    'macAddress' = if ($adapter.MacAddress) { $adapter.MacAddress } else { 'N/A' }\n")
	script.WriteString("                                                    'linkSpeed' = $linkSpeed\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get IP Address Information\n")
	script.WriteString("                                    $ipAddresses = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $netAdapters = Get-NetAdapter -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($netAdapters) {\n")
	script.WriteString("                                            foreach ($adapter in $netAdapters) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $ipConfig = Get-NetIPAddress -InterfaceIndex $adapter.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    $ipGateway = Get-NetRoute -InterfaceIndex $adapter.InterfaceIndex -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Select-Object -First 1\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    if ($ipConfig) {\n")
	script.WriteString("                                                        foreach ($ip in $ipConfig) {\n")
	script.WriteString("                                                            $subnetMask = 'N/A'\n")
	script.WriteString("                                                            $gateway = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($ip.PrefixLength) {\n")
	script.WriteString("                                                                    $subnetMask = $ip.PrefixLength.ToString()\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                if ($ipGateway -and $ipGateway.NextHop) {\n")
	script.WriteString("                                                                    $gateway = $ipGateway.NextHop.ToString()\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $ipAddresses += @{\n")
	script.WriteString("                                                                'interfaceName' = if ($adapter.Name) { $adapter.Name } else { 'N/A' }\n")
	script.WriteString("                                                                'interfaceDescription' = if ($adapter.InterfaceDescription) { $adapter.InterfaceDescription } else { 'N/A' }\n")
	script.WriteString("                                                                'ipv4Address' = if ($ip.IPAddress) { $ip.IPAddress.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                                'subnetMask' = $subnetMask\n")
	script.WriteString("                                                                'ipv4Gateway' = $gateway\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $backupServerInfo = @{\n")
	script.WriteString("                                        'name' = $serverName\n")
	script.WriteString("                                        'isDomainJoined' = $isDomainJoined\n")
	script.WriteString("                                        'version' = $veeamVersion\n")
	script.WriteString("                                        'databaseType' = $dbType\n")
	script.WriteString("                                        'databaseName' = $dbName\n")
	script.WriteString("                                        'databaseServer' = $dbServer\n")
	script.WriteString("                                        'databasePort' = $dbPort\n")
	script.WriteString("                                        'backupServerPort' = $backupServerPort\n")
	script.WriteString("                                        'secureConnectionsPort' = $secureConnectionsPort\n")
	script.WriteString("                                        'cloudServerPort' = $cloudServerPort\n")
	script.WriteString("                                        'cloudServicePort' = $cloudServicePort\n")
	script.WriteString("                                        'installPath' = $installPath\n")
	script.WriteString("                                        'auditLogsPath' = $auditLogsPath\n")
	script.WriteString("                                        'compressOldAuditLogs' = $compressOldAuditLogs\n")
	script.WriteString("                                        'fipsCompliantMode' = $fipsCompliantMode\n")
	script.WriteString("                                        'linuxHostAuth' = $linuxHostAuth\n")
	script.WriteString("                                        'loggingLevel' = $loggingLevel\n")
	script.WriteString("                                        'cores' = $cores\n")
	script.WriteString("                                        'ram' = $ram\n")
	script.WriteString("                                        'proxyRole' = $proxyRole\n")
	script.WriteString("                                        'repoGatewayRole' = $repoGatewayRole\n")
	script.WriteString("                                        'wanAccRole' = $wanAccRole\n")
	script.WriteString("                                        'systemInventory' = $systemInventory\n")
	script.WriteString("                                        'localDisks' = $localDisks\n")
	script.WriteString("                                        'hostVolumes' = $hostVolumes\n")
	script.WriteString("                                        'networkAdapters' = $networkAdapters\n")
	script.WriteString("                                        'ipAddresses' = $ipAddresses\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            $veeamInfo['backupServerInfo'] = $backupServerInfo\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Infrastructure Statistics\n")
	script.WriteString("                            Update-Progress -Step ($currentStep++) -Activity \"Collecting Infrastructure Statistics\" -Status \"Counting infrastructure components\"\n")
	script.WriteString("                            $infrastructureStats = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Backup Proxies\n")
	script.WriteString("                                $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['backupProxies'] = if ($proxies) { $proxies.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Managed Servers\n")
	script.WriteString("                                $servers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['managedServers'] = if ($servers) { $servers.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Backup Repositories (Standalone only)\n")
	script.WriteString("                                $repos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $standaloneRepos = 0\n")
	script.WriteString("                                if ($repos) {\n")
	script.WriteString("                                    foreach ($repo in $repos) {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($repo.IsScaleOut -ne $true) { $standaloneRepos++ }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                $infrastructureStats['backupRepositories'] = $standaloneRepos\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SOBR Repositories\n")
	script.WriteString("                                $sobrs = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sobrRepositories'] = if ($sobrs) { $sobrs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Object Repository\n")
	script.WriteString("                                $objectRepos = Get-VBRObjectStorageRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['objectRepository'] = if ($objectRepos) { $objectRepos.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # WAN Accelerator\n")
	script.WriteString("                                $wanAccs = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['wanAccelerator'] = if ($wanAccs) { $wanAccs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Cloud Service Providers\n")
	script.WriteString("                                $csp = Get-VBRCloudProvider -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['cloudServiceProviders'] = if ($csp) { $csp.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SureBackup Application Group\n")
	script.WriteString("                                $appGroups = Get-VBRApplicationGroup -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sureBackupApplicationGroup'] = if ($appGroups) { $appGroups.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SureBackup Virtual Lab\n")
	script.WriteString("                                $virtualLabs = Get-VBRVirtualLab -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sureBackupVirtualLab'] = if ($virtualLabs) { $virtualLabs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Locations\n")
	script.WriteString("                                $locations = Get-VBRLocation -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['locations'] = if ($locations) { $locations.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # License Information\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $license = Get-VBRLicenseInfo -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($license) {\n")
	script.WriteString("                                        # Instance Licenses\n")
	script.WriteString("                                        if ($license.InstanceLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesTotal'] = if ($license.InstanceLicenseSummary.LicensedInstancesNumber) { $license.InstanceLicenseSummary.LicensedInstancesNumber } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesUsed'] = if ($license.InstanceLicenseSummary.UsedInstancesNumber) { $license.InstanceLicenseSummary.UsedInstancesNumber } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesTotal'] = if ($license.LicensedInstances) { $license.LicensedInstances } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesUsed'] = if ($license.UsedInstances) { $license.UsedInstances } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        # Socket Licenses\n")
	script.WriteString("                                        if ($license.SocketLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesTotal'] = if ($license.SocketLicenseSummary.LicensedSocketsNumber) { $license.SocketLicenseSummary.LicensedSocketsNumber } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesUsed'] = if ($license.SocketLicenseSummary.UsedSocketsNumber) { $license.SocketLicenseSummary.UsedSocketsNumber } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesTotal'] = if ($license.LicensedSockets) { $license.LicensedSockets } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesUsed'] = if ($license.UsedSockets) { $license.UsedSockets } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        # Capacity Licenses\n")
	script.WriteString("                                        if ($license.CapacityLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesTotal'] = if ($license.CapacityLicenseSummary.LicensedCapacityTb) { $license.CapacityLicenseSummary.LicensedCapacityTb } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesUsed'] = if ($license.CapacityLicenseSummary.UsedCapacityTb) { $license.CapacityLicenseSummary.UsedCapacityTb } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesTotal'] = if ($license.LicensedCapacity) { [math]::Round($license.LicensedCapacity / 1TB, 0) } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesUsed'] = if ($license.UsedCapacity) { [math]::Round($license.UsedCapacity / 1TB, 0) } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $infrastructureStats['instanceLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['instanceLicensesUsed'] = 0\n")
	script.WriteString("                                        $infrastructureStats['socketLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['socketLicensesUsed'] = 0\n")
	script.WriteString("                                        $infrastructureStats['capacityLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['capacityLicensesUsed'] = 0\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $infrastructureStats['instanceLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['instanceLicensesUsed'] = 0\n")
	script.WriteString("                                    $infrastructureStats['socketLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['socketLicensesUsed'] = 0\n")
	script.WriteString("                                    $infrastructureStats['capacityLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['capacityLicensesUsed'] = 0\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            $veeamInfo['infrastructureStats'] = $infrastructureStats\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Config Backup Info\n")
	script.WriteString("                            $configBackupInfo = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $job = Get-VBRConfigurationBackupJob -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($job) {\n")
	script.WriteString("                                    # Extract values directly from $job object properties\n")
	script.WriteString("                                    $configBackupName = if ($job.Name) { $job.Name } else { 'N/A' }\n")
	script.WriteString("                                    $configBackupEnabled = if ($job.Enabled -ne $null) { [bool]$job.Enabled } else { $false }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get ScheduleOptions - check the type of schedule\n")
	script.WriteString("                                    $scheduleType = 'N/A'\n")
	script.WriteString("                                    if ($job.ScheduleOptions) {\n")
	script.WriteString("                                        $scheduleOpts = $job.ScheduleOptions\n")
	script.WriteString("                                        # Try to get the schedule type from the object\n")
	script.WriteString("                                        if ($scheduleOpts.OptionsDaily) { $scheduleType = 'Daily' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsMonthly) { $scheduleType = 'Monthly' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsPeriodically) { $scheduleType = 'Periodically' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsContinuous) { $scheduleType = 'Continuous' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsScheduleAfterJob) { $scheduleType = 'After Job' }\n")
	script.WriteString("                                        else {\n")
	script.WriteString("                                            # Fallback: try to get type name or use ToString\n")
	script.WriteString("                                            $typeName = $scheduleOpts.GetType().Name\n")
	script.WriteString("                                            if ($typeName -like '*Daily*') { $scheduleType = 'Daily' }\n")
	script.WriteString("                                            elseif ($typeName -like '*Monthly*') { $scheduleType = 'Monthly' }\n")
	script.WriteString("                                            else { $scheduleType = $scheduleOpts.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get RestorePointsToKeep - handle null/0 values\n")
	script.WriteString("                                    $restorePointsToKeep = 'N/A'\n")
	script.WriteString("                                    if ($job.RestorePointsToKeep -ne $null -and $job.RestorePointsToKeep -ne '') {\n")
	script.WriteString("                                        $restorePointsToKeep = $job.RestorePointsToKeep\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Encryption status - EncryptionOptions is a boolean\n")
	script.WriteString("                                    $configBackupEncrypted = $false\n")
	script.WriteString("                                    if ($job.EncryptionOptions -ne $null) {\n")
	script.WriteString("                                        $configBackupEncrypted = [bool]$job.EncryptionOptions\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get NextRun - handle DateTime objects\n")
	script.WriteString("                                    $nextRun = '--'\n")
	script.WriteString("                                    if ($job.NextRun -ne $null) {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($job.NextRun -is [DateTime]) {\n")
	script.WriteString("                                                $nextRun = $job.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $nextRun = $job.NextRun.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {\n")
	script.WriteString("                                            $nextRun = $job.NextRun.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Target - handle object or string\n")
	script.WriteString("                                    $configBackupTarget = 'N/A'\n")
	script.WriteString("                                    if ($job.Target -ne $null) {\n")
	script.WriteString("                                        if ($job.Target -is [string]) {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target\n")
	script.WriteString("                                        } elseif ($job.Target.Name) {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target.Name\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get LastResult\n")
	script.WriteString("                                    $configBackupLastResult = if ($job.LastResult) { $job.LastResult.ToString() } else { 'None' }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Build simplified config backup info\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = $configBackupName\n")
	script.WriteString("                                        'enabled' = $configBackupEnabled\n")
	script.WriteString("                                        'scheduleType' = $scheduleType\n")
	script.WriteString("                                        'restorePointsToKeep' = $restorePointsToKeep\n")
	script.WriteString("                                        'encrypted' = $configBackupEncrypted\n")
	script.WriteString("                                        'nextRun' = $nextRun\n")
	script.WriteString("                                        'target' = $configBackupTarget\n")
	script.WriteString("                                        'lastResult' = $configBackupLastResult\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    # If no config backup job found, set defaults\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = 'N/A'\n")
	script.WriteString("                                        'enabled' = $false\n")
	script.WriteString("                                        'scheduleType' = 'N/A'\n")
	script.WriteString("                                        'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                        'encrypted' = $false\n")
	script.WriteString("                                        'nextRun' = '--'\n")
	script.WriteString("                                        'target' = 'N/A'\n")
	script.WriteString("                                        'lastResult' = 'N/A'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {\n")
	script.WriteString("                                # On error, set defaults\n")
	script.WriteString("                                $configBackupInfo = @{\n")
	script.WriteString("                                    'name' = 'N/A'\n")
	script.WriteString("                                    'enabled' = $false\n")
	script.WriteString("                                    'scheduleType' = 'N/A'\n")
	script.WriteString("                                    'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                    'encrypted' = $false\n")
	script.WriteString("                                    'nextRun' = '--'\n")
	script.WriteString("                                    'target' = 'N/A'\n")
	script.WriteString("                                    'lastResult' = 'N/A'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['configBackup'] = $configBackupInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Server TLS Certificate\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting TLS Certificate Information\" -Status \"Retrieving backup server TLS certificate details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $tlsCertificate = @{}\n")
	script.WriteString("                            $friendlyName = 'N/A'\n")
	script.WriteString("                            $subjectName = 'N/A'\n")
	script.WriteString("                            $issuerName = 'N/A'\n")
	script.WriteString("                            $expirationDate = 'N/A'\n")
	script.WriteString("                            $issuedDate = 'N/A'\n")
	script.WriteString("                            $thumbprint = 'N/A'\n")
	script.WriteString("                            $serialNumber = 'N/A'\n")
	script.WriteString("                            \n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get certificate from Veeam Backup Server\n")
	script.WriteString("                                $cert = Get-VBRBackupServerCertificate -ErrorAction SilentlyContinue\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($cert) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get FriendlyName\n")
	script.WriteString("                                        if ($cert.FriendlyName) { $friendlyName = $cert.FriendlyName.ToString() }\n")
	script.WriteString("                                        elseif ($cert.Name) { $friendlyName = $cert.Name.ToString() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Subject\n")
	script.WriteString("                                        if ($cert.SubjectName) {\n")
	script.WriteString("                                            if ($cert.SubjectName -is [string]) { $subjectName = $cert.SubjectName }\n")
	script.WriteString("                                            else { $subjectName = $cert.SubjectName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Subject) {\n")
	script.WriteString("                                            if ($cert.Subject -is [string]) { $subjectName = $cert.Subject }\n")
	script.WriteString("                                            else { $subjectName = $cert.Subject.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SubjectName) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.SubjectName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Subject) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.Subject.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issuer\n")
	script.WriteString("                                        if ($cert.IssuerName) {\n")
	script.WriteString("                                            if ($cert.IssuerName -is [string]) { $issuerName = $cert.IssuerName }\n")
	script.WriteString("                                            else { $issuerName = $cert.IssuerName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Issuer) {\n")
	script.WriteString("                                            if ($cert.Issuer -is [string]) { $issuerName = $cert.Issuer }\n")
	script.WriteString("                                            else { $issuerName = $cert.Issuer.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.IssuerName) {\n")
	script.WriteString("                                            $runJobAutomatically = [bool]$configBackupJob.ScheduleOptions.Enabled\n")
	script.WriteString("                                        } elseif ($configBackupJob.IsScheduleEnabled -ne $null) {\n")
	script.WriteString("                                            $runJobAutomatically = [bool]$configBackupJob.IsScheduleEnabled\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Schedule Type and Options\n")
	script.WriteString("                                    $scheduleType = 'N/A'\n")
	script.WriteString("                                    $scheduleTypeValue = 'N/A'\n")
	script.WriteString("                                    $schedulePeriod = 'N/A'\n")
	script.WriteString("                                    $scheduleDayOfWeek = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.ScheduleOptions) {\n")
	script.WriteString("                                            $scheduleOpts = $configBackupJob.ScheduleOptions\n")
	script.WriteString("                                            if ($scheduleOpts.ScheduleType) {\n")
	script.WriteString("                                                $scheduleTypeValue = $scheduleOpts.ScheduleType\n")
	script.WriteString("                                                if ($scheduleTypeValue -is [enum]) {\n")
	script.WriteString("                                                    $scheduleType = $scheduleTypeValue.ToString()\n")
	script.WriteString("                                                } else {\n")
	script.WriteString("                                                    $scheduleType = $scheduleTypeValue.ToString()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($scheduleOpts.DailyOptions -and $scheduleOpts.DailyOptions.Time) {\n")
	script.WriteString("                                                $schedulePeriod = $scheduleOpts.DailyOptions.Time.ToString('HH:mm:ss')\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($scheduleOpts.DailyOptions -and $scheduleOpts.DailyOptions.Days) {\n")
	script.WriteString("                                                $days = @()\n")
	script.WriteString("                                                foreach ($day in $scheduleOpts.DailyOptions.Days) {\n")
	script.WriteString("                                                    if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                $scheduleDayOfWeek = $days -join ' '\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Restore Points To Keep\n")
	script.WriteString("                                    $restorePointsToKeep = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.Options -and $configBackupJob.Options.RestorePointsToKeep) {\n")
	script.WriteString("                                            $restorePointsToKeep = $configBackupJob.Options.RestorePointsToKeep\n")
	script.WriteString("                                        } elseif ($configBackupJob.RestorePointsToKeep) {\n")
	script.WriteString("                                            $restorePointsToKeep = $configBackupJob.RestorePointsToKeep\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Encryption Key\n")
	script.WriteString("                                    $encryptionKey = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.Options -and $configBackupJob.Options.EncryptionKey) {\n")
	script.WriteString("                                            $encKey = $configBackupJob.Options.EncryptionKey\n")
	script.WriteString("                                            if ($encKey -is [string]) {\n")
	script.WriteString("                                                $encryptionKey = $encKey\n")
	script.WriteString("                                            } elseif ($encKey.Name) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.Name\n")
	script.WriteString("                                            } elseif ($encKey.ToString) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } elseif ($configBackupJob.EncryptionKey) {\n")
	script.WriteString("                                            $encKey = $configBackupJob.EncryptionKey\n")
	script.WriteString("                                            if ($encKey -is [string]) {\n")
	script.WriteString("                                                $encryptionKey = $encKey\n")
	script.WriteString("                                            } elseif ($encKey.Name) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.Name\n")
	script.WriteString("                                            } elseif ($encKey.ToString) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Email Notification Settings\n")
	script.WriteString("                                    $emailAdditionalAddress = 'N/A'\n")
	script.WriteString("                                    $emailSubject = 'N/A'\n")
	script.WriteString("                                    $notifyOnSuccess = $false\n")
	script.WriteString("                                    $notifyOnWarning = $false\n")
	script.WriteString("                                    $notifyOnError = $false\n")
	script.WriteString("                                    $notifyOnLastRetryOnly = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.NotificationOptions) {\n")
	script.WriteString("                                            $notifyOpts = $configBackupJob.NotificationOptions\n")
	script.WriteString("                                            if ($notifyOpts.EmailAdditionalAddress) { $emailAdditionalAddress = $notifyOpts.EmailAdditionalAddress }\n")
	script.WriteString("                                            if ($notifyOpts.EmailSubject) { $emailSubject = $notifyOpts.EmailSubject }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnSuccess -ne $null) { $notifyOnSuccess = [bool]$notifyOpts.NotifyOnSuccess }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnWarning -ne $null) { $notifyOnWarning = [bool]$notifyOpts.NotifyOnWarning }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnError -ne $null) { $notifyOnError = [bool]$notifyOpts.NotifyOnError }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnLastRetryOnly -ne $null) { $notifyOnLastRetryOnly = [bool]$notifyOpts.NotifyOnLastRetryOnly }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get NextRun\n")
	script.WriteString("                                    $nextRun = '--'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.ScheduleOptions -and $configBackupJob.ScheduleOptions.NextRun) {\n")
	script.WriteString("                                            $nextRun = $configBackupJob.ScheduleOptions.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($configBackupJob.NextRun) {\n")
	script.WriteString("                                            $nextRun = $configBackupJob.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = $configBackupName\n")
	script.WriteString("                                        'runJobAutomatically' = $runJobAutomatically\n")
	script.WriteString("                                        'scheduleType' = $scheduleType\n")
	script.WriteString("                                        'schedulePeriod' = $schedulePeriod\n")
	script.WriteString("                                        'scheduleDayOfWeek' = $scheduleDayOfWeek\n")
	script.WriteString("                                        'restorePointsToKeep' = $restorePointsToKeep\n")
	script.WriteString("                                        'encryptionKey' = $encryptionKey\n")
	script.WriteString("                                        'emailAdditionalAddress' = $emailAdditionalAddress\n")
	script.WriteString("                                        'emailSubject' = $emailSubject\n")
	script.WriteString("                                        'notifyOnSuccess' = $notifyOnSuccess\n")
	script.WriteString("                                        'notifyOnWarning' = $notifyOnWarning\n")
	script.WriteString("                                        'notifyOnError' = $notifyOnError\n")
	script.WriteString("                                        'notifyOnLastRetryOnly' = $notifyOnLastRetryOnly\n")
	script.WriteString("                                        'nextRun' = $nextRun\n")
	script.WriteString("                                        'enabled' = $configBackupEnabled\n")
	script.WriteString("                                        'lastResult' = $configBackupLastResult\n")
	script.WriteString("                                        'encrypted' = $configBackupEncrypted\n")
	script.WriteString("                                        'target' = $configBackupTarget\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    # If no config backup job found, set defaults\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = 'N/A'\n")
	script.WriteString("                                        'enabled' = $false\n")
	script.WriteString("                                        'scheduleType' = 'N/A'\n")
	script.WriteString("                                        'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                        'encrypted' = $false\n")
	script.WriteString("                                        'nextRun' = '--'\n")
	script.WriteString("                                        'target' = 'N/A'\n")
	script.WriteString("                                        'lastResult' = 'N/A'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {\n")
	script.WriteString("                                # On error, set defaults\n")
	script.WriteString("                                $configBackupInfo = @{\n")
	script.WriteString("                                    'name' = 'N/A'\n")
	script.WriteString("                                    'enabled' = $false\n")
	script.WriteString("                                    'scheduleType' = 'N/A'\n")
	script.WriteString("                                    'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                    'encrypted' = $false\n")
	script.WriteString("                                    'nextRun' = '--'\n")
	script.WriteString("                                    'target' = 'N/A'\n")
	script.WriteString("                                    'lastResult' = 'N/A'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['configBackup'] = $configBackupInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Server TLS Certificate\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting TLS Certificate Information\" -Status \"Retrieving backup server TLS certificate details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $tlsCertificate = @{}\n")
	script.WriteString("                            $friendlyName = 'N/A'\n")
	script.WriteString("                            $subjectName = 'N/A'\n")
	script.WriteString("                            $issuerName = 'N/A'\n")
	script.WriteString("                            $expirationDate = 'N/A'\n")
	script.WriteString("                            $issuedDate = 'N/A'\n")
	script.WriteString("                            $thumbprint = 'N/A'\n")
	script.WriteString("                            $serialNumber = 'N/A'\n")
	script.WriteString("                            \n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get certificate from Veeam Backup Server\n")
	script.WriteString("                                $cert = Get-VBRBackupServerCertificate -ErrorAction SilentlyContinue\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($cert) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get FriendlyName\n")
	script.WriteString("                                        if ($cert.FriendlyName) { $friendlyName = $cert.FriendlyName.ToString() }\n")
	script.WriteString("                                        elseif ($cert.Name) { $friendlyName = $cert.Name.ToString() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Subject\n")
	script.WriteString("                                        if ($cert.SubjectName) {\n")
	script.WriteString("                                            if ($cert.SubjectName -is [string]) { $subjectName = $cert.SubjectName }\n")
	script.WriteString("                                            else { $subjectName = $cert.SubjectName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Subject) {\n")
	script.WriteString("                                            if ($cert.Subject -is [string]) { $subjectName = $cert.Subject }\n")
	script.WriteString("                                            else { $subjectName = $cert.Subject.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SubjectName) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.SubjectName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Subject) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.Subject.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issuer\n")
	script.WriteString("                                        if ($cert.IssuerName) {\n")
	script.WriteString("                                            if ($cert.IssuerName -is [string]) { $issuerName = $cert.IssuerName }\n")
	script.WriteString("                                            else { $issuerName = $cert.IssuerName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Issuer) {\n")
	script.WriteString("                                            if ($cert.Issuer -is [string]) { $issuerName = $cert.Issuer }\n")
	script.WriteString("                                            else { $issuerName = $cert.Issuer.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.IssuerName) {\n")
	script.WriteString("                                            $issuerName = $cert.Certificate.IssuerName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Issuer) {\n")
	script.WriteString("                                            $issuerName = $cert.Certificate.Issuer.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Expiration Date\n")
	script.WriteString("                                        if ($cert.NotAfter) { $expirationDate = $cert.NotAfter.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.ExpirationDate) { $expirationDate = $cert.ExpirationDate.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.NotAfter) { $expirationDate = $cert.Certificate.NotAfter.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issued Date\n")
	script.WriteString("                                        if ($cert.NotBefore) { $issuedDate = $cert.NotBefore.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.IssueDate) { $issuedDate = $cert.IssueDate.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.NotBefore) { $issuedDate = $cert.Certificate.NotBefore.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Thumbprint\n")
	script.WriteString("                                        if ($cert.Thumbprint) { $thumbprint = $cert.Thumbprint.ToUpper() }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Thumbprint) { $thumbprint = $cert.Certificate.Thumbprint.ToUpper() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Serial Number\n")
	script.WriteString("                                        if ($cert.SerialNumber) { $serialNumber = $cert.SerialNumber.ToUpper() }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SerialNumber) { $serialNumber = $cert.Certificate.SerialNumber.ToUpper() }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            $tlsCertificate = @{\n")
	script.WriteString("                                'friendlyName' = $friendlyName\n")
	script.WriteString("                                'subjectName' = $subjectName\n")
	script.WriteString("                                'issuerName' = $issuerName\n")
	script.WriteString("                                'expirationDate' = $expirationDate\n")
	script.WriteString("                                'issuedDate' = $issuedDate\n")
	script.WriteString("                                'thumbprint' = $thumbprint\n")
	script.WriteString("                                'serialNumber' = $serialNumber\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['tlsCertificate'] = $tlsCertificate\n")
	script.WriteString("                        } catch {\n")
	script.WriteString("                            $veeamInfo['tlsCertificate'] = @{\n")
	script.WriteString("                                'friendlyName' = 'N/A'\n")
	script.WriteString("                                'subjectName' = 'N/A'\n")
	script.WriteString("                                'issuerName' = 'N/A'\n")
	script.WriteString("                                'expirationDate' = 'N/A'\n")
	script.WriteString("                                'issuedDate' = 'N/A'\n")
	script.WriteString("                                'thumbprint' = 'N/A'\n")
	script.WriteString("                                'serialNumber' = 'N/A'\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get License Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting License Information\" -Status \"Retrieving license details and usage statistics\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $license = Get-VBRInstalledLicense -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($license) {\n")
	script.WriteString("                                # Convert Edition enum to name\n")
	script.WriteString("                                $editionName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $editionValue = $license.Edition\n")
	script.WriteString("                                    $editionStr = $editionValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $editionInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($editionStr, [ref]$editionInt)) {\n")
	script.WriteString("                                        switch ($editionInt) {\n")
	script.WriteString("                                            0 { $editionName = 'Standard' }\n")
	script.WriteString("                                            1 { $editionName = 'Enterprise' }\n")
	script.WriteString("                                            2 { $editionName = 'EnterprisePlus' }\n")
	script.WriteString("                                            3 { $editionName = 'Foundation' }\n")
	script.WriteString("                                            default { $editionName = \"Edition_$editionInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($editionValue -is [enum]) {\n")
	script.WriteString("                                        $editionName = $editionStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $editionName = $editionStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $editionName = if ($license.Edition) { $license.Edition.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Convert Status enum to name\n")
	script.WriteString("                                $statusName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $statusValue = $license.Status\n")
	script.WriteString("                                    $statusStr = $statusValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $statusInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($statusStr, [ref]$statusInt)) {\n")
	script.WriteString("                                        switch ($statusInt) {\n")
	script.WriteString("                                            0 { $statusName = 'Valid' }\n")
	script.WriteString("                                            1 { $statusName = 'Expired' }\n")
	script.WriteString("                                            2 { $statusName = 'ExpiringSoon' }\n")
	script.WriteString("                                            3 { $statusName = 'Invalid' }\n")
	script.WriteString("                                            default { $statusName = \"Status_$statusInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($statusValue -is [enum]) {\n")
	script.WriteString("                                        $statusName = $statusStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $statusName = $statusStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $statusName = if ($license.Status) { $license.Status.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Convert Type enum to name\n")
	script.WriteString("                                $typeName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $typeValue = $license.Type\n")
	script.WriteString("                                    $typeStr = $typeValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $typeInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($typeStr, [ref]$typeInt)) {\n")
	script.WriteString("                                        switch ($typeInt) {\n")
	script.WriteString("                                            0 { $typeName = 'Perpetual' }\n")
	script.WriteString("                                            1 { $typeName = 'Subscription' }\n")
	script.WriteString("                                            2 { $typeName = 'Rental' }\n")
	script.WriteString("                                            3 { $typeName = 'NFR' }\n")
	script.WriteString("                                            4 { $typeName = 'Trial' }\n")
	script.WriteString("                                            5 { $typeName = 'Free' }\n")
	script.WriteString("                                            default { $typeName = \"Type_$typeInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($typeValue -is [enum]) {\n")
	script.WriteString("                                        $typeName = $typeStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $typeName = $typeStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $typeName = if ($license.Type) { $license.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                $veeamInfo['license'] = @{\n")
	script.WriteString("                                    'licensedTo' = $license.LicensedTo\n")
	script.WriteString("                                    'edition' = $editionName\n")
	script.WriteString("                                    'expirationDate' = if ($license.ExpirationDate) { $license.ExpirationDate.ToString('yyyy-MM-dd HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                    'type' = $typeName\n")
	script.WriteString("                                    'status' = $statusName\n")
	script.WriteString("                                    'licensedSockets' = if ($license.SocketLicenseSummary) { $license.SocketLicenseSummary.LicensedSocketsNumber } else { 0 }\n")
	script.WriteString("                                    'usedSockets' = if ($license.SocketLicenseSummary) { $license.SocketLicenseSummary.UsedSocketsNumber } else { 0 }\n")
	script.WriteString("                                    'licensedInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.LicensedInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'usedInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.UsedInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'newInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.NewInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'rentalInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.RentalInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'licensedNas' = if ($license.CapacityLicenseSummary) { $license.CapacityLicenseSummary.LicensedCapacityTb } else { 0 }\n")
	script.WriteString("                                    'usedNas' = if ($license.CapacityLicenseSummary) { $license.CapacityLicenseSummary.UsedCapacityTb } else { 0 }\n")
	script.WriteString("                                    'supportExpirationDate' = if ($license.SupportExpirationDate) { $license.SupportExpirationDate.ToString('yyyy-MM-dd HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                    'cloudConnectEnabled' = if ($license.CloudConnect) { $license.CloudConnect.ToString() } else { 'Disabled' }\n")
	script.WriteString("                                    'supportId' = if ($license.SupportId) { $license.SupportId.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    'autoUpdateEnabled' = if ($license.AutoUpdateEnabled -ne $null) { $license.AutoUpdateEnabled.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    'freeAgentInstance' = if ($license.FreeAgentInstance -ne $null) { $license.FreeAgentInstance.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Veeam Services Status\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Services Status\" -Status \"Checking Veeam service status and health\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $veeamServices = @()\n")
	script.WriteString("                            $allServices = Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*Veeam*' }\n")
	script.WriteString("                            if ($allServices) {\n")
	script.WriteString("                                foreach ($svc in $allServices) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $status = 'N/A'\n")
	script.WriteString("                                        if ($svc.Status) {\n")
	script.WriteString("                                            $status = $svc.Status.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        $veeamServices += @{\n")
	script.WriteString("                                            'displayName' = if ($svc.DisplayName) { $svc.DisplayName } else { 'N/A' }\n")
	script.WriteString("                                            'shortName' = if ($svc.Name) { $svc.Name } else { 'N/A' }\n")
	script.WriteString("                                            'status' = $status\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['servicesStatus'] = $veeamServices\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Enterprise Manager Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Enterprise Manager Information\" -Status \"Gathering Enterprise Manager connection details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $emInfo = @{}\n")
	script.WriteString("                            $emServerName = 'N/A'\n")
	script.WriteString("                            $emServerUrl = 'N/A'\n")
	script.WriteString("                            $emSkipLicensePush = 'N/A'\n")
	script.WriteString("                            $emIsConnected = 'No'\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 1: Try Get-VBREmServer\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $emServer = Get-VBREmServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($emServer) {\n")
	script.WriteString("                                    $emServerName = if ($emServer.Name) { $emServer.Name } else { 'N/A' }\n")
	script.WriteString("                                    $emServerUrl = if ($emServer.Url) { $emServer.Url } else { 'N/A' }\n")
	script.WriteString("                                    $emSkipLicensePush = if ($emServer.SkipLicensePush -ne $null) { $emServer.SkipLicensePush.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    $emIsConnected = if ($emServer.IsConnected -ne $null) { $emServer.IsConnected.ToString() } else { 'No' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 2: Try Get-VBREmConnection if Method 1 failed\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emConnection = Get-VBREmConnection -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($emConnection) {\n")
	script.WriteString("                                        if ($emServerName -eq 'N/A') { $emServerName = if ($emConnection.ServerName) { $emConnection.ServerName } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emServerUrl -eq 'N/A') { $emServerUrl = if ($emConnection.Url) { $emConnection.Url } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emSkipLicensePush -eq 'N/A') { $emSkipLicensePush = if ($emConnection.SkipLicensePush -ne $null) { $emConnection.SkipLicensePush.ToString() } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emIsConnected -eq 'No') { $emIsConnected = if ($emConnection.IsConnected -ne $null) { $emConnection.IsConnected.ToString() } else { 'No' } }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 3: Try .NET classes directly\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emServerObj = [Veeam.Backup.DBManager.CDBManager]::Instance.EmServer\n")
	script.WriteString("                                    if ($emServerObj) {\n")
	script.WriteString("                                        if ($emServerName -eq 'N/A') { $emServerName = if ($emServerObj.Name) { $emServerObj.Name } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emServerUrl -eq 'N/A') { $emServerUrl = if ($emServerObj.Url) { $emServerObj.Url } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emSkipLicensePush -eq 'N/A') { $emSkipLicensePush = if ($emServerObj.SkipLicensePush -ne $null) { $emServerObj.SkipLicensePush.ToString() } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emIsConnected -eq 'No') { $emIsConnected = if ($emServerObj.IsConnected -ne $null) { $emServerObj.IsConnected.ToString() } else { 'No' } }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 4: Try registry\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emRegPath = 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\EnterpriseManager'\n")
	script.WriteString("                                    if (Test-Path $emRegPath) {\n")
	script.WriteString("                                        $emReg = Get-ItemProperty -Path $emRegPath -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($emReg) {\n")
	script.WriteString("                                            if ($emServerName -eq 'N/A' -and $emReg.ServerName) { $emServerName = $emReg.ServerName }\n")
	script.WriteString("                                            if ($emServerUrl -eq 'N/A' -and $emReg.Url) { $emServerUrl = $emReg.Url }\n")
	script.WriteString("                                            if ($emSkipLicensePush -eq 'N/A' -and $emReg.SkipLicensePush -ne $null) { $emSkipLicensePush = $emReg.SkipLicensePush.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $emInfo['serverName'] = $emServerName\n")
	script.WriteString("                            $emInfo['serverUrl'] = $emServerUrl\n")
	script.WriteString("                            $emInfo['skipLicensePush'] = $emSkipLicensePush\n")
	script.WriteString("                            $emInfo['isConnected'] = $emIsConnected\n")
	script.WriteString("                            $veeamInfo['enterpriseManager'] = $emInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Email Notification Settings\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Email Notification Settings\" -Status \"Getting email notification configuration\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $emailInfo = @{}\n")
	script.WriteString("                            $emailConfig = Get-VBRMailNotificationConfiguration -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($emailConfig) {\n")
	script.WriteString("                                $emailRecipient = if ($emailConfig.Recipient) { $emailConfig.Recipient } else { 'N/A' }\n")
	script.WriteString("                                $emailSender = if ($emailConfig.Sender) { $emailConfig.Sender } else { 'N/A' }\n")
	script.WriteString("                                $smtpServer = if ($emailConfig.SmtpServer) { $emailConfig.SmtpServer } else { 'N/A' }\n")
	script.WriteString("                                $emailSubject = if ($emailConfig.Subject) { $emailConfig.Subject } else { 'N/A' }\n")
	script.WriteString("                                $sslEnabled = if ($emailConfig.SSLEnabled -ne $null) { if ($emailConfig.SSLEnabled) { 'Yes' } else { 'No' } } else { 'N/A' }\n")
	script.WriteString("                                $authEnabled = if ($emailConfig.AuthEnabled -ne $null) { if ($emailConfig.AuthEnabled) { 'Yes' } else { 'No' } } else { 'N/A' }\n")
	script.WriteString("                                $credentials = if ($emailConfig.Credentials -and $emailConfig.Credentials.UserName) { $emailConfig.Credentials.UserName } elseif ($emailConfig.Credentials) { $emailConfig.Credentials.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $dailyReportsTime = if ($emailConfig.DailyReportsTime) { $emailConfig.DailyReportsTime.ToString('HH:mm') } else { 'N/A' }\n")
	script.WriteString("                                $smtpPort = if ($emailConfig.Port) { $emailConfig.Port.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $smtpTimeout = if ($emailConfig.Timeout) { $emailConfig.Timeout.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $enabled = if ($emailConfig.Enabled -ne $null) { if ($emailConfig.Enabled) { 'Yes' } else { 'No' } } else { 'No' }\n")
	script.WriteString("                                $notifyOnSuccess = if ($emailConfig.NotifyOnSuccess -ne $null) { if ($emailConfig.NotifyOnSuccess) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnWarning = if ($emailConfig.NotifyOnWarning -ne $null) { if ($emailConfig.NotifyOnWarning) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnFailure = if ($emailConfig.NotifyOnFailure -ne $null) { if ($emailConfig.NotifyOnFailure) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnLastRetryOnly = if ($emailConfig.NotifyOnLastRetryOnly -ne $null) { if ($emailConfig.NotifyOnLastRetryOnly) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                            } else {\n")
	script.WriteString("                                $emailRecipient = 'N/A'\n")
	script.WriteString("                                $emailSender = 'N/A'\n")
	script.WriteString("                                $smtpServer = 'N/A'\n")
	script.WriteString("                                $emailSubject = 'N/A'\n")
	script.WriteString("                                $sslEnabled = 'N/A'\n")
	script.WriteString("                                $authEnabled = 'N/A'\n")
	script.WriteString("                                $credentials = 'N/A'\n")
	script.WriteString("                                $dailyReportsTime = 'N/A'\n")
	script.WriteString("                                $smtpPort = 'N/A'\n")
	script.WriteString("                                $smtpTimeout = 'N/A'\n")
	script.WriteString("                                $enabled = 'No'\n")
	script.WriteString("                                $notifyOnSuccess = 'N/A'\n")
	script.WriteString("                                $notifyOnWarning = 'N/A'\n")
	script.WriteString("                                $notifyOnFailure = 'N/A'\n")
	script.WriteString("                                $notifyOnLastRetryOnly = 'N/A'\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Detect SMTP Server Type\n")
	script.WriteString("                            $smtpType = 'N/A'\n")
	script.WriteString("                            if ($smtpServer -ne 'N/A' -and $smtpServer) {\n")
	script.WriteString("                                $smtpLower = $smtpServer.ToLower()\n")
	script.WriteString("                                if ($smtpLower -like '*outlook*' -or $smtpLower -like '*office365*' -or $smtpLower -like '*office.com*' -or $smtpLower -like '*smtp.office365.com*') {\n")
	script.WriteString("                                    $smtpType = 'Office365'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*gmail*' -or $smtpLower -like '*google*' -or $smtpLower -like '*smtp.gmail.com*') {\n")
	script.WriteString("                                    $smtpType = 'Gmail'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*exchange*' -or $smtpLower -like '*mail.office365.com*') {\n")
	script.WriteString("                                    $smtpType = 'Exchange'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*azure*') {\n")
	script.WriteString("                                    $smtpType = 'Azure'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*yahoo*' -or $smtpLower -like '*smtp.mail.yahoo.com*') {\n")
	script.WriteString("                                    $smtpType = 'Yahoo'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*smtp*') {\n")
	script.WriteString("                                    $smtpType = 'SMTP'\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $smtpType = 'Custom'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $emailInfo['emailRecipient'] = $emailRecipient\n")
	script.WriteString("                            $emailInfo['emailSender'] = $emailSender\n")
	script.WriteString("                            $emailInfo['smtpServer'] = $smtpServer\n")
	script.WriteString("                            $emailInfo['smtpType'] = $smtpType\n")
	script.WriteString("                            $emailInfo['emailSubject'] = $emailSubject\n")
	script.WriteString("                            $emailInfo['sslEnabled'] = $sslEnabled\n")
	script.WriteString("                            $emailInfo['authEnabled'] = $authEnabled\n")
	script.WriteString("                            $emailInfo['credentials'] = $credentials\n")
	script.WriteString("                            $emailInfo['dailyReportsTime'] = $dailyReportsTime\n")
	script.WriteString("                            $emailInfo['smtpPort'] = $smtpPort\n")
	script.WriteString("                            $emailInfo['smtpTimeout'] = $smtpTimeout\n")
	script.WriteString("                            $emailInfo['enabled'] = $enabled\n")
	script.WriteString("                            $emailInfo['notifyOnSuccess'] = $notifyOnSuccess\n")
	script.WriteString("                            $emailInfo['notifyOnWarning'] = $notifyOnWarning\n")
	script.WriteString("                            $emailInfo['notifyOnFailure'] = $notifyOnFailure\n")
	script.WriteString("                            $emailInfo['notifyOnLastRetryOnly'] = $notifyOnLastRetryOnly\n")
	script.WriteString("                            $veeamInfo['emailNotification'] = $emailInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Repositories\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Repositories\" -Status \"Enumerating backup repositories\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $repositories = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $repoList = @()\n")
	script.WriteString("                            foreach ($repo in $repositories) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Convert Type enum to name\n")
	script.WriteString("                                    $typeName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $typeValue = $repo.Type\n")
	script.WriteString("                                        if ($typeValue -is [enum]) {\n")
	script.WriteString("                                            $typeName = $typeValue.ToString()\n")
	script.WriteString("                                        } elseif ($typeValue -is [int] -or $typeValue -is [System.Int32]) {\n")
	script.WriteString("                                            switch ([int]$typeValue) {\n")
	script.WriteString("                                                0 { $typeName = 'Windows' }\n")
	script.WriteString("                                                1 { $typeName = 'Linux' }\n")
	script.WriteString("                                                2 { $typeName = 'SharedFolder' }\n")
	script.WriteString("                                                3 { $typeName = 'DedupeStorage' }\n")
	script.WriteString("                                                4 { $typeName = 'Cloud' }\n")
	script.WriteString("                                                default { $typeName = \"Type_$typeValue\" }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $typeName = if ($typeValue) { $typeValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {\n")
	script.WriteString("                                        $typeName = if ($repo.Type) { $repo.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Convert Status enum to name\n")
	script.WriteString("                                    $statusName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $statusValue = $repo.Status\n")
	script.WriteString("                                        if ($statusValue -is [enum]) {\n")
	script.WriteString("                                            $statusName = $statusValue.ToString()\n")
	script.WriteString("                                        } elseif ($statusValue -is [int] -or $statusValue -is [System.Int32]) {\n")
	script.WriteString("                                            switch ([int]$statusValue) {\n")
	script.WriteString("                                                0 { $statusName = 'Available' }\n")
	script.WriteString("                                                1 { $statusName = 'Unavailable' }\n")
	script.WriteString("                                                2 { $statusName = 'Maintenance' }\n")
	script.WriteString("                                                default { $statusName = \"Status_$statusValue\" }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $statusName = if ($statusValue) { $statusValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {\n")
	script.WriteString("                                        $statusName = if ($repo.Status) { $repo.Status.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Skip SOBR repositories\n")
	script.WriteString("                                    if ($repo.IsScaleOut -eq $true) { continue }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get space information\n")
	script.WriteString("                                    $cachedTotalSpaceGB = 0\n")
	script.WriteString("                                    $cachedFreeSpaceGB = 0\n")
	script.WriteString("                                    $freeSpacePercent = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $container = $repo.getcontainer()\n")
	script.WriteString("                                        if ($container) {\n")
	script.WriteString("                                            if ($container.CachedTotalSpace) {\n")
	script.WriteString("                                                $cachedTotalSpaceGB = [math]::Round($container.CachedTotalSpace.ingigabytes, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($container.CachedFreeSpace) {\n")
	script.WriteString("                                                $cachedFreeSpaceGB = [math]::Round($container.CachedFreeSpace.ingigabytes, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($cachedTotalSpaceGB -gt 0) {\n")
	script.WriteString("                                                $freeSpacePercent = [math]::Round(($cachedFreeSpaceGB / $cachedTotalSpaceGB) * 100, 1)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Job Count\n")
	script.WriteString("                                    $jobCount = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($jobs) {\n")
	script.WriteString("                                            foreach ($job in $jobs) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    if ($job.TargetRepositoryId -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                    elseif ($job.TargetRepository -and $job.TargetRepository.Id -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                    elseif ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.TargetRepositoryId -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Set Tasks\n")
	script.WriteString("                                    $setTasks = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.ScheduleOptions -and $repo.ScheduleOptions.Enabled) { $setTasks = 1 }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Host information\n")
	script.WriteString("                                    $hostNames = @()\n")
	script.WriteString("                                    $hostName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Host) {\n")
	script.WriteString("                                            $hostName = $repo.Host.Name\n")
	script.WriteString("                                            $hostNames += $repo.Host.Name\n")
	script.WriteString("                                        } elseif ($repo.Hosts) {\n")
	script.WriteString("                                            foreach ($h in $repo.Hosts) {\n")
	script.WriteString("                                                if ($h.Name) { $hostNames += $h.Name }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $hostName = $hostNames -join ', '\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Path\n")
	script.WriteString("                                    $path = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Path) { $path = $repo.Path }\n")
	script.WriteString("                                        elseif ($repo.FriendlyPath) { $path = $repo.FriendlyPath }\n")
	script.WriteString("                                        elseif ($repo.RepositoryPath) { $path = $repo.RepositoryPath }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Cores and RAM from host\n")
	script.WriteString("                                    $cores = 0\n")
	script.WriteString("                                    $ram = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Host) {\n")
	script.WriteString("                                            $hostInfo = $repo.Host\n")
	script.WriteString("                                            if ($hostInfo.CpuCount) { $cores = $hostInfo.CpuCount }\n")
	script.WriteString("                                            elseif ($hostInfo.Cores) { $cores = $hostInfo.Cores }\n")
	script.WriteString("                                            if ($hostInfo.Memory) { $ram = [math]::Round($hostInfo.Memory / 1GB, 0) }\n")
	script.WriteString("                                            elseif ($hostInfo.Ram) { $ram = [math]::Round($hostInfo.Ram / 1GB, 0) }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Auto Gateway\n")
	script.WriteString("                                    $autoGateway = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.AutoGateway) { $autoGateway = $repo.Options.AutoGateway }\n")
	script.WriteString("                                        elseif ($repo.AutoGateway) { $autoGateway = $repo.AutoGateway }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Per-VM\n")
	script.WriteString("                                    $perVM = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.UsePerVMBackupFiles) { $perVM = $repo.Options.UsePerVMBackupFiles }\n")
	script.WriteString("                                        elseif ($repo.UsePerVMBackupFiles) { $perVM = $repo.UsePerVMBackupFiles }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get DeCompress\n")
	script.WriteString("                                    $decompress = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.DecompressBeforeStorage) { $decompress = $repo.Options.DecompressBeforeStorage }\n")
	script.WriteString("                                        elseif ($repo.DecompressBeforeStorage) { $decompress = $repo.DecompressBeforeStorage }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Align Blocks\n")
	script.WriteString("                                    $alignBlocks = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.AlignDataBlocks) { $alignBlocks = $repo.Options.AlignDataBlocks }\n")
	script.WriteString("                                        elseif ($repo.AlignDataBlocks) { $alignBlocks = $repo.AlignDataBlocks }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Rotated Drives\n")
	script.WriteString("                                    $rotatedDrives = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.RotatedDrives) { $rotatedDrives = $repo.Options.RotatedDrives }\n")
	script.WriteString("                                        elseif ($repo.RotatedDrives) { $rotatedDrives = $repo.RotatedDrives }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Use Immutability\n")
	script.WriteString("                                    $useImmutability = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.ImmutabilityEnabled) { $useImmutability = $repo.Options.ImmutabilityEnabled }\n")
	script.WriteString("                                        elseif ($repo.ImmutabilityEnabled) { $useImmutability = $repo.ImmutabilityEnabled }\n")
	script.WriteString("                                        elseif ($repo.IsImmutabilityEnabled) { $useImmutability = $repo.IsImmutabilityEnabled }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $repoList += @{\n")
	script.WriteString("                                        'Id' = $repo.Id\n")
	script.WriteString("                                        'Name' = $repo.Name\n")
	script.WriteString("                                        'Type' = $typeName\n")
	script.WriteString("                                        'Status' = $statusName\n")
	script.WriteString("                                        'IsUnavailable' = if ($repo.IsUnavailable -ne $null) { $repo.IsUnavailable } else { $false }\n")
	script.WriteString("                                        'CachedTotalSpaceGB' = $cachedTotalSpaceGB\n")
	script.WriteString("                                        'CachedFreeSpaceGB' = $cachedFreeSpaceGB\n")
	script.WriteString("                                        'FreeSpacePercent' = $freeSpacePercent\n")
	script.WriteString("                                        'JobCount' = $jobCount\n")
	script.WriteString("                                        'SetTasks' = $setTasks\n")
	script.WriteString("                                        'Cores' = $cores\n")
	script.WriteString("                                        'Ram' = $ram\n")
	script.WriteString("                                        'AutoGateway' = $autoGateway\n")
	script.WriteString("                                        'Host' = $hostName\n")
	script.WriteString("                                        'Hosts' = $hostNames\n")
	script.WriteString("                                        'Path' = $path\n")
	script.WriteString("                                        'PerVM' = $perVM\n")
	script.WriteString("                                        'Decompress' = $decompress\n")
	script.WriteString("                                        'AlignBlocks' = $alignBlocks\n")
	script.WriteString("                                        'RotatedDrives' = $rotatedDrives\n")
	script.WriteString("                                        'UseImmutability' = $useImmutability\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $repoList += @{\n")
	script.WriteString("                                        'Id' = $repo.Id\n")
	script.WriteString("                                        'Name' = $repo.Name\n")
	script.WriteString("                                        'Type' = 'N/A'\n")
	script.WriteString("                                        'Status' = 'N/A'\n")
	script.WriteString("                                        'Error' = 'Failed to collect detailed information'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['repositories'] = $repoList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Scale-Out Backup Repositories (SOBR)\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Scale-Out Backup Repositories\" -Status \"Enumerating SOBR repositories and policies\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $sobrs = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $sobrList = @()\n")
	script.WriteString("                            $sobrExtentsList = @()\n")
	script.WriteString("                            if ($sobrs) {\n")
	script.WriteString("                                foreach ($sobr in $sobrs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $sobrName = $sobr.Name\n")
	script.WriteString("                                        $sobrId = $sobr.Id\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $extentsCount = 0\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.Extents) { $extentsCount = $sobr.Extents.Count }\n")
	script.WriteString("                                            elseif ($sobr.GetExtents) { $extentsCount = ($sobr.GetExtents()).Count }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $jobCount = 0\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($jobs) {\n")
	script.WriteString("                                                foreach ($job in $jobs) {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        if ($job.TargetRepositoryId -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                        elseif ($job.TargetRepository -and $job.TargetRepository.Id -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                        elseif ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.TargetRepositoryId -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $policy = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.PolicyType) { $policy = $sobr.PolicyType.ToString() }\n")
	script.WriteString("                                            elseif ($sobr.Policy) { $policy = $sobr.Policy.ToString() }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $capacityTier = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.EnableCapacityTier) { $capacityTier = $sobr.EnableCapacityTier }\n")
	script.WriteString("                                            elseif ($sobr.CapacityTierEnabled) { $capacityTier = $sobr.CapacityTierEnabled }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $copyEnabled = $false\n")
	script.WriteString("                                        $moveEnabled = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions) {\n")
	script.WriteString("                                                $copyEnabled = $sobr.CapacityTierOptions.CopyEnabled\n")
	script.WriteString("                                                $moveEnabled = $sobr.CapacityTierOptions.MoveEnabled\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $archiveTier = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.ArchiveTierEnabled) { $archiveTier = $sobr.ArchiveTierEnabled }\n")
	script.WriteString("                                            elseif ($sobr.EnableArchiveTier) { $archiveTier = $sobr.EnableArchiveTier }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $perMachine = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.UsePerVMBackupFiles) { $perMachine = $sobr.UsePerVMBackupFiles }\n")
	script.WriteString("                                            elseif ($sobr.PerVMBackupFiles) { $perMachine = $sobr.PerVMBackupFiles }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $capTierType = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.TierType) {\n")
	script.WriteString("                                                $capTierType = $sobr.CapacityTierOptions.TierType.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $immutable = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.ImmutabilityEnabled) {\n")
	script.WriteString("                                                $immutable = $sobr.CapacityTierOptions.ImmutabilityEnabled\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $immutablePeriod = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.ImmutabilityPeriodDays) {\n")
	script.WriteString("                                                $immutablePeriod = $sobr.CapacityTierOptions.ImmutabilityPeriodDays\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sizeLimitEnabled = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.SizeLimitEnabled) { $sizeLimitEnabled = $sobr.SizeLimitEnabled }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sizeLimit = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.SizeLimit) {\n")
	script.WriteString("                                                $sizeLimit = [math]::Round($sobr.SizeLimit / 1GB, 0)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sobrList += @{\n")
	script.WriteString("                                            'Id' = $sobrId\n")
	script.WriteString("                                            'Name' = $sobrName\n")
	script.WriteString("                                            'Extents' = $extentsCount\n")
	script.WriteString("                                            'JobCount' = $jobCount\n")
	script.WriteString("                                            'Policy' = $policy\n")
	script.WriteString("                                            'CapacityTier' = $capacityTier\n")
	script.WriteString("                                            'Copy' = $copyEnabled\n")
	script.WriteString("                                            'Move' = $moveEnabled\n")
	script.WriteString("                                            'ArchiveTier' = $archiveTier\n")
	script.WriteString("                                            'PerMachine' = $perMachine\n")
	script.WriteString("                                            'CapTierType' = $capTierType\n")
	script.WriteString("                                            'Immutable' = $immutable\n")
	script.WriteString("                                            'ImmutablePeriod' = $immutablePeriod\n")
	script.WriteString("                                            'SizeLimitEnabled' = $sizeLimitEnabled\n")
	script.WriteString("                                            'SizeLimit' = $sizeLimit\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $extents = $null\n")
	script.WriteString("                                            if ($sobr.Extents) { $extents = $sobr.Extents }\n")
	script.WriteString("                                            elseif ($sobr.GetExtents) { $extents = $sobr.GetExtents() }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            if ($extents) {\n")
	script.WriteString("                                                foreach ($extent in $extents) {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        $extentRepo = $null\n")
	script.WriteString("                                                        if ($extent.Repository) { $extentRepo = $extent.Repository }\n")
	script.WriteString("                                                        elseif ($extent.BackupRepository) { $extentRepo = $extent.BackupRepository }\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        if ($extentRepo) {\n")
	script.WriteString("                                                            $extentTotalSpaceGB = 0\n")
	script.WriteString("                                                            $extentFreeSpaceGB = 0\n")
	script.WriteString("                                                            $extentFreeSpacePercent = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $container = $extentRepo.getcontainer()\n")
	script.WriteString("                                                                if ($container) {\n")
	script.WriteString("                                                                    if ($container.CachedTotalSpace) {\n")
	script.WriteString("                                                                        $extentTotalSpaceGB = [math]::Round($container.CachedTotalSpace.ingigabytes, 2)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    if ($container.CachedFreeSpace) {\n")
	script.WriteString("                                                                        $extentFreeSpaceGB = [math]::Round($container.CachedFreeSpace.ingigabytes, 2)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    if ($extentTotalSpaceGB -gt 0) {\n")
	script.WriteString("                                                                        $extentFreeSpacePercent = [math]::Round(($extentFreeSpaceGB / $extentTotalSpaceGB) * 100, 1)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentSetTasks = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.ScheduleOptions -and $extentRepo.ScheduleOptions.Enabled) { $extentSetTasks = 1 }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentHostNames = @()\n")
	script.WriteString("                                                            $extentHostName = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Host) {\n")
	script.WriteString("                                                                    $extentHostName = $extentRepo.Host.Name\n")
	script.WriteString("                                                                    $extentHostNames += $extentRepo.Host.Name\n")
	script.WriteString("                                                                } elseif ($extentRepo.Hosts) {\n")
	script.WriteString("                                                                    foreach ($h in $extentRepo.Hosts) {\n")
	script.WriteString("                                                                        if ($h.Name) { $extentHostNames += $h.Name }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    $extentHostName = $extentHostNames -join ', '\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentPath = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Path) { $extentPath = $extentRepo.Path }\n")
	script.WriteString("                                                                elseif ($extentRepo.FriendlyPath) { $extentPath = $extentRepo.FriendlyPath }\n")
	script.WriteString("                                                                elseif ($extentRepo.RepositoryPath) { $extentPath = $extentRepo.RepositoryPath }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentCores = 0\n")
	script.WriteString("                                                            $extentRam = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Host) {\n")
	script.WriteString("                                                                    $hostInfo = $extentRepo.Host\n")
	script.WriteString("                                                                    if ($hostInfo.CpuCount) { $extentCores = $hostInfo.CpuCount }\n")
	script.WriteString("                                                                    elseif ($hostInfo.Cores) { $extentCores = $hostInfo.Cores }\n")
	script.WriteString("                                                                    if ($hostInfo.Memory) { $extentRam = [math]::Round($hostInfo.Memory / 1GB, 0) }\n")
	script.WriteString("                                                                    elseif ($hostInfo.Ram) { $extentRam = [math]::Round($hostInfo.Ram / 1GB, 0) }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentAutoGateway = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.AutoGateway) { $extentAutoGateway = $extentRepo.Options.AutoGateway }\n")
	script.WriteString("                                                                elseif ($extentRepo.AutoGateway) { $extentAutoGateway = $extentRepo.AutoGateway }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentDecompress = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.DecompressBeforeStorage) { $extentDecompress = $extentRepo.Options.DecompressBeforeStorage }\n")
	script.WriteString("                                                                elseif ($extentRepo.DecompressBeforeStorage) { $extentDecompress = $extentRepo.DecompressBeforeStorage }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentAlignBlocks = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.AlignDataBlocks) { $extentAlignBlocks = $extentRepo.Options.AlignDataBlocks }\n")
	script.WriteString("                                                                elseif ($extentRepo.AlignDataBlocks) { $extentAlignBlocks = $extentRepo.AlignDataBlocks }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentRotatedDrives = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.RotatedDrives) { $extentRotatedDrives = $extentRepo.Options.RotatedDrives }\n")
	script.WriteString("                                                                elseif ($extentRepo.RotatedDrives) { $extentRotatedDrives = $extentRepo.RotatedDrives }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentUseImmutability = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.ImmutabilityEnabled) { $extentUseImmutability = $extentRepo.Options.ImmutabilityEnabled }\n")
	script.WriteString("                                                                elseif ($extentRepo.ImmutabilityEnabled) { $extentUseImmutability = $extentRepo.ImmutabilityEnabled }\n")
	script.WriteString("                                                                elseif ($extentRepo.IsImmutabilityEnabled) { $extentUseImmutability = $extentRepo.IsImmutabilityEnabled }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentType = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $extentTypeValue = $extentRepo.Type\n")
	script.WriteString("                                                                if ($extentTypeValue -is [enum]) {\n")
	script.WriteString("                                                                    $extentType = $extentTypeValue.ToString()\n")
	script.WriteString("                                                                } elseif ($extentTypeValue -is [int] -or $extentTypeValue -is [System.Int32]) {\n")
	script.WriteString("                                                                    switch ([int]$extentTypeValue) {\n")
	script.WriteString("                                                                        0 { $extentType = 'Windows' }\n")
	script.WriteString("                                                                        1 { $extentType = 'Linux' }\n")
	script.WriteString("                                                                        2 { $extentType = 'SharedFolder' }\n")
	script.WriteString("                                                                        3 { $extentType = 'DedupeStorage' }\n")
	script.WriteString("                                                                        4 { $extentType = 'AmazonS3Compatible' }\n")
	script.WriteString("                                                                        5 { $extentType = 'AzureBlob' }\n")
	script.WriteString("                                                                        6 { $extentType = 'AmazonS3' }\n")
	script.WriteString("                                                                        7 { $extentType = 'WasabiS3' }\n")
	script.WriteString("                                                                        default { $extentType = \"Type_$extentTypeValue\" }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $extentType = if ($extentTypeValue) { $extentTypeValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {\n")
	script.WriteString("                                                                $extentType = if ($extentRepo.Type) { $extentRepo.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $sobrExtentsList += @{\n")
	script.WriteString("                                                                'Name' = $extentRepo.Name\n")
	script.WriteString("                                                                'SOBR' = $sobrName\n")
	script.WriteString("                                                                'SetTasks' = $extentSetTasks\n")
	script.WriteString("                                                                'Cores' = $extentCores\n")
	script.WriteString("                                                                'Ram' = $extentRam\n")
	script.WriteString("                                                                'AutoGateway' = $extentAutoGateway\n")
	script.WriteString("                                                                'Host' = $extentHostName\n")
	script.WriteString("                                                                'Hosts' = $extentHostNames\n")
	script.WriteString("                                                                'Path' = $extentPath\n")
	script.WriteString("                                                                'FreeSpaceGB' = $extentFreeSpaceGB\n")
	script.WriteString("                                                                'TotalSpaceGB' = $extentTotalSpaceGB\n")
	script.WriteString("                                                                'FreeSpacePercent' = $extentFreeSpacePercent\n")
	script.WriteString("                                                                'Decompress' = $extentDecompress\n")
	script.WriteString("                                                                'AlignBlocks' = $extentAlignBlocks\n")
	script.WriteString("                                                                'RotatedDrives' = $extentRotatedDrives\n")
	script.WriteString("                                                                'UseImmutability' = $extentUseImmutability\n")
	script.WriteString("                                                                'Type' = $extentType\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['sobrs'] = $sobrList\n")
	script.WriteString("                            $veeamInfo['sobrExtents'] = $sobrExtentsList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Security Credentials\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Security Credentials\" -Status \"Enumerating managed credentials\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $credentials = Get-VBRCredentials -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $credentialsList = @()\n")
	script.WriteString("                            if ($credentials) {\n")
	script.WriteString("                                foreach ($cred in $credentials) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $credName = if ($cred.Name) { $cred.Name } else { 'N/A' }\n")
	script.WriteString("                                        $credDescription = if ($cred.Description) { $cred.Description } else { 'N/A' }\n")
	script.WriteString("                                        $credentialsList += @{\n")
	script.WriteString("                                            'name' = $credName\n")
	script.WriteString("                                            'description' = $credDescription\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['securityCredentials'] = $credentialsList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Jobs\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Jobs\" -Status \"Enumerating backup, replica, and copy jobs\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['jobs'] = @{\n")
	script.WriteString("                                'total' = $jobs.Count\n")
	script.WriteString("                                'jobList' = @($jobs | Select-Object -Property Name, JobType, @{n='ScheduleEnabled';e={$_.ScheduleOptions.Enabled}}, @{n='RestorePoints';e={$_.Options.BackupStorageOptions.RetainCycles}}, @{n='Algorithm';e={$_.Options.BackupTargetOptions.Algorithm}}, @{n='CompressionLevel';e={$_.Options.BackupStorageOptions.CompressionLevel}}, @{n='Deduplication';e={$_.Options.BackupStorageOptions.EnableDeduplication}})\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Infrastructure Types & Count\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Infrastructure Types\" -Status \"Detecting infrastructure types and counts\"\n")
	script.WriteString("                        $infrastructureTypes = @{}\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $servers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($servers) {\n")
	script.WriteString("                                foreach ($server in $servers) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $serverType = $null\n")
	script.WriteString("                                        if ($server.Type) {\n")
	script.WriteString("                                            $serverType = $server.Type.ToString()\n")
	script.WriteString("                                        } elseif ($server.Info -and $server.Info.Type) {\n")
	script.WriteString("                                            $serverType = $server.Info.Type.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        if ($serverType) {\n")
	script.WriteString("                                            if ($infrastructureTypes.ContainsKey($serverType)) {\n")
	script.WriteString("                                                $infrastructureTypes[$serverType]++\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $infrastructureTypes[$serverType] = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $infrastructureList = @()\n")
	script.WriteString("                        foreach ($key in $infrastructureTypes.Keys) {\n")
	script.WriteString("                            $infrastructureList += @{\n")
	script.WriteString("                                'name' = $key\n")
	script.WriteString("                                'count' = $infrastructureTypes[$key]\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $veeamInfo['infrastructureTypes'] = $infrastructureList\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Job Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Job Summary\" -Status \"Summarizing job types and totals\"\n")
	script.WriteString("                        $jobSummary = @{}\n")
	script.WriteString("                        $totalJobs = 0\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allJobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allJobs) {\n")
	script.WriteString("                                foreach ($job in $allJobs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $jobType = $null\n")
	script.WriteString("                                        if ($job.JobType) {\n")
	script.WriteString("                                            $jobTypeStr = $job.JobType.ToString()\n")
	script.WriteString("                                            # Normalize job types\n")
	script.WriteString("                                            if ($jobTypeStr -eq 'NasBackup' -or $jobTypeStr -eq 'ENasBackup' -or $jobTypeStr -eq 'FileBackup') {\n")
	script.WriteString("                                                $jobType = 'File Backup'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Backup') {\n")
	script.WriteString("                                                $jobType = 'Backup'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Replica') {\n")
	script.WriteString("                                                $jobType = 'Replica'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'FileCopy' -or $jobTypeStr -eq 'Copy') {\n")
	script.WriteString("                                                $jobType = 'File Copy'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'BackupCopy') {\n")
	script.WriteString("                                                $jobType = 'Backup Copy'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Tape') {\n")
	script.WriteString("                                                $jobType = 'Tape'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Plugin') {\n")
	script.WriteString("                                                $jobType = 'Plugin'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'UnmanagedAgent' -or $jobTypeStr -eq 'Agent') {\n")
	script.WriteString("                                                $jobType = 'Unmanaged Agent'\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $jobType = $jobTypeStr\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        if ($jobType) {\n")
	script.WriteString("                                            if ($jobSummary.ContainsKey($jobType)) {\n")
	script.WriteString("                                                $jobSummary[$jobType]++\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $jobSummary[$jobType] = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $totalJobs++\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $jobSummaryList = @()\n")
	script.WriteString("                        foreach ($key in $jobSummary.Keys | Sort-Object) {\n")
	script.WriteString("                            $jobSummaryList += @{\n")
	script.WriteString("                                'type' = $key\n")
	script.WriteString("                                'total' = $jobSummary[$key]\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $veeamInfo['jobSummary'] = @{\n")
	script.WriteString("                            'summary' = $jobSummaryList\n")
	script.WriteString("                            'totalJobs' = $totalJobs\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Protected Workloads\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Protected Workloads\" -Status \"Analyzing VMware, Hyper-V, and Physical workloads\"\n")
	script.WriteString("                        $protectedWorkloads = @{\n")
	script.WriteString("                            'vmware' = @{\n")
	script.WriteString("                                'viTotal' = 0\n")
	script.WriteString("                                'viProtected' = 0\n")
	script.WriteString("                                'viNotProt' = 0\n")
	script.WriteString("                                'viPotentialDupes' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                            'hyperv' = @{\n")
	script.WriteString("                                'hvTotal' = 0\n")
	script.WriteString("                                'hvProtected' = 0\n")
	script.WriteString("                                'hvUnprotected' = 0\n")
	script.WriteString("                                'hvDuplicates' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                            'physical' = @{\n")
	script.WriteString("                                'viProtectedAsPhysical' = 0\n")
	script.WriteString("                                'physTotal' = 0\n")
	script.WriteString("                                'phyProtected' = 0\n")
	script.WriteString("                                'physNotProt' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # VMware Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $vmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'VMware Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $vmNames = $null\n")
	script.WriteString("                            if ($vmbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $vmNames = $vmbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $vmNames = $vmbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $allViEntities = Find-VBRViEntity -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allViEntities) {\n")
	script.WriteString("                                $protectedWorkloads['vmware']['viTotal'] = $allViEntities.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                    $protectedEntityInfo = Find-VBRViEntity -Name $vmNames.Name -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $unprotectedEntityInfo = Find-VBRViEntity | Where-Object { $_.Name -notin $vmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protectedEntityInfo) { $protectedWorkloads['vmware']['viProtected'] = $protectedEntityInfo.Count }\n")
	script.WriteString("                                    if ($unprotectedEntityInfo) { $protectedWorkloads['vmware']['viNotProt'] = $unprotectedEntityInfo.Count }\n")
	script.WriteString("                                    $protectedWorkloads['vmware']['viPotentialDupes'] = $vmNames.Count\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['vmware']['viNotProt'] = $allViEntities.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Hyper-V Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $hvvmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'Hyper-v Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $hvvmNames = $null\n")
	script.WriteString("                            if ($hvvmbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $hvvmNames = $hvvmbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $hvvmNames = $hvvmbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $allHvEntities = Find-VBRHvEntity -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allHvEntities) {\n")
	script.WriteString("                                $protectedWorkloads['hyperv']['hvTotal'] = $allHvEntities.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($hvvmNames -and $hvvmNames.Name) {\n")
	script.WriteString("                                    $protectedHvEntityInfo = Find-VBRHvEntity -Name $hvvmNames.Name -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $unprotectedHvEntityInfo = Find-VBRHvEntity | Where-Object { $_.Name -notin $hvvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protectedHvEntityInfo) { $protectedWorkloads['hyperv']['hvProtected'] = $protectedHvEntityInfo.Count }\n")
	script.WriteString("                                    if ($unprotectedHvEntityInfo) { $protectedWorkloads['hyperv']['hvUnprotected'] = $unprotectedHvEntityInfo.Count }\n")
	script.WriteString("                                    $protectedWorkloads['hyperv']['hvDuplicates'] = $hvvmNames.Count\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['hyperv']['hvUnprotected'] = $allHvEntities.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Physical Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $physbackups = Get-VBRBackup | Where-Object { $_.TypeToString -like '*Agent*' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $pvmNames = $null\n")
	script.WriteString("                            if ($physbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $pvmNames = $physbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $pvmNames = $physbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $phys = Get-VBRComputer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($phys) {\n")
	script.WriteString("                                $protectedWorkloads['physical']['physTotal'] = $phys.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($pvmNames -and $pvmNames.Name) {\n")
	script.WriteString("                                    $protected = $phys | Where-Object { $_.Name -in $pvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $notprotected = $phys | Where-Object { $_.Name -notin $pvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protected) { $protectedWorkloads['physical']['phyProtected'] = $protected.Count }\n")
	script.WriteString("                                    if ($notprotected) { $protectedWorkloads['physical']['physNotProt'] = $notprotected.Count }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['physical']['physNotProt'] = $phys.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['protectedWorkloads'] = $protectedWorkloads\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Managed Server Info\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Managed Server Information\" -Status \"Gathering details for all managed servers\"\n")
	script.WriteString("                        $managedServers = @()\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allServers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $repos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $wanAccs = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($allServers) {\n")
	script.WriteString("                                foreach ($server in $allServers) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $serverInfo = @{\n")
	script.WriteString("                                            'name' = if ($server.Name) { $server.Name } else { 'N/A' }\n")
	script.WriteString("                                            'cores' = 0\n")
	script.WriteString("                                            'ram' = 0\n")
	script.WriteString("                                            'type' = if ($server.Type) { $server.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                            'osInfo' = 'N/A'\n")
	script.WriteString("                                            'apiVersion' = ''\n")
	script.WriteString("                                            'protectedVMs' = 0\n")
	script.WriteString("                                            'notProtectedVMs' = 0\n")
	script.WriteString("                                            'totalVMs' = 0\n")
	script.WriteString("                                            'isProxy' = $false\n")
	script.WriteString("                                            'isRepo' = $false\n")
	script.WriteString("                                            'isWANAcc' = $false\n")
	script.WriteString("                                            'isUnavailable' = if ($server.IsUnavailable -ne $null) { $server.IsUnavailable } else { $false }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get API Version (try multiple methods)\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.ApiVersion) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.ApiVersion.ToString()\n")
	script.WriteString("                                            } elseif ($server.Info -and $server.Info.ApiVersion) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.Info.ApiVersion.ToString()\n")
	script.WriteString("                                            } elseif ($server.Version) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.Version.ToString()\n")
	script.WriteString("                                            } elseif ($server.GetPhysicalHost()) {\n")
	script.WriteString("                                                $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                if ($physHost -and $physHost.ApiVersion) {\n")
	script.WriteString("                                                    $serverInfo['apiVersion'] = $physHost.ApiVersion.ToString()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Cores and RAM\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.Type -eq 'Local' -or $server.Type -eq 'Windows') {\n")
	script.WriteString("                                                # For local/Windows servers, use WMI/CIM to get system info\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $computerSystem = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($computerSystem -and $computerSystem.TotalPhysicalMemory) {\n")
	script.WriteString("                                                        # Convert bytes to GB\n")
	script.WriteString("                                                        $serverInfo['ram'] = [math]::Round($computerSystem.TotalPhysicalMemory / 1GB, 2)\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $processor = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($processor) {\n")
	script.WriteString("                                                        $totalCores = ($processor | Measure-Object -Property NumberOfCores -Sum).Sum\n")
	script.WriteString("                                                        if ($totalCores -and $totalCores -gt 0) {\n")
	script.WriteString("                                                            $serverInfo['cores'] = $totalCores\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $totalLogical = ($processor | Measure-Object -Property NumberOfLogicalProcessors -Sum).Sum\n")
	script.WriteString("                                                            if ($totalLogical -and $totalLogical -gt 0) {\n")
	script.WriteString("                                                                $serverInfo['cores'] = $totalLogical\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # Get OS Info for local server\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($os) {\n")
	script.WriteString("                                                        $serverInfo['osInfo'] = $os.Caption + ' ' + $os.OSArchitecture + ' (' + $os.Version + ' build:' + $os.BuildNumber + ')'\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                # For remote servers, use GetPhysicalHost\n")
	script.WriteString("                                                $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                if ($physHost -and $physHost.hardwareinfo) {\n")
	script.WriteString("                                                    if ($physHost.hardwareinfo.CoresCount) { $serverInfo['cores'] = $physHost.hardwareinfo.CoresCount }\n")
	script.WriteString("                                                    if ($physHost.hardwareinfo.PhysicalRamTotal) {\n")
	script.WriteString("                                                        # PhysicalRamTotal is in bytes, convert to GB\n")
	script.WriteString("                                                        $serverInfo['ram'] = [math]::Round($physHost.hardwareinfo.PhysicalRamTotal / 1GB, 2)\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get OS Info (fallback if not already set)\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($serverInfo['osInfo'] -eq 'N/A' -or -not $serverInfo['osInfo'] -or $serverInfo['osInfo'] -eq '') {\n")
	script.WriteString("                                                if ($server.Info -and $server.Info.Info) {\n")
	script.WriteString("                                                    $serverInfo['osInfo'] = $server.Info.Info\n")
	script.WriteString("                                                } elseif ($server.Info -and $server.Info.Name) {\n")
	script.WriteString("                                                    $serverInfo['osInfo'] = $server.Info.Name\n")
	script.WriteString("                                                } elseif ($server.GetPhysicalHost()) {\n")
	script.WriteString("                                                    $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                    if ($physHost -and $physHost.Info) {\n")
	script.WriteString("                                                        if ($physHost.Info.Info) {\n")
	script.WriteString("                                                            $serverInfo['osInfo'] = $physHost.Info.Info\n")
	script.WriteString("                                                        } elseif ($physHost.Info.Name) {\n")
	script.WriteString("                                                            $serverInfo['osInfo'] = $physHost.Info.Name\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a proxy\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($proxies) {\n")
	script.WriteString("                                                $isProxy = ($proxies | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isProxy'] = $isProxy\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a repository\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($repos) {\n")
	script.WriteString("                                                $isRepo = ($repos | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isRepo'] = $isRepo\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a WAN Accelerator\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($wanAccs) {\n")
	script.WriteString("                                                $isWANAcc = ($wanAccs | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isWANAcc'] = $isWANAcc\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get VM counts for ESXi/VC servers\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.Type -eq 'ESXi' -or $server.Type -eq 'VC') {\n")
	script.WriteString("                                                $viEntities = Find-VBRViEntity -Server $server -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($viEntities) {\n")
	script.WriteString("                                                    $serverInfo['totalVMs'] = $viEntities.Count\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    $vmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'VMware Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    $vmNames = $null\n")
	script.WriteString("                                                    if ($vmbackups) {\n")
	script.WriteString("                                                        try {\n")
	script.WriteString("                                                            $vmNames = $vmbackups.GetLastOibs($true)\n")
	script.WriteString("                                                        } catch {\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $vmNames = $vmbackups.GetLastOibs()\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                                        $serverVMs = $viEntities | Where-Object { $_.Name -in $vmNames.Name }\n")
	script.WriteString("                                                        $serverInfo['protectedVMs'] = $serverVMs.Count\n")
	script.WriteString("                                                        $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs'] - $serverInfo['protectedVMs']\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs']\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($server.Type -eq 'HvServer' -or $server.Type -eq 'HyperV') {\n")
	script.WriteString("                                                # Get VM counts for Hyper-V servers\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $hvEntities = Find-VBRHvEntity -Server $server -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($hvEntities) {\n")
	script.WriteString("                                                        $serverInfo['totalVMs'] = $hvEntities.Count\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        $hvbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'Hyper-V Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                        $vmNames = $null\n")
	script.WriteString("                                                        if ($hvbackups) {\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $vmNames = $hvbackups.GetLastOibs($true)\n")
	script.WriteString("                                                            } catch {\n")
	script.WriteString("                                                                try {\n")
	script.WriteString("                                                                    $vmNames = $hvbackups.GetLastOibs()\n")
	script.WriteString("                                                                } catch {}\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                                            $serverVMs = $hvEntities | Where-Object { $_.Name -in $vmNames.Name }\n")
	script.WriteString("                                                            $serverInfo['protectedVMs'] = $serverVMs.Count\n")
	script.WriteString("                                                            $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs'] - $serverInfo['protectedVMs']\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs']\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $managedServers += $serverInfo\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $veeamInfo['managedServers'] = $managedServers\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Proxies\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Proxies\" -Status \"Enumerating backup proxy servers\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['proxies'] = @($proxies | Select-Object -Property Name, HostId, @{n='Host';e={$_.Host.Name}})\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get WAN Accelerators\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting WAN Accelerators\" -Status \"Enumerating WAN accelerator servers\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $wanAccelerators = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['wanAccelerators'] = @($wanAccelerators | Select-Object -Property Name, HostId, @{n='Host';e={$_.Host.Name}})\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Database Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Database Configuration\" -Status \"Retrieving database connection details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $dbType = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations' -Name 'SqlActiveConfiguration' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $dbServerPath = Get-ItemProperty -Path $veeamRegPath -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $instancePath = Get-ItemProperty -Path $veeamRegPath -Name 'SqlInstanceName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($dbType) {\n")
	script.WriteString("                                $veeamInfo['database'] = @{\n")
	script.WriteString("                                    'type' = $dbType.SqlActiveConfiguration\n")
	script.WriteString("                                    'server' = if ($dbServerPath) { $dbServerPath.SqlServerName } else { 'N/A' }\n")
	script.WriteString("                                    'instance' = if ($instancePath) { $instancePath.SqlInstanceName } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($dbType.SqlActiveConfiguration -eq 'PostgreSql') {\n")
	script.WriteString("                                    $pgDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlHostName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $pgDbDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($pgDbHost) { $veeamInfo['database']['pgHost'] = $pgDbHost.SqlHostName }\n")
	script.WriteString("                                    if ($pgDbDbName) { $veeamInfo['database']['pgDb'] = $pgDbDbName.SqlDatabaseName }\n")
	script.WriteString("                                } elseif ($dbType.SqlActiveConfiguration -eq 'MsSql') {\n")
	script.WriteString("                                    $msDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $msDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($msDbHost) { $veeamInfo['database']['msHost'] = $msDbHost.SqlServerName }\n")
	script.WriteString("                                    if ($msDbName) { $veeamInfo['database']['msDb'] = $msDbName.SqlDatabaseName }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Security Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Security Summary\" -Status \"Analyzing security settings and encryption\"\n")
	script.WriteString("                        $securitySummary = @{\n")
	script.WriteString("                            'immutability' = $false\n")
	script.WriteString("                            'trafficEncryption' = $false\n")
	script.WriteString("                            'backupFileEncryption' = $false\n")
	script.WriteString("                            'configBackupEncryption' = $false\n")
	script.WriteString("                            'mfaEnabled' = $false\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Immutability (at least one repository with BackupImmutabilityEnabled)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allRepos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allRepos) {\n")
	script.WriteString("                                foreach ($repo in $allRepos) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.BackupImmutabilityEnabled -eq $true) {\n")
	script.WriteString("                                            $securitySummary['immutability'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            # Also check SOBR extents\n")
	script.WriteString("                            $sobrRepos = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($sobrRepos) {\n")
	script.WriteString("                                foreach ($sobr in $sobrRepos) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $extents = $sobr | Get-VBRCapacityExtent -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($extents) {\n")
	script.WriteString("                                            foreach ($extent in $extents) {\n")
	script.WriteString("                                                if ($extent.Repository -and $extent.Repository.BackupImmutabilityEnabled -eq $true) {\n")
	script.WriteString("                                                    $securitySummary['immutability'] = $true\n")
	script.WriteString("                                                    break\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Traffic Encryption (at least one network traffic rule with EncryptionEnabled)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $trafficRules = Get-VBRNetworkTrafficRule -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($trafficRules) {\n")
	script.WriteString("                                foreach ($rule in $trafficRules) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($rule.EncryptionEnabled -eq $true) {\n")
	script.WriteString("                                            $securitySummary['trafficEncryption'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Backup File Encryption (at least one job with PasswordKeyId not empty and not default)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allJobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allJobs) {\n")
	script.WriteString("                                foreach ($job in $allJobs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $pwdKeyId = $null\n")
	script.WriteString("                                        if ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Options.BackupStorageOptions.Encryption.PasswordKeyId\n")
	script.WriteString("                                        } elseif ($job.Options -and $job.Options.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Options.Encryption.PasswordKeyId\n")
	script.WriteString("                                        } elseif ($job.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Encryption.PasswordKeyId\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($pwdKeyId -and $pwdKeyId -ne '' -and $pwdKeyId -ne '00000000-0000-0000-0000-000000000000') {\n")
	script.WriteString("                                            $securitySummary['backupFileEncryption'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Config Backup Encryption (from configBackup.encrypted)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            if ($veeamInfo['configBackup'] -and $veeamInfo['configBackup']['encrypted']) {\n")
	script.WriteString("                                $securitySummary['configBackupEncryption'] = $veeamInfo['configBackup']['encrypted']\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get MFA Setting (VBR 12+)\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting MFA Settings\" -Status \"Checking multi-factor authentication configuration\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $mfaGlobalSetting = [Veeam.Backup.Core.SBackupOptions]::get_GlobalMFA()\n")
	script.WriteString("                            $securitySummary['mfaEnabled'] = $mfaGlobalSetting\n")
	script.WriteString("                            $veeamInfo['mfaEnabled'] = $mfaGlobalSetting\n")
	script.WriteString("                        } catch {\n")
	script.WriteString("                            $securitySummary['mfaEnabled'] = $false\n")
	script.WriteString("                            $veeamInfo['mfaEnabled'] = 'N/A - Pre VBR 12'\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['securitySummary'] = $securitySummary\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Compliance Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Compliance Summary\" -Status \"Analyzing best practices and compliance status\"\n")
	script.WriteString("                        $complianceSummary = @{\n")
	script.WriteString("                            'passed' = 0\n")
	script.WriteString("                            'notImplemented' = 0\n")
	script.WriteString("                            'unableToDetect' = 0\n")
	script.WriteString("                            'suppressed' = 0\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $complianceTable = @()\n")
	script.WriteString("                        \n")
	script.WriteString("                        try {\n")
	script.WriteString("                            # Get VBR Version\n")
	script.WriteString("                            $vbrVersion = 12\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $vbrVersionObj = Get-VBRVersion -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($vbrVersionObj) {\n")
	script.WriteString("                                    $vbrVersion = $vbrVersionObj.Major\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Compliance Results\n")
	script.WriteString("                            $securityCompliances = $null\n")
	script.WriteString("                            if ($vbrVersion -ge 13) {\n")
	script.WriteString("                                # VBR 13+ uses Get-VBRSecurityComplianceAnalyzerResults cmdlet\n")
	script.WriteString("                                $securityCompliances = Get-VBRSecurityComplianceAnalyzerResults -ErrorAction SilentlyContinue\n")
	script.WriteString("                            } else {\n")
	script.WriteString("                                # VBR 12 uses database method\n")
	script.WriteString("                                $securityCompliances = [Veeam.Backup.DBManager.CDBManager]::Instance.BestPractices.GetAll()\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($securityCompliances) {\n")
	script.WriteString("                                # Mapping of rule types to best practice names\n")
	script.WriteString("                                $ruleTypes = @{\n")
	script.WriteString("                                    'WindowsScriptHostDisabled' = 'Windows Script Host is disabled'\n")
	script.WriteString("                                    'BackupServicesUnderLocalSystem' = 'Backup services run under the LocalSystem account'\n")
	script.WriteString("                                    'OutdatedSslAndTlsDisabled' = 'Outdated SSL And TLS are Disabled'\n")
	script.WriteString("                                    'ManualLinuxHostAuthentication' = 'Unknown Linux servers are not trusted automatically'\n")
	script.WriteString("                                    'CSmbSigningAndEncryptionEnabled' = 'SMB v3 signing is enabled'\n")
	script.WriteString("                                    'ViProxyTrafficEncrypted' = 'Host to proxy traffic encryption should be enabled for the Network transport mode'\n")
	script.WriteString("                                    'JobsTargetingCloudRepositoriesEncrypted' = 'Backup jobs to cloud repositories is encrypted'\n")
	script.WriteString("                                    'LLMNRDisabled' = 'Link-Local Multicast Name Resolution (LLMNR) is disabled'\n")
	script.WriteString("                                    'ImmutableOrOfflineMediaPresence' = 'Immutable or offline media is used'\n")
	script.WriteString("                                    'OsBucketsInComplianceMode' = 'Os Buckets In Compliance Mode'\n")
	script.WriteString("                                    'BackupServerUpToDate' = 'Backup Server is Up To Date'\n")
	script.WriteString("                                    'BackupServerInProductionDomain' = 'Computer is Workgroup member'\n")
	script.WriteString("                                    'ReverseIncrementalInUse' = 'Reverse incremental backup mode is not used'\n")
	script.WriteString("                                    'ConfigurationBackupEncryptionEnabled' = 'Configuration backup encryption is enabled'\n")
	script.WriteString("                                    'WDigestNotStorePasswordsInMemory' = 'WDigest credentials caching is disabled'\n")
	script.WriteString("                                    'WebProxyAutoDiscoveryDisabled' = 'Web Proxy Auto-Discovery service (WinHttpAutoProxySvc) is disabled'\n")
	script.WriteString("                                    'ContainBackupCopies' = 'All backups have at least one copy (the 3-2-1 backup rule)'\n")
	script.WriteString("                                    'SMB1ProtocolDisabled' = 'SMB 1.0 is disabled'\n")
	script.WriteString("                                    'EmailNotificationsEnabled' = 'Email notifications are enabled'\n")
	script.WriteString("                                    'RemoteRegistryDisabled' = 'Remote registry service is disabled'\n")
	script.WriteString("                                    'PasswordsRotation' = 'Credentials and encryption passwords rotates annually'\n")
	script.WriteString("                                    'WinRmServiceDisabled' = 'Remote powershell is disabled (WinRM service)'\n")
	script.WriteString("                                    'MfaEnabledInBackupConsole' = 'MFA is enabled'\n")
	script.WriteString("                                    'HardenedRepositorySshDisabled' = 'Hardened repositories have SSH disabled'\n")
	script.WriteString("                                    'LinuxServersUsingSSHKeys' = 'Linux servers have password-based authentication disabled'\n")
	script.WriteString("                                    'RemoteDesktopServiceDisabled' = 'Remote desktop protocol is disabled'\n")
	script.WriteString("                                    'ConfigurationBackupEnabled' = 'Configuration backup is enabled'\n")
	script.WriteString("                                    'WindowsFirewallEnabled' = 'Windows firewall is enabled'\n")
	script.WriteString("                                    'FirewallEnabled' = 'Windows firewall is enabled'\n")
	script.WriteString("                                    'ConfigurationBackupEnabledAndEncrypted' = 'Configuration backup is enabled and use encryption'\n")
	script.WriteString("                                    'HardenedRepositoryNotVirtual' = 'Hardened repositories are not hosted in virtual machines'\n")
	script.WriteString("                                    'ConfigurationBackupRepositoryNotLocal' = 'The configuration backup is not stored on the backup server'\n")
	script.WriteString("                                    'PostgreSqlUseRecommendedSettings' = 'PostgreSQL server uses recommended settings'\n")
	script.WriteString("                                    'LossProtectionEnabled' = 'Password loss protection is enabled'\n")
	script.WriteString("                                    'TrafficEncryptionEnabled' = 'Encryption network rules added for LAN traffic'\n")
	script.WriteString("                                    'NetBiosDisabled' = 'NetBIOS protocol should be disabled on all network interfaces'\n")
	script.WriteString("                                    'HardenedRepositoryNotContainsNBDProxies' = 'Hardened repository should not be used as proxy'\n")
	script.WriteString("                                    'LsassProtectedProcess' = 'Local Security Authority Server Service (LSASS) running as protected process'\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Mapping of status values\n")
	script.WriteString("                                $statusObj = @{\n")
	script.WriteString("                                    'Ok' = 'Passed'\n")
	script.WriteString("                                    'Violation' = 'Not Implemented'\n")
	script.WriteString("                                    'UnableToCheck' = 'Unable to Detect'\n")
	script.WriteString("                                    'Suppressed' = 'Suppressed'\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                foreach ($compliance in $securityCompliances) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $complianceType = $null\n")
	script.WriteString("                                        $complianceStatus = $null\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($compliance.Type) {\n")
	script.WriteString("                                            $complianceType = $compliance.Type.ToString()\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($compliance.Status) {\n")
	script.WriteString("                                            $complianceStatus = $compliance.Status.ToString()\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if rule type exists in mapping\n")
	script.WriteString("                                        if (-not $ruleTypes.ContainsKey($complianceType)) {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if status exists in mapping\n")
	script.WriteString("                                        if (-not $statusObj.ContainsKey($complianceStatus)) {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $bestPractice = $ruleTypes[$complianceType]\n")
	script.WriteString("                                        $status = $statusObj[$complianceStatus]\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Add to table\n")
	script.WriteString("                                        $complianceTable += @{\n")
	script.WriteString("                                            'bestPractice' = $bestPractice\n")
	script.WriteString("                                            'status' = $status\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Count by status\n")
	script.WriteString("                                        switch ($status) {\n")
	script.WriteString("                                            'Passed' { $complianceSummary['passed']++ }\n")
	script.WriteString("                                            'Not Implemented' { $complianceSummary['notImplemented']++ }\n")
	script.WriteString("                                            'Unable to Detect' { $complianceSummary['unableToDetect']++ }\n")
	script.WriteString("                                            'Suppressed' { $complianceSummary['suppressed']++ }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['complianceSummary'] = $complianceSummary\n")
	script.WriteString("                        $veeamInfo['complianceTable'] = $complianceTable\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Disconnect\n")
	script.WriteString("                        Disconnect-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                    } catch {\n")
	script.WriteString("                        $veeamInfo['error'] = \"Failed to connect to VBR server: $($_.Exception.Message)\"\n")
	script.WriteString("                        $veeamInfo['connected'] = $false\n")
	script.WriteString("                    }\n")
	script.WriteString("                } catch {\n")
	script.WriteString("                    $veeamInfo['error'] = \"Veeam module loaded but commands failed: $($_.Exception.Message)\"\n")
	script.WriteString("                }\n")
	script.WriteString("            } else {\n")
	script.WriteString("                $veeamInfo['error'] = 'Veeam PowerShell module/snap-in not available'\n")
	script.WriteString("            }\n")
	script.WriteString("        }\n")
	script.WriteString("    } catch {\n")
	script.WriteString("        $veeamInfo['error'] = $_.Exception.Message\n")
	script.WriteString("    }\n")
	script.WriteString("    \n")
	script.WriteString("    $result['veeam'] = $veeamInfo\n\n")

	script.WriteString("    # Add metadata\n")
	script.WriteString("    $result['auditDate'] = (Get-Date).ToString('yyyy-MM-ddTHH:mm:ssZ')\n")
	script.WriteString("    $computer = Get-CimInstance Win32_ComputerSystem\n")
	script.WriteString("    $result['serverName'] = $computer.Name\n\n")

	script.WriteString("} catch {\n")
	script.WriteString("    $result['error'] = $_.Exception.Message\n")
	script.WriteString("    $result['errorDetails'] = $_.Exception.ToString()\n")
	script.WriteString("}\n\n")

	script.WriteString("Update-Progress -Step ($currentStep++) -Activity \"Finalizing\" -Status \"Converting data to JSON\"\n")
	script.WriteString("$json = $result | ConvertTo-Json -Depth 10 -Compress\n")
	script.WriteString("Write-Output $json\n")

	return script.String()
}

// generateVeeamAuditScriptForLocal creates a PowerShell script for local Veeam auditing
func generateVeeamAuditScriptForLocal(publicKeyPEM string, encrypt bool) string {
	var script strings.Builder
	script.WriteString("# Veeam Backup & Replication Audit Data Collection Script\n")
	script.WriteString("# Generated on " + time.Now().Format("2006-01-02 15:04:05") + "\n")
	if encrypt {
		script.WriteString("# This script collects Veeam data and outputs encrypted JSON\n\n")
	} else {
		script.WriteString("# This script collects Veeam data and outputs plain JSON\n\n")
	}

	script.WriteString("#Requires -Version 3.0\n")
	script.WriteString("#Requires -RunAsAdministrator\n\n")

	script.WriteString("$ErrorActionPreference = 'Stop'\n\n")

	if encrypt {
		// Encode public key to base64 for embedding in script
		pubKeyB64 := base64.StdEncoding.EncodeToString([]byte(publicKeyPEM))
		script.WriteString("$pubKeyB64 = '" + pubKeyB64 + "'\n\n")

		// Add encryption functions (same as Windows Server Auditor)
		script.WriteString("# Function to parse PEM public key\n")
		script.WriteString("function Parse-PEMPublicKey {\n")
		script.WriteString("    param([string]$PEM)\n")
		script.WriteString("    # Remove PEM headers/footers and whitespace\n")
		script.WriteString("    $base64 = $PEM -replace '-----BEGIN PUBLIC KEY-----', '' -replace '-----END PUBLIC KEY-----', '' -replace '\\s', ''\n")
		script.WriteString("    $keyBytes = [System.Convert]::FromBase64String($base64)\n")
		script.WriteString("    $pos = 0\n")
		script.WriteString("    \n")
		script.WriteString("    # Read SEQUENCE (0x30)\n")
		script.WriteString("    if ($keyBytes[$pos] -ne 0x30) { throw 'Invalid PEM format' }\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    \n")
		script.WriteString("    # Read length (skip for now)\n")
		script.WriteString("    $len = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    if ($len -gt 127) {\n")
		script.WriteString("        $lenBytes = $len - 128\n")
		script.WriteString("        $len = 0\n")
		script.WriteString("        for ($i = 0; $i -lt $lenBytes; $i++) {\n")
		script.WriteString("            $len = ($len -shl 8) -bor $keyBytes[$pos]\n")
		script.WriteString("            $pos++\n")
		script.WriteString("        }\n")
		script.WriteString("    }\n")
		script.WriteString("    \n")
		script.WriteString("    # Skip AlgorithmIdentifier (SEQUENCE)\n")
		script.WriteString("    if ($keyBytes[$pos] -eq 0x30) { $pos++ }\n")
		script.WriteString("    $algLen = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    if ($algLen -gt 127) {\n")
		script.WriteString("        $lenBytes = $algLen - 128\n")
		script.WriteString("        $pos += $lenBytes\n")
		script.WriteString("    }\n")
		script.WriteString("    $pos += $algLen\n")
		script.WriteString("    \n")
		script.WriteString("    # Read BIT STRING (0x03)\n")
		script.WriteString("    if ($keyBytes[$pos] -ne 0x03) { throw 'Invalid PEM format' }\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    $bitStrLen = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    if ($bitStrLen -gt 127) {\n")
		script.WriteString("        $lenBytes = $bitStrLen - 128\n")
		script.WriteString("        $bitStrLen = 0\n")
		script.WriteString("        for ($i = 0; $i -lt $lenBytes; $i++) {\n")
		script.WriteString("            $bitStrLen = ($bitStrLen -shl 8) -bor $keyBytes[$pos]\n")
		script.WriteString("            $pos++\n")
		script.WriteString("        }\n")
		script.WriteString("    }\n")
		script.WriteString("    $pos++ # Skip unused bits byte\n")
		script.WriteString("    \n")
		script.WriteString("    # Read RSA public key SEQUENCE\n")
		script.WriteString("    if ($keyBytes[$pos] -ne 0x30) { throw 'Invalid RSA key format' }\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    $rsaKeyLen = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    if ($rsaKeyLen -gt 127) {\n")
		script.WriteString("        $lenBytes = $rsaKeyLen - 128\n")
		script.WriteString("        $rsaKeyLen = 0\n")
		script.WriteString("        for ($i = 0; $i -lt $lenBytes; $i++) {\n")
		script.WriteString("            $rsaKeyLen = ($rsaKeyLen -shl 8) -bor $keyBytes[$pos]\n")
		script.WriteString("            $pos++\n")
		script.WriteString("        }\n")
		script.WriteString("    }\n")
		script.WriteString("    \n")
		script.WriteString("    # Read modulus INTEGER (0x02)\n")
		script.WriteString("    if ($keyBytes[$pos] -ne 0x02) { throw 'Invalid modulus' }\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    $modLen = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    if ($modLen -gt 127) {\n")
		script.WriteString("        $lenBytes = $modLen - 128\n")
		script.WriteString("        $modLen = 0\n")
		script.WriteString("        for ($i = 0; $i -lt $lenBytes; $i++) {\n")
		script.WriteString("            $modLen = ($modLen -shl 8) -bor $keyBytes[$pos]\n")
		script.WriteString("            $pos++\n")
		script.WriteString("        }\n")
		script.WriteString("    }\n")
		script.WriteString("    # Handle leading zero\n")
		script.WriteString("    if ($keyBytes[$pos] -eq 0) { $pos++; $modLen-- }\n")
		script.WriteString("    $modulus = New-Object byte[] $modLen\n")
		script.WriteString("    [Array]::Copy($keyBytes, $pos, $modulus, 0, $modLen)\n")
		script.WriteString("    $pos += $modLen\n")
		script.WriteString("    \n")
		script.WriteString("    # Read exponent INTEGER (0x02)\n")
		script.WriteString("    if ($keyBytes[$pos] -ne 0x02) { throw 'Invalid exponent' }\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    $expLen = $keyBytes[$pos]\n")
		script.WriteString("    $pos++\n")
		script.WriteString("    $exponent = New-Object byte[] $expLen\n")
		script.WriteString("    [Array]::Copy($keyBytes, $pos, $exponent, 0, $expLen)\n")
		script.WriteString("    \n")
		script.WriteString("    return @{ Modulus = $modulus; Exponent = $exponent }\n")
		script.WriteString("}\n\n")

		script.WriteString("# Function to encrypt data using hybrid encryption (AES + RSA)\n")
		script.WriteString("function Encrypt-Data {\n")
		script.WriteString("    param([string]$Data, [string]$PublicKeyBase64)\n")
		script.WriteString("    try {\n")
		script.WriteString("        # Generate AES key and IV\n")
		script.WriteString("        $aes = New-Object System.Security.Cryptography.AesCryptoServiceProvider\n")
		script.WriteString("        $aes.GenerateKey()\n")
		script.WriteString("        $aes.GenerateIV()\n")
		script.WriteString("        $aesKey = $aes.Key\n")
		script.WriteString("        $aesIV = $aes.IV\n")
		script.WriteString("        # Encrypt data with AES\n")
		script.WriteString("        $dataBytes = [System.Text.Encoding]::UTF8.GetBytes($Data)\n")
		script.WriteString("        $encryptor = $aes.CreateEncryptor()\n")
		script.WriteString("        $encryptedData = $encryptor.TransformFinalBlock($dataBytes, 0, $dataBytes.Length)\n")
		script.WriteString("        # Parse and import RSA public key\n")
		script.WriteString("        $pubKeyBytes = [System.Convert]::FromBase64String($PublicKeyBase64)\n")
		script.WriteString("        $pubKeyPEM = [System.Text.Encoding]::UTF8.GetString($pubKeyBytes)\n")
		script.WriteString("        $keyParams = Parse-PEMPublicKey -PEM $pubKeyPEM\n")
		script.WriteString("        # Create RSA parameters and import to RSA provider\n")
		script.WriteString("        $rsaParams = New-Object System.Security.Cryptography.RSAParameters\n")
		script.WriteString("        $rsaParams.Modulus = $keyParams.Modulus\n")
		script.WriteString("        $rsaParams.Exponent = $keyParams.Exponent\n")
		script.WriteString("        $rsa = New-Object System.Security.Cryptography.RSACryptoServiceProvider\n")
		script.WriteString("        $rsa.ImportParameters($rsaParams)\n")
		script.WriteString("        $encryptedKey = $rsa.Encrypt($aesKey, $false)\n")
		script.WriteString("        # Combine: encrypted key + IV + encrypted data (all base64)\n")
		script.WriteString("        $result = @{\n")
		script.WriteString("            key = [System.Convert]::ToBase64String($encryptedKey)\n")
		script.WriteString("            iv = [System.Convert]::ToBase64String($aesIV)\n")
		script.WriteString("            data = [System.Convert]::ToBase64String($encryptedData)\n")
		script.WriteString("        }\n")
		script.WriteString("        return ($result | ConvertTo-Json -Compress)\n")
		script.WriteString("    } catch {\n")
		script.WriteString("        Write-Error \"Encryption failed: $_\"\n")
		script.WriteString("        return $null\n")
		script.WriteString("    } finally {\n")
		script.WriteString("        if ($aes) { $aes.Dispose() }\n")
		script.WriteString("        if ($encryptor) { $encryptor.Dispose() }\n")
		script.WriteString("        if ($rsa) { $rsa.Dispose() }\n")
		script.WriteString("    }\n")
		script.WriteString("}\n\n")
	} else {
		script.WriteString("# NOTE: This script saves report data as plain JSON without encryption.\n")
		script.WriteString("Write-Warning 'Report data will be saved without encryption. Handle securely.'\n\n")
	}

	script.WriteString("$ProgressPreference = 'SilentlyContinue'\n\n")

	script.WriteString("# Enhanced progress tracking with colors\n")
	script.WriteString("function Update-Progress {\n")
	script.WriteString("    param([int]$Step, [string]$Activity, [string]$Status)\n")
	script.WriteString("    $percent = [math]::Round(($Step / $totalSteps) * 100)\n")
	script.WriteString("    if ($percent -gt 100) { $percent = 100 }\n")
	script.WriteString("    if ($percent -lt 0) { $percent = 0 }\n")
	script.WriteString("    Write-Progress -Activity \"Veeam Backup & Replication Audit\" -Status $Status -PercentComplete $percent\n")
	script.WriteString("    Write-Host \"[$percent%] $Activity\" -ForegroundColor Cyan\n")
	script.WriteString("}\n\n")

	script.WriteString("# Display banner\n")
	script.WriteString("Write-Host \"\"\n")
	script.WriteString("Write-Host \"========================================\" -ForegroundColor Cyan\n")
	script.WriteString("Write-Host \"  Veeam Backup & Replication Audit\" -ForegroundColor Yellow\n")
	script.WriteString("Write-Host \"  Data Collection Script\" -ForegroundColor Yellow\n")
	script.WriteString("Write-Host \"========================================\" -ForegroundColor Cyan\n")
	script.WriteString("Write-Host \"\"\n")
	script.WriteString("Write-Host \"Starting audit process...\" -ForegroundColor Green\n")
	script.WriteString("Write-Host \"\"\n\n")

	script.WriteString("$totalSteps = 26\n")
	script.WriteString("$currentStep = 0\n")
	script.WriteString("$startTime = Get-Date\n\n")

	script.WriteString("$result = @{}\n\n")

	script.WriteString("try {\n")
	script.WriteString("    # Veeam Backup & Replication Information\n")
	script.WriteString("    Update-Progress -Step ($currentStep++) -Activity \"Checking Veeam Installation\" -Status \"Verifying Veeam Backup & Replication installation\"\n")
	script.WriteString("    $veeamInfo = @{\n")
	script.WriteString("        'installed' = $false\n")
	script.WriteString("        'version' = 'N/A'\n")
	script.WriteString("        'serverName' = 'N/A'\n")
	script.WriteString("        'connected' = $false\n")
	script.WriteString("        'error' = $null\n")
	script.WriteString("    }\n")
	script.WriteString("    \n")
	script.WriteString("    try {\n")
	script.WriteString("        # Check if Veeam is installed by checking registry\n")
	script.WriteString("        $veeamRegPath = 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication'\n")
	script.WriteString("        Write-Host \"Checking registry path: $veeamRegPath\" -ForegroundColor Gray\n")
	script.WriteString("        $veeamInstalled = Test-Path $veeamRegPath\n")
	script.WriteString("        Write-Host \"Veeam installed: $veeamInstalled\" -ForegroundColor $(if ($veeamInstalled) { 'Green' } else { 'Yellow' })\n")
	script.WriteString("        \n")
	script.WriteString("        if ($veeamInstalled) {\n")
	script.WriteString("            $veeamInfo['installed'] = $true\n")
	script.WriteString("            Write-Host \"Veeam is installed, proceeding with data collection...\" -ForegroundColor Green\n")
	script.WriteString("            \n")
	script.WriteString("            # Get Veeam version\n")
	script.WriteString("            try {\n")
	script.WriteString("                $corePath = Get-ItemProperty -Path $veeamRegPath -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                    $depDLLPath = Join-Path -Path $corePath.CorePath -ChildPath 'Packages\\VeeamDeploymentDll.dll'\n")
	script.WriteString("                    if (Test-Path $depDLLPath) {\n")
	script.WriteString("                        $file = Get-Item -Path $depDLLPath\n")
	script.WriteString("                        $veeamInfo['version'] = $file.VersionInfo.ProductVersion\n")
	script.WriteString("                        $veeamInfo['fixes'] = $file.VersionInfo.Comments\n")
	script.WriteString("                    }\n")
	script.WriteString("                }\n")
	script.WriteString("            } catch {}\n")
	script.WriteString("            \n")
	script.WriteString("            # Try to load Veeam PowerShell module/snap-in\n")
	script.WriteString("            $veeamModuleLoaded = $false\n")
	script.WriteString("            $modulePath = $null\n")
	script.WriteString("            try {\n")
	script.WriteString("                # First, try to find the module in Veeam installation directory\n")
	script.WriteString("                $corePath = Get-ItemProperty -Path $veeamRegPath -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                    $possibleModulePaths = @(\n")
	script.WriteString("                        Join-Path $corePath.CorePath 'Backup\\Powershell'\n")
	script.WriteString("                        Join-Path $corePath.CorePath 'Backup\\Powershell\\Veeam.Backup.PowerShell.psd1'\n")
	script.WriteString("                        Join-Path $corePath.CorePath 'Powershell'\n")
	script.WriteString("                        Join-Path $corePath.CorePath 'Powershell\\Veeam.Backup.PowerShell.psd1'\n")
	script.WriteString("                    )\n")
	script.WriteString("                    foreach ($path in $possibleModulePaths) {\n")
	script.WriteString("                        if (Test-Path $path) {\n")
	script.WriteString("                            $modulePath = $path\n")
	script.WriteString("                            Write-Host \"Found Veeam module at: $modulePath\" -ForegroundColor Green\n")
	script.WriteString("                            break\n")
	script.WriteString("                        }\n")
	script.WriteString("                    }\n")
	script.WriteString("                }\n")
	script.WriteString("                \n")
	script.WriteString("                # PowerShell 7+ only supports modules, not PSSnapins\n")
	script.WriteString("                if ($PSVersionTable.PSVersion.Major -ge 6) {\n")
	script.WriteString("                    if ($modulePath -and (Test-Path $modulePath)) {\n")
	script.WriteString("                        Write-Host \"Importing Veeam module from: $modulePath\" -ForegroundColor Cyan\n")
	script.WriteString("                        Import-Module -Name $modulePath -ErrorAction Stop -WarningAction SilentlyContinue\n")
	script.WriteString("                    } else {\n")
	script.WriteString("                        if (!(Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue)) {\n")
	script.WriteString("                            Write-Host \"Trying to import Veeam.Backup.PowerShell from PSModulePath...\" -ForegroundColor Cyan\n")
	script.WriteString("                            Import-Module -Name Veeam.Backup.Powershell -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                        }\n")
	script.WriteString("                    }\n")
	script.WriteString("                    if (Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                        $veeamModuleLoaded = $true\n")
	script.WriteString("                        Write-Host \"Veeam.Backup.PowerShell module loaded successfully\" -ForegroundColor Green\n")
	script.WriteString("                    }\n")
	script.WriteString("                } else {\n")
	script.WriteString("                    # Windows PowerShell 5.1 - try PSSnapin first, then module\n")
	script.WriteString("                    Write-Host \"PowerShell version: $($PSVersionTable.PSVersion.Major).$($PSVersionTable.PSVersion.Minor) - Trying PSSnapin first...\" -ForegroundColor Gray\n")
	script.WriteString("                    if (!(Get-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue -Registered)) {\n")
	script.WriteString("                        Write-Host \"VeeamPSSnapIn not registered, trying to add it...\" -ForegroundColor Cyan\n")
	script.WriteString("                        Add-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                    } else {\n")
	script.WriteString("                        Write-Host \"VeeamPSSnapIn is registered, adding it...\" -ForegroundColor Cyan\n")
	script.WriteString("                        Add-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                    }\n")
	script.WriteString("                    if (Get-PSSnapin -Name VeeamPSSnapIn -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                        $veeamModuleLoaded = $true\n")
	script.WriteString("                        Write-Host \"VeeamPSSnapIn loaded successfully\" -ForegroundColor Green\n")
	script.WriteString("                    } else {\n")
	script.WriteString("                        Write-Host \"PSSnapin failed, trying module...\" -ForegroundColor Yellow\n")
	script.WriteString("                        if ($modulePath -and (Test-Path $modulePath)) {\n")
	script.WriteString("                            Write-Host \"Importing Veeam module from: $modulePath\" -ForegroundColor Cyan\n")
	script.WriteString("                            Import-Module -Name $modulePath -ErrorAction Stop -WarningAction SilentlyContinue\n")
	script.WriteString("                        } else {\n")
	script.WriteString("                            if (!(Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue)) {\n")
	script.WriteString("                                Write-Host \"Trying to import Veeam.Backup.PowerShell from PSModulePath...\" -ForegroundColor Cyan\n")
	script.WriteString("                                Import-Module -Name Veeam.Backup.Powershell -ErrorAction SilentlyContinue -WarningAction SilentlyContinue\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        if (Get-Module -Name Veeam.Backup.PowerShell -ErrorAction SilentlyContinue) {\n")
	script.WriteString("                            $veeamModuleLoaded = $true\n")
	script.WriteString("                            Write-Host \"Veeam.Backup.PowerShell module loaded successfully\" -ForegroundColor Green\n")
	script.WriteString("                        }\n")
	script.WriteString("                    }\n")
	script.WriteString("                }\n")
	script.WriteString("            } catch {\n")
	script.WriteString("                $errorMsg = \"Failed to load Veeam module: $($_.Exception.Message)\"\n")
	script.WriteString("                Write-Host $errorMsg -ForegroundColor Red\n")
	script.WriteString("                Write-Host \"Error details: $($_.Exception.StackTrace)\" -ForegroundColor Gray\n")
	script.WriteString("                $veeamInfo['error'] = $errorMsg\n")
	script.WriteString("            }\n")
	script.WriteString("            \n")
	script.WriteString("            if ($veeamModuleLoaded) {\n")
	script.WriteString("                try {\n")
	script.WriteString("                    # Disconnect any existing connections\n")
	script.WriteString("                    Disconnect-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                    \n")
	script.WriteString("                    # Try to connect to local VBR server\n")
	script.WriteString("                    $vbrServer = 'localhost'\n")
	script.WriteString("                    try {\n")
	script.WriteString("                        Connect-VBRServer -Server $vbrServer -ErrorAction Stop\n")
	script.WriteString("                        $veeamInfo['connected'] = $true\n")
	script.WriteString("                        $veeamInfo['serverName'] = $vbrServer\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get VBR Server Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Server Information\" -Status \"Gathering VBR server and configuration details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $vbrServers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['servers'] = @($vbrServers | Select-Object -Property Name, Type, IsUnavailable, @{n='Cores';e={try{$_.GetPhysicalHost().hardwareinfo.CoresCount}catch{'N/A'}}}, @{n='CPUCount';e={try{$_.GetPhysicalHost().hardwareinfo.CPUCount}catch{'N/A'}}}, @{n='RAM';e={try{[math]::Round($_.GetPhysicalHost().hardwareinfo.PhysicalRamTotal / 1GB, 2)}catch{'N/A'}}})\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Backup Server & Config DB Info\n")
	script.WriteString("                            $backupServerInfo = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get Veeam Version\n")
	script.WriteString("                                $veeamVersion = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Method 1: Try CVersion class\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $version = [Veeam.Backup.Core.CVersion]::Get()\n")
	script.WriteString("                                        if ($version) {\n")
	script.WriteString("                                            $veeamVersion = $version.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Method 2: Try registry\n")
	script.WriteString("                                    if ($veeamVersion -eq 'N/A') {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $corePath = Get-ItemProperty -Path 'HKLM:\\Software\\Veeam\\Veeam Backup and Replication\\' -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                                                $depDLLPath = Join-Path -Path $corePath.CorePath -ChildPath 'Packages\\VeeamDeploymentDll.dll'\n")
	script.WriteString("                                                if (Test-Path $depDLLPath) {\n")
	script.WriteString("                                                    $file = Get-Item -Path $depDLLPath\n")
	script.WriteString("                                                    if ($file.VersionInfo.ProductVersion) {\n")
	script.WriteString("                                                        $veeamVersion = $file.VersionInfo.ProductVersion\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Method 3: Try Get-VBRServerVersion\n")
	script.WriteString("                                    if ($veeamVersion -eq 'N/A') {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $version = Get-VBRServerVersion -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($version) {\n")
	script.WriteString("                                                $veeamVersion = $version.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Get local VBR server (backup server)\n")
	script.WriteString("                                $backupServer = $null\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $backupServer = Get-VBRServer | Where-Object { $_.Type -eq 'VBRServer' -or $_.Name -eq 'localhost' -or $_.Name -eq $env:COMPUTERNAME } | Select-Object -First 1\n")
	script.WriteString("                                    if (-not $backupServer) {\n")
	script.WriteString("                                        $backupServer = $vbrServers | Select-Object -First 1\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($backupServer) {\n")
	script.WriteString("                                    $serverName = $backupServer.Name\n")
	script.WriteString("                                    $cores = 'N/A'\n")
	script.WriteString("                                    $ram = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $physicalHost = $backupServer.GetPhysicalHost()\n")
	script.WriteString("                                        if ($physicalHost -and $physicalHost.hardwareinfo) {\n")
	script.WriteString("                                            $cores = $physicalHost.hardwareinfo.CoresCount\n")
	script.WriteString("                                            # PhysicalRamTotal is in bytes, convert to GB\n")
	script.WriteString("                                            $ram = [math]::Round($physicalHost.hardwareinfo.PhysicalRamTotal / 1GB, 2)\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check Proxy Role\n")
	script.WriteString("                                    $proxyRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($proxies) {\n")
	script.WriteString("                                            $proxyRole = ($proxies | Where-Object { $_.Host.Id -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check Repository/Gateway Role\n")
	script.WriteString("                                    $repoGatewayRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $repositories = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($repositories) {\n")
	script.WriteString("                                            $repoGatewayRole = ($repositories | Where-Object { $_.HostId -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Check WAN Accelerator Role\n")
	script.WriteString("                                    $wanAccRole = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $wanAccelerators = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($wanAccelerators) {\n")
	script.WriteString("                                            $wanAccRole = ($wanAccelerators | Where-Object { $_.HostId -eq $backupServer.Id }) -ne $null\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Domain Joined status\n")
	script.WriteString("                                    $isDomainJoined = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $computerSystem = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($computerSystem) {\n")
	script.WriteString("                                            $isDomainJoined = ($computerSystem.PartOfDomain -eq $true)\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Database Info\n")
	script.WriteString("                                    $dbType = 'N/A'\n")
	script.WriteString("                                    $dbName = 'N/A'\n")
	script.WriteString("                                    $dbServer = 'N/A'\n")
	script.WriteString("                                    $dbPort = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $dbTypePath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations' -Name 'SqlActiveConfiguration' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($dbTypePath) {\n")
	script.WriteString("                                            $dbType = $dbTypePath.SqlActiveConfiguration\n")
	script.WriteString("                                            if ($dbType -eq 'PostgreSql') {\n")
	script.WriteString("                                                $pgDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlHostName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $pgDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $pgDbPort = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlPort' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($pgDbHost) { $dbServer = $pgDbHost.SqlHostName }\n")
	script.WriteString("                                                if ($pgDbName) { $dbName = $pgDbName.SqlDatabaseName }\n")
	script.WriteString("                                                if ($pgDbPort -and $pgDbPort.PSObject.Properties['SqlPort']) {\n")
	script.WriteString("                                                    $portValue = $pgDbPort.SqlPort\n")
	script.WriteString("                                                    if ($portValue) { $dbPort = $portValue.ToString() + '/TCP' }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($dbType -eq 'MsSql') {\n")
	script.WriteString("                                                $msDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                $msDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($msDbHost) { $dbServer = $msDbHost.SqlServerName }\n")
	script.WriteString("                                                if ($msDbName) { $dbName = $msDbName.SqlDatabaseName }\n")
	script.WriteString("                                                $dbPort = '1433/TCP'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Connection Ports\n")
	script.WriteString("                                    $backupServerPort = 'N/A'\n")
	script.WriteString("                                    $secureConnectionsPort = 'N/A'\n")
	script.WriteString("                                    $cloudServerPort = 'N/A'\n")
	script.WriteString("                                    $cloudServicePort = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $portsPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($portsPath) {\n")
	script.WriteString("                                            if ($portsPath.BackupServerPort) { $backupServerPort = 'Backup Server Port: ' + $portsPath.BackupServerPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.SecureConnectionsPort) { $secureConnectionsPort = 'Secure Connections Port: ' + $portsPath.SecureConnectionsPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.CloudServerPort) { $cloudServerPort = 'Cloud Server Port: ' + $portsPath.CloudServerPort.ToString() }\n")
	script.WriteString("                                            if ($portsPath.CloudServicePort) { $cloudServicePort = 'Cloud Service Port: ' + $portsPath.CloudServicePort.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Install Path\n")
	script.WriteString("                                    $installPath = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $corePath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'CorePath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($corePath -and $corePath.CorePath) {\n")
	script.WriteString("                                            $installPath = $corePath.CorePath\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Audit Logs Path\n")
	script.WriteString("                                    $auditLogsPath = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $auditPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'AuditPath' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($auditPath) {\n")
	script.WriteString("                                            if ($auditPath.AuditPath) { $auditLogsPath = $auditPath.AuditPath }\n")
	script.WriteString("                                            elseif ($auditPath.PSObject.Properties['AuditPath']) { $auditLogsPath = $auditPath.PSObject.Properties['AuditPath'].Value }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Compress Old Audit Logs\n")
	script.WriteString("                                    $compressOldAuditLogs = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $compressPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'CompressOldAuditLogs' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($compressPath) {\n")
	script.WriteString("                                            if ($compressPath.PSObject.Properties['CompressOldAuditLogs']) {\n")
	script.WriteString("                                                $compressValue = $compressPath.CompressOldAuditLogs\n")
	script.WriteString("                                                $compressOldAuditLogs = ($compressValue -eq 1 -or $compressValue -eq $true)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get FIPS Compliant Mode\n")
	script.WriteString("                                    $fipsCompliantMode = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $fipsPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'FipsCompliantMode' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($fipsPath) {\n")
	script.WriteString("                                            if ($fipsPath.PSObject.Properties['FipsCompliantMode']) {\n")
	script.WriteString("                                                $fipsValue = $fipsPath.FipsCompliantMode\n")
	script.WriteString("                                                $fipsCompliantMode = if ($fipsValue -eq 1 -or $fipsValue -eq $true) { 'Enabled' } else { 'Disabled' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Linux host authentication\n")
	script.WriteString("                                    $linuxHostAuth = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $linuxAuthPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'LinuxHostAuthentication' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($linuxAuthPath) {\n")
	script.WriteString("                                            if ($linuxAuthPath.PSObject.Properties['LinuxHostAuthentication']) {\n")
	script.WriteString("                                                $authValue = $linuxAuthPath.LinuxHostAuthentication\n")
	script.WriteString("                                                if ($authValue -eq 0) { $linuxHostAuth = 'Add unknown host to the list automatically' }\n")
	script.WriteString("                                                elseif ($authValue -eq 1) { $linuxHostAuth = 'Add unknown host to the list manually' }\n")
	script.WriteString("                                                else { $linuxHostAuth = 'N/A' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Logging Level\n")
	script.WriteString("                                    $loggingLevel = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $logLevelPath = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication' -Name 'LoggingLevel' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($logLevelPath) {\n")
	script.WriteString("                                            $loggingLevel = $logLevelPath.LoggingLevel.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Hardware & Software Inventory\n")
	script.WriteString("                                    $systemInventory = @{}\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $computer = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $bios = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $processor = Get-CimInstance Win32_Processor | Select-Object -First 1 -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        $timezone = (Get-TimeZone -ErrorAction SilentlyContinue).DisplayName\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get License Info\n")
	script.WriteString("                                        $licenseType = 'N/A'\n")
	script.WriteString("                                        $partialProductKey = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $license = Get-CimInstance -ClassName SoftwareLicensingProduct -ErrorAction SilentlyContinue | Where-Object { $_.PartialProductKey -and $_.Name -like '*Windows*' } | Select-Object -First 1\n")
	script.WriteString("                                            if ($license) {\n")
	script.WriteString("                                                $licenseType = $license.Name\n")
	script.WriteString("                                                $partialProductKey = $license.PartialProductKey\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Install Type\n")
	script.WriteString("                                        $installType = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $serverGuiShell = Get-WindowsFeature -Name Server-Gui-Shell -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($serverGuiShell) {\n")
	script.WriteString("                                                $installType = if ($serverGuiShell.InstallState -eq 'Installed') { 'Server' } else { 'Server Core' }\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $installType = 'Server'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {\n")
	script.WriteString("                                            $installType = 'Server'\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get BIOS Type\n")
	script.WriteString("                                        $biosType = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $biosType = if ($bios.SMBIOSBIOSVersion -like '*UEFI*' -or ($bios.BiosCharacteristics -and $bios.BiosCharacteristics -contains 12)) { 'Uefi' } else { 'Legacy' }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($os -and $computer -and $bios -and $processor) {\n")
	script.WriteString("                                            $systemInventory = @{\n")
	script.WriteString("                                                'name' = $computer.Name\n")
	script.WriteString("                                                'windowsProductName' = $os.Caption\n")
	script.WriteString("                                                'windowsCurrentVersion' = $os.Version\n")
	script.WriteString("                                                'windowsBuildNumber' = $os.BuildNumber\n")
	script.WriteString("                                                'windowsInstallType' = $installType\n")
	script.WriteString("                                                'activeDirectoryDomain' = $computer.Domain\n")
	script.WriteString("                                                'windowsInstallationDate' = if ($os.InstallDate) { $os.InstallDate.ToString('MM/dd/yyyy HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                                'timeZone' = if ($timezone) { $timezone } else { 'N/A' }\n")
	script.WriteString("                                                'licenseType' = $licenseType\n")
	script.WriteString("                                                'partialProductKey' = $partialProductKey\n")
	script.WriteString("                                                'manufacturer' = $computer.Manufacturer\n")
	script.WriteString("                                                'model' = $computer.Model\n")
	script.WriteString("                                                'serialNumber' = $bios.SerialNumber\n")
	script.WriteString("                                                'biosType' = $biosType\n")
	script.WriteString("                                                'biosVersion' = $bios.Version\n")
	script.WriteString("                                                'processorManufacturer' = $processor.Manufacturer\n")
	script.WriteString("                                                'processorModel' = $processor.Name\n")
	script.WriteString("                                                'numberOfCpuCores' = $processor.NumberOfCores\n")
	script.WriteString("                                                'numberOfLogicalCores' = $processor.NumberOfLogicalProcessors\n")
	script.WriteString("                                                'physicalMemoryGB' = [math]::Round($computer.TotalPhysicalMemory / 1GB, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Local Disks\n")
	script.WriteString("                                    $localDisks = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $disks = Get-Disk -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($disks) {\n")
	script.WriteString("                                            $localDisks = @($disks | ForEach-Object {\n")
	script.WriteString("                                                $disk = $_\n")
	script.WriteString("                                                $partitionStyle = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $partitionStyle = $disk.PartitionStyle.ToString()\n")
	script.WriteString("                                                    if ($partitionStyle -eq 'GPT') { $partitionStyle = '2' }\n")
	script.WriteString("                                                    elseif ($partitionStyle -eq 'MBR') { $partitionStyle = '1' }\n")
	script.WriteString("                                                    elseif ($partitionStyle -eq 'Raw') { $partitionStyle = '0' }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'diskNumber' = $disk.Number\n")
	script.WriteString("                                                    'model' = if ($disk.Model) { $disk.Model.Trim() } else { 'N/A' }\n")
	script.WriteString("                                                    'serialNumber' = if ($disk.SerialNumber) { $disk.SerialNumber.Trim() } else { 'N/A' }\n")
	script.WriteString("                                                    'partitionStyle' = $partitionStyle\n")
	script.WriteString("                                                    'diskSize' = [math]::Round($disk.Size / 1GB, 2)\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Host Volumes\n")
	script.WriteString("                                    $hostVolumes = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $volumes = Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -or $_.FileSystemLabel }\n")
	script.WriteString("                                        if ($volumes) {\n")
	script.WriteString("                                            $hostVolumes = @($volumes | ForEach-Object {\n")
	script.WriteString("                                                $vol = $_\n")
	script.WriteString("                                                $healthStatus = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    if ($vol.HealthStatus) {\n")
	script.WriteString("                                                        $healthStatus = $vol.HealthStatus.ToString()\n")
	script.WriteString("                                                        if ($healthStatus -eq 'Healthy') { $healthStatus = '0' }\n")
	script.WriteString("                                                        elseif ($healthStatus -eq 'Warning') { $healthStatus = '1' }\n")
	script.WriteString("                                                        elseif ($healthStatus -eq 'Unhealthy') { $healthStatus = '2' }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'driveLetter' = if ($vol.DriveLetter) { $vol.DriveLetter } else { '' }\n")
	script.WriteString("                                                    'fileSystemLabel' = if ($vol.FileSystemLabel) { $vol.FileSystemLabel } else { '' }\n")
	script.WriteString("                                                    'fileSystem' = if ($vol.FileSystem) { $vol.FileSystem } else { 'N/A' }\n")
	script.WriteString("                                                    'size' = [math]::Round($vol.Size / 1GB, 2)\n")
	script.WriteString("                                                    'freeSpace' = [math]::Round($vol.SizeRemaining / 1GB, 2)\n")
	script.WriteString("                                                    'healthStatus' = $healthStatus\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Network Adapters\n")
	script.WriteString("                                    $networkAdapters = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $adapters = Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }\n")
	script.WriteString("                                        if ($adapters) {\n")
	script.WriteString("                                            $networkAdapters = @($adapters | ForEach-Object {\n")
	script.WriteString("                                                $adapter = $_\n")
	script.WriteString("                                                $linkSpeed = 'N/A'\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $linkSpeed = $adapter.LinkSpeed\n")
	script.WriteString("                                                    if ($linkSpeed) {\n")
	script.WriteString("                                                        $linkSpeed = $linkSpeed.ToString()\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                @{\n")
	script.WriteString("                                                    'adapterName' = if ($adapter.Name) { $adapter.Name } else { 'N/A' }\n")
	script.WriteString("                                                    'adapterDescription' = if ($adapter.InterfaceDescription) { $adapter.InterfaceDescription } else { 'N/A' }\n")
	script.WriteString("                                                    'macAddress' = if ($adapter.MacAddress) { $adapter.MacAddress } else { 'N/A' }\n")
	script.WriteString("                                                    'linkSpeed' = $linkSpeed\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            })\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get IP Address Information\n")
	script.WriteString("                                    $ipAddresses = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $netAdapters = Get-NetAdapter -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($netAdapters) {\n")
	script.WriteString("                                            foreach ($adapter in $netAdapters) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $ipConfig = Get-NetIPAddress -InterfaceIndex $adapter.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    $ipGateway = Get-NetRoute -InterfaceIndex $adapter.InterfaceIndex -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Select-Object -First 1\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    if ($ipConfig) {\n")
	script.WriteString("                                                        foreach ($ip in $ipConfig) {\n")
	script.WriteString("                                                            $subnetMask = 'N/A'\n")
	script.WriteString("                                                            $gateway = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($ip.PrefixLength) {\n")
	script.WriteString("                                                                    $subnetMask = $ip.PrefixLength.ToString()\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                if ($ipGateway -and $ipGateway.NextHop) {\n")
	script.WriteString("                                                                    $gateway = $ipGateway.NextHop.ToString()\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $ipAddresses += @{\n")
	script.WriteString("                                                                'interfaceName' = if ($adapter.Name) { $adapter.Name } else { 'N/A' }\n")
	script.WriteString("                                                                'interfaceDescription' = if ($adapter.InterfaceDescription) { $adapter.InterfaceDescription } else { 'N/A' }\n")
	script.WriteString("                                                                'ipv4Address' = if ($ip.IPAddress) { $ip.IPAddress.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                                'subnetMask' = $subnetMask\n")
	script.WriteString("                                                                'ipv4Gateway' = $gateway\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $backupServerInfo = @{\n")
	script.WriteString("                                        'name' = $serverName\n")
	script.WriteString("                                        'isDomainJoined' = $isDomainJoined\n")
	script.WriteString("                                        'version' = $veeamVersion\n")
	script.WriteString("                                        'databaseType' = $dbType\n")
	script.WriteString("                                        'databaseName' = $dbName\n")
	script.WriteString("                                        'databaseServer' = $dbServer\n")
	script.WriteString("                                        'databasePort' = $dbPort\n")
	script.WriteString("                                        'backupServerPort' = $backupServerPort\n")
	script.WriteString("                                        'secureConnectionsPort' = $secureConnectionsPort\n")
	script.WriteString("                                        'cloudServerPort' = $cloudServerPort\n")
	script.WriteString("                                        'cloudServicePort' = $cloudServicePort\n")
	script.WriteString("                                        'installPath' = $installPath\n")
	script.WriteString("                                        'auditLogsPath' = $auditLogsPath\n")
	script.WriteString("                                        'compressOldAuditLogs' = $compressOldAuditLogs\n")
	script.WriteString("                                        'fipsCompliantMode' = $fipsCompliantMode\n")
	script.WriteString("                                        'linuxHostAuth' = $linuxHostAuth\n")
	script.WriteString("                                        'loggingLevel' = $loggingLevel\n")
	script.WriteString("                                        'cores' = $cores\n")
	script.WriteString("                                        'ram' = $ram\n")
	script.WriteString("                                        'proxyRole' = $proxyRole\n")
	script.WriteString("                                        'repoGatewayRole' = $repoGatewayRole\n")
	script.WriteString("                                        'wanAccRole' = $wanAccRole\n")
	script.WriteString("                                        'systemInventory' = $systemInventory\n")
	script.WriteString("                                        'localDisks' = $localDisks\n")
	script.WriteString("                                        'hostVolumes' = $hostVolumes\n")
	script.WriteString("                                        'networkAdapters' = $networkAdapters\n")
	script.WriteString("                                        'ipAddresses' = $ipAddresses\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            $veeamInfo['backupServerInfo'] = $backupServerInfo\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Infrastructure Statistics\n")
	script.WriteString("                            Update-Progress -Step ($currentStep++) -Activity \"Collecting Infrastructure Statistics\" -Status \"Counting infrastructure components\"\n")
	script.WriteString("                            $infrastructureStats = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Backup Proxies\n")
	script.WriteString("                                $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['backupProxies'] = if ($proxies) { $proxies.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Managed Servers\n")
	script.WriteString("                                $servers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['managedServers'] = if ($servers) { $servers.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Backup Repositories (Standalone only)\n")
	script.WriteString("                                $repos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $standaloneRepos = 0\n")
	script.WriteString("                                if ($repos) {\n")
	script.WriteString("                                    foreach ($repo in $repos) {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($repo.IsScaleOut -ne $true) { $standaloneRepos++ }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                $infrastructureStats['backupRepositories'] = $standaloneRepos\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SOBR Repositories\n")
	script.WriteString("                                $sobrs = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sobrRepositories'] = if ($sobrs) { $sobrs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Object Repository\n")
	script.WriteString("                                $objectRepos = Get-VBRObjectStorageRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['objectRepository'] = if ($objectRepos) { $objectRepos.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # WAN Accelerator\n")
	script.WriteString("                                $wanAccs = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['wanAccelerator'] = if ($wanAccs) { $wanAccs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Cloud Service Providers\n")
	script.WriteString("                                $csp = Get-VBRCloudProvider -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['cloudServiceProviders'] = if ($csp) { $csp.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SureBackup Application Group\n")
	script.WriteString("                                $appGroups = Get-VBRApplicationGroup -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sureBackupApplicationGroup'] = if ($appGroups) { $appGroups.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # SureBackup Virtual Lab\n")
	script.WriteString("                                $virtualLabs = Get-VBRVirtualLab -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['sureBackupVirtualLab'] = if ($virtualLabs) { $virtualLabs.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Locations\n")
	script.WriteString("                                $locations = Get-VBRLocation -ErrorAction SilentlyContinue\n")
	script.WriteString("                                $infrastructureStats['locations'] = if ($locations) { $locations.Count } else { 0 }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # License Information\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $license = Get-VBRLicenseInfo -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($license) {\n")
	script.WriteString("                                        # Instance Licenses\n")
	script.WriteString("                                        if ($license.InstanceLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesTotal'] = if ($license.InstanceLicenseSummary.LicensedInstancesNumber) { $license.InstanceLicenseSummary.LicensedInstancesNumber } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesUsed'] = if ($license.InstanceLicenseSummary.UsedInstancesNumber) { $license.InstanceLicenseSummary.UsedInstancesNumber } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesTotal'] = if ($license.LicensedInstances) { $license.LicensedInstances } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['instanceLicensesUsed'] = if ($license.UsedInstances) { $license.UsedInstances } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        # Socket Licenses\n")
	script.WriteString("                                        if ($license.SocketLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesTotal'] = if ($license.SocketLicenseSummary.LicensedSocketsNumber) { $license.SocketLicenseSummary.LicensedSocketsNumber } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesUsed'] = if ($license.SocketLicenseSummary.UsedSocketsNumber) { $license.SocketLicenseSummary.UsedSocketsNumber } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesTotal'] = if ($license.LicensedSockets) { $license.LicensedSockets } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['socketLicensesUsed'] = if ($license.UsedSockets) { $license.UsedSockets } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        # Capacity Licenses\n")
	script.WriteString("                                        if ($license.CapacityLicenseSummary) {\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesTotal'] = if ($license.CapacityLicenseSummary.LicensedCapacityTb) { $license.CapacityLicenseSummary.LicensedCapacityTb } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesUsed'] = if ($license.CapacityLicenseSummary.UsedCapacityTb) { $license.CapacityLicenseSummary.UsedCapacityTb } else { 0 }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesTotal'] = if ($license.LicensedCapacity) { [math]::Round($license.LicensedCapacity / 1TB, 0) } else { 0 }\n")
	script.WriteString("                                            $infrastructureStats['capacityLicensesUsed'] = if ($license.UsedCapacity) { [math]::Round($license.UsedCapacity / 1TB, 0) } else { 0 }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $infrastructureStats['instanceLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['instanceLicensesUsed'] = 0\n")
	script.WriteString("                                        $infrastructureStats['socketLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['socketLicensesUsed'] = 0\n")
	script.WriteString("                                        $infrastructureStats['capacityLicensesTotal'] = 0\n")
	script.WriteString("                                        $infrastructureStats['capacityLicensesUsed'] = 0\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $infrastructureStats['instanceLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['instanceLicensesUsed'] = 0\n")
	script.WriteString("                                    $infrastructureStats['socketLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['socketLicensesUsed'] = 0\n")
	script.WriteString("                                    $infrastructureStats['capacityLicensesTotal'] = 0\n")
	script.WriteString("                                    $infrastructureStats['capacityLicensesUsed'] = 0\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            $veeamInfo['infrastructureStats'] = $infrastructureStats\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Config Backup Info\n")
	script.WriteString("                            $configBackupInfo = @{}\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $job = Get-VBRConfigurationBackupJob -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($job) {\n")
	script.WriteString("                                    # Extract values directly from $job object properties\n")
	script.WriteString("                                    $configBackupName = if ($job.Name) { $job.Name } else { 'N/A' }\n")
	script.WriteString("                                    $configBackupEnabled = if ($job.Enabled -ne $null) { [bool]$job.Enabled } else { $false }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get ScheduleOptions - check the type of schedule\n")
	script.WriteString("                                    $scheduleType = 'N/A'\n")
	script.WriteString("                                    if ($job.ScheduleOptions) {\n")
	script.WriteString("                                        $scheduleOpts = $job.ScheduleOptions\n")
	script.WriteString("                                        # Try to get the schedule type from the object\n")
	script.WriteString("                                        if ($scheduleOpts.OptionsDaily) { $scheduleType = 'Daily' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsMonthly) { $scheduleType = 'Monthly' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsPeriodically) { $scheduleType = 'Periodically' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsContinuous) { $scheduleType = 'Continuous' }\n")
	script.WriteString("                                        elseif ($scheduleOpts.OptionsScheduleAfterJob) { $scheduleType = 'After Job' }\n")
	script.WriteString("                                        else {\n")
	script.WriteString("                                            # Fallback: try to get type name or use ToString\n")
	script.WriteString("                                            $typeName = $scheduleOpts.GetType().Name\n")
	script.WriteString("                                            if ($typeName -like '*Daily*') { $scheduleType = 'Daily' }\n")
	script.WriteString("                                            elseif ($typeName -like '*Monthly*') { $scheduleType = 'Monthly' }\n")
	script.WriteString("                                            else { $scheduleType = $scheduleOpts.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get RestorePointsToKeep - handle null/0 values\n")
	script.WriteString("                                    $restorePointsToKeep = 'N/A'\n")
	script.WriteString("                                    if ($job.RestorePointsToKeep -ne $null -and $job.RestorePointsToKeep -ne '') {\n")
	script.WriteString("                                        $restorePointsToKeep = $job.RestorePointsToKeep\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Encryption status - EncryptionOptions is a boolean\n")
	script.WriteString("                                    $configBackupEncrypted = $false\n")
	script.WriteString("                                    if ($job.EncryptionOptions -ne $null) {\n")
	script.WriteString("                                        $configBackupEncrypted = [bool]$job.EncryptionOptions\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get NextRun - handle DateTime objects\n")
	script.WriteString("                                    $nextRun = '--'\n")
	script.WriteString("                                    if ($job.NextRun -ne $null) {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($job.NextRun -is [DateTime]) {\n")
	script.WriteString("                                                $nextRun = $job.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $nextRun = $job.NextRun.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {\n")
	script.WriteString("                                            $nextRun = $job.NextRun.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Target - handle object or string\n")
	script.WriteString("                                    $configBackupTarget = 'N/A'\n")
	script.WriteString("                                    if ($job.Target -ne $null) {\n")
	script.WriteString("                                        if ($job.Target -is [string]) {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target\n")
	script.WriteString("                                        } elseif ($job.Target.Name) {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target.Name\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $configBackupTarget = $job.Target.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get LastResult\n")
	script.WriteString("                                    $configBackupLastResult = if ($job.LastResult) { $job.LastResult.ToString() } else { 'None' }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Build simplified config backup info\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = $configBackupName\n")
	script.WriteString("                                        'enabled' = $configBackupEnabled\n")
	script.WriteString("                                        'scheduleType' = $scheduleType\n")
	script.WriteString("                                        'restorePointsToKeep' = $restorePointsToKeep\n")
	script.WriteString("                                        'encrypted' = $configBackupEncrypted\n")
	script.WriteString("                                        'nextRun' = $nextRun\n")
	script.WriteString("                                        'target' = $configBackupTarget\n")
	script.WriteString("                                        'lastResult' = $configBackupLastResult\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    # If no config backup job found, set defaults\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = 'N/A'\n")
	script.WriteString("                                        'enabled' = $false\n")
	script.WriteString("                                        'scheduleType' = 'N/A'\n")
	script.WriteString("                                        'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                        'encrypted' = $false\n")
	script.WriteString("                                        'nextRun' = '--'\n")
	script.WriteString("                                        'target' = 'N/A'\n")
	script.WriteString("                                        'lastResult' = 'N/A'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {\n")
	script.WriteString("                                # On error, set defaults\n")
	script.WriteString("                                $configBackupInfo = @{\n")
	script.WriteString("                                    'name' = 'N/A'\n")
	script.WriteString("                                    'enabled' = $false\n")
	script.WriteString("                                    'scheduleType' = 'N/A'\n")
	script.WriteString("                                    'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                    'encrypted' = $false\n")
	script.WriteString("                                    'nextRun' = '--'\n")
	script.WriteString("                                    'target' = 'N/A'\n")
	script.WriteString("                                    'lastResult' = 'N/A'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['configBackup'] = $configBackupInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Server TLS Certificate\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting TLS Certificate Information\" -Status \"Retrieving backup server TLS certificate details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $tlsCertificate = @{}\n")
	script.WriteString("                            $friendlyName = 'N/A'\n")
	script.WriteString("                            $subjectName = 'N/A'\n")
	script.WriteString("                            $issuerName = 'N/A'\n")
	script.WriteString("                            $expirationDate = 'N/A'\n")
	script.WriteString("                            $issuedDate = 'N/A'\n")
	script.WriteString("                            $thumbprint = 'N/A'\n")
	script.WriteString("                            $serialNumber = 'N/A'\n")
	script.WriteString("                            \n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get certificate from Veeam Backup Server\n")
	script.WriteString("                                $cert = Get-VBRBackupServerCertificate -ErrorAction SilentlyContinue\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($cert) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get FriendlyName\n")
	script.WriteString("                                        if ($cert.FriendlyName) { $friendlyName = $cert.FriendlyName.ToString() }\n")
	script.WriteString("                                        elseif ($cert.Name) { $friendlyName = $cert.Name.ToString() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Subject\n")
	script.WriteString("                                        if ($cert.SubjectName) {\n")
	script.WriteString("                                            if ($cert.SubjectName -is [string]) { $subjectName = $cert.SubjectName }\n")
	script.WriteString("                                            else { $subjectName = $cert.SubjectName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Subject) {\n")
	script.WriteString("                                            if ($cert.Subject -is [string]) { $subjectName = $cert.Subject }\n")
	script.WriteString("                                            else { $subjectName = $cert.Subject.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SubjectName) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.SubjectName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Subject) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.Subject.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issuer\n")
	script.WriteString("                                        if ($cert.IssuerName) {\n")
	script.WriteString("                                            if ($cert.IssuerName -is [string]) { $issuerName = $cert.IssuerName }\n")
	script.WriteString("                                            else { $issuerName = $cert.IssuerName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Issuer) {\n")
	script.WriteString("                                            if ($cert.Issuer -is [string]) { $issuerName = $cert.Issuer }\n")
	script.WriteString("                                            else { $issuerName = $cert.Issuer.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.IssuerName) {\n")
	script.WriteString("                                            $runJobAutomatically = [bool]$configBackupJob.ScheduleOptions.Enabled\n")
	script.WriteString("                                        } elseif ($configBackupJob.IsScheduleEnabled -ne $null) {\n")
	script.WriteString("                                            $runJobAutomatically = [bool]$configBackupJob.IsScheduleEnabled\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Schedule Type and Options\n")
	script.WriteString("                                    $scheduleType = 'N/A'\n")
	script.WriteString("                                    $scheduleTypeValue = 'N/A'\n")
	script.WriteString("                                    $schedulePeriod = 'N/A'\n")
	script.WriteString("                                    $scheduleDayOfWeek = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.ScheduleOptions) {\n")
	script.WriteString("                                            $scheduleOpts = $configBackupJob.ScheduleOptions\n")
	script.WriteString("                                            if ($scheduleOpts.ScheduleType) {\n")
	script.WriteString("                                                $scheduleTypeValue = $scheduleOpts.ScheduleType\n")
	script.WriteString("                                                if ($scheduleTypeValue -is [enum]) {\n")
	script.WriteString("                                                    $scheduleType = $scheduleTypeValue.ToString()\n")
	script.WriteString("                                                } else {\n")
	script.WriteString("                                                    $scheduleType = $scheduleTypeValue.ToString()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($scheduleOpts.DailyOptions -and $scheduleOpts.DailyOptions.Time) {\n")
	script.WriteString("                                                $schedulePeriod = $scheduleOpts.DailyOptions.Time.ToString('HH:mm:ss')\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($scheduleOpts.DailyOptions -and $scheduleOpts.DailyOptions.Days) {\n")
	script.WriteString("                                                $days = @()\n")
	script.WriteString("                                                foreach ($day in $scheduleOpts.DailyOptions.Days) {\n")
	script.WriteString("                                                    if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                $scheduleDayOfWeek = $days -join ' '\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Restore Points To Keep\n")
	script.WriteString("                                    $restorePointsToKeep = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.Options -and $configBackupJob.Options.RestorePointsToKeep) {\n")
	script.WriteString("                                            $restorePointsToKeep = $configBackupJob.Options.RestorePointsToKeep\n")
	script.WriteString("                                        } elseif ($configBackupJob.RestorePointsToKeep) {\n")
	script.WriteString("                                            $restorePointsToKeep = $configBackupJob.RestorePointsToKeep\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Encryption Key\n")
	script.WriteString("                                    $encryptionKey = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.Options -and $configBackupJob.Options.EncryptionKey) {\n")
	script.WriteString("                                            $encKey = $configBackupJob.Options.EncryptionKey\n")
	script.WriteString("                                            if ($encKey -is [string]) {\n")
	script.WriteString("                                                $encryptionKey = $encKey\n")
	script.WriteString("                                            } elseif ($encKey.Name) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.Name\n")
	script.WriteString("                                            } elseif ($encKey.ToString) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } elseif ($configBackupJob.EncryptionKey) {\n")
	script.WriteString("                                            $encKey = $configBackupJob.EncryptionKey\n")
	script.WriteString("                                            if ($encKey -is [string]) {\n")
	script.WriteString("                                                $encryptionKey = $encKey\n")
	script.WriteString("                                            } elseif ($encKey.Name) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.Name\n")
	script.WriteString("                                            } elseif ($encKey.ToString) {\n")
	script.WriteString("                                                $encryptionKey = $encKey.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Email Notification Settings\n")
	script.WriteString("                                    $emailAdditionalAddress = 'N/A'\n")
	script.WriteString("                                    $emailSubject = 'N/A'\n")
	script.WriteString("                                    $notifyOnSuccess = $false\n")
	script.WriteString("                                    $notifyOnWarning = $false\n")
	script.WriteString("                                    $notifyOnError = $false\n")
	script.WriteString("                                    $notifyOnLastRetryOnly = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.NotificationOptions) {\n")
	script.WriteString("                                            $notifyOpts = $configBackupJob.NotificationOptions\n")
	script.WriteString("                                            if ($notifyOpts.EmailAdditionalAddress) { $emailAdditionalAddress = $notifyOpts.EmailAdditionalAddress }\n")
	script.WriteString("                                            if ($notifyOpts.EmailSubject) { $emailSubject = $notifyOpts.EmailSubject }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnSuccess -ne $null) { $notifyOnSuccess = [bool]$notifyOpts.NotifyOnSuccess }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnWarning -ne $null) { $notifyOnWarning = [bool]$notifyOpts.NotifyOnWarning }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnError -ne $null) { $notifyOnError = [bool]$notifyOpts.NotifyOnError }\n")
	script.WriteString("                                            if ($notifyOpts.NotifyOnLastRetryOnly -ne $null) { $notifyOnLastRetryOnly = [bool]$notifyOpts.NotifyOnLastRetryOnly }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get NextRun\n")
	script.WriteString("                                    $nextRun = '--'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($configBackupJob.ScheduleOptions -and $configBackupJob.ScheduleOptions.NextRun) {\n")
	script.WriteString("                                            $nextRun = $configBackupJob.ScheduleOptions.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($configBackupJob.NextRun) {\n")
	script.WriteString("                                            $nextRun = $configBackupJob.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = $configBackupName\n")
	script.WriteString("                                        'runJobAutomatically' = $runJobAutomatically\n")
	script.WriteString("                                        'scheduleType' = $scheduleType\n")
	script.WriteString("                                        'schedulePeriod' = $schedulePeriod\n")
	script.WriteString("                                        'scheduleDayOfWeek' = $scheduleDayOfWeek\n")
	script.WriteString("                                        'restorePointsToKeep' = $restorePointsToKeep\n")
	script.WriteString("                                        'encryptionKey' = $encryptionKey\n")
	script.WriteString("                                        'emailAdditionalAddress' = $emailAdditionalAddress\n")
	script.WriteString("                                        'emailSubject' = $emailSubject\n")
	script.WriteString("                                        'notifyOnSuccess' = $notifyOnSuccess\n")
	script.WriteString("                                        'notifyOnWarning' = $notifyOnWarning\n")
	script.WriteString("                                        'notifyOnError' = $notifyOnError\n")
	script.WriteString("                                        'notifyOnLastRetryOnly' = $notifyOnLastRetryOnly\n")
	script.WriteString("                                        'nextRun' = $nextRun\n")
	script.WriteString("                                        'enabled' = $configBackupEnabled\n")
	script.WriteString("                                        'lastResult' = $configBackupLastResult\n")
	script.WriteString("                                        'encrypted' = $configBackupEncrypted\n")
	script.WriteString("                                        'target' = $configBackupTarget\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    # If no config backup job found, set defaults\n")
	script.WriteString("                                    $configBackupInfo = @{\n")
	script.WriteString("                                        'name' = 'N/A'\n")
	script.WriteString("                                        'enabled' = $false\n")
	script.WriteString("                                        'scheduleType' = 'N/A'\n")
	script.WriteString("                                        'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                        'encrypted' = $false\n")
	script.WriteString("                                        'nextRun' = '--'\n")
	script.WriteString("                                        'target' = 'N/A'\n")
	script.WriteString("                                        'lastResult' = 'N/A'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {\n")
	script.WriteString("                                # On error, set defaults\n")
	script.WriteString("                                $configBackupInfo = @{\n")
	script.WriteString("                                    'name' = 'N/A'\n")
	script.WriteString("                                    'enabled' = $false\n")
	script.WriteString("                                    'scheduleType' = 'N/A'\n")
	script.WriteString("                                    'restorePointsToKeep' = 'N/A'\n")
	script.WriteString("                                    'encrypted' = $false\n")
	script.WriteString("                                    'nextRun' = '--'\n")
	script.WriteString("                                    'target' = 'N/A'\n")
	script.WriteString("                                    'lastResult' = 'N/A'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['configBackup'] = $configBackupInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Server TLS Certificate\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting TLS Certificate Information\" -Status \"Retrieving backup server TLS certificate details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $tlsCertificate = @{}\n")
	script.WriteString("                            $friendlyName = 'N/A'\n")
	script.WriteString("                            $subjectName = 'N/A'\n")
	script.WriteString("                            $issuerName = 'N/A'\n")
	script.WriteString("                            $expirationDate = 'N/A'\n")
	script.WriteString("                            $issuedDate = 'N/A'\n")
	script.WriteString("                            $thumbprint = 'N/A'\n")
	script.WriteString("                            $serialNumber = 'N/A'\n")
	script.WriteString("                            \n")
	script.WriteString("                            try {\n")
	script.WriteString("                                # Get certificate from Veeam Backup Server\n")
	script.WriteString("                                $cert = Get-VBRBackupServerCertificate -ErrorAction SilentlyContinue\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($cert) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get FriendlyName\n")
	script.WriteString("                                        if ($cert.FriendlyName) { $friendlyName = $cert.FriendlyName.ToString() }\n")
	script.WriteString("                                        elseif ($cert.Name) { $friendlyName = $cert.Name.ToString() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Subject\n")
	script.WriteString("                                        if ($cert.SubjectName) {\n")
	script.WriteString("                                            if ($cert.SubjectName -is [string]) { $subjectName = $cert.SubjectName }\n")
	script.WriteString("                                            else { $subjectName = $cert.SubjectName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Subject) {\n")
	script.WriteString("                                            if ($cert.Subject -is [string]) { $subjectName = $cert.Subject }\n")
	script.WriteString("                                            else { $subjectName = $cert.Subject.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SubjectName) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.SubjectName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Subject) {\n")
	script.WriteString("                                            $subjectName = $cert.Certificate.Subject.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issuer\n")
	script.WriteString("                                        if ($cert.IssuerName) {\n")
	script.WriteString("                                            if ($cert.IssuerName -is [string]) { $issuerName = $cert.IssuerName }\n")
	script.WriteString("                                            else { $issuerName = $cert.IssuerName.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Issuer) {\n")
	script.WriteString("                                            if ($cert.Issuer -is [string]) { $issuerName = $cert.Issuer }\n")
	script.WriteString("                                            else { $issuerName = $cert.Issuer.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.IssuerName) {\n")
	script.WriteString("                                            $issuerName = $cert.Certificate.IssuerName.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Issuer) {\n")
	script.WriteString("                                            $issuerName = $cert.Certificate.Issuer.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Expiration Date\n")
	script.WriteString("                                        if ($cert.NotAfter) { $expirationDate = $cert.NotAfter.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.ExpirationDate) { $expirationDate = $cert.ExpirationDate.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.NotAfter) { $expirationDate = $cert.Certificate.NotAfter.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Issued Date\n")
	script.WriteString("                                        if ($cert.NotBefore) { $issuedDate = $cert.NotBefore.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.IssueDate) { $issuedDate = $cert.IssueDate.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.NotBefore) { $issuedDate = $cert.Certificate.NotBefore.ToString('M/d/yyyy') }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Thumbprint\n")
	script.WriteString("                                        if ($cert.Thumbprint) { $thumbprint = $cert.Thumbprint.ToUpper() }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.Thumbprint) { $thumbprint = $cert.Certificate.Thumbprint.ToUpper() }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Serial Number\n")
	script.WriteString("                                        if ($cert.SerialNumber) { $serialNumber = $cert.SerialNumber.ToUpper() }\n")
	script.WriteString("                                        elseif ($cert.Certificate -and $cert.Certificate.SerialNumber) { $serialNumber = $cert.Certificate.SerialNumber.ToUpper() }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            $tlsCertificate = @{\n")
	script.WriteString("                                'friendlyName' = $friendlyName\n")
	script.WriteString("                                'subjectName' = $subjectName\n")
	script.WriteString("                                'issuerName' = $issuerName\n")
	script.WriteString("                                'expirationDate' = $expirationDate\n")
	script.WriteString("                                'issuedDate' = $issuedDate\n")
	script.WriteString("                                'thumbprint' = $thumbprint\n")
	script.WriteString("                                'serialNumber' = $serialNumber\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['tlsCertificate'] = $tlsCertificate\n")
	script.WriteString("                        } catch {\n")
	script.WriteString("                            $veeamInfo['tlsCertificate'] = @{\n")
	script.WriteString("                                'friendlyName' = 'N/A'\n")
	script.WriteString("                                'subjectName' = 'N/A'\n")
	script.WriteString("                                'issuerName' = 'N/A'\n")
	script.WriteString("                                'expirationDate' = 'N/A'\n")
	script.WriteString("                                'issuedDate' = 'N/A'\n")
	script.WriteString("                                'thumbprint' = 'N/A'\n")
	script.WriteString("                                'serialNumber' = 'N/A'\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get License Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting License Information\" -Status \"Retrieving license details and usage statistics\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $license = Get-VBRInstalledLicense -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($license) {\n")
	script.WriteString("                                # Convert Edition enum to name\n")
	script.WriteString("                                $editionName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $editionValue = $license.Edition\n")
	script.WriteString("                                    $editionStr = $editionValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $editionInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($editionStr, [ref]$editionInt)) {\n")
	script.WriteString("                                        switch ($editionInt) {\n")
	script.WriteString("                                            0 { $editionName = 'Standard' }\n")
	script.WriteString("                                            1 { $editionName = 'Enterprise' }\n")
	script.WriteString("                                            2 { $editionName = 'EnterprisePlus' }\n")
	script.WriteString("                                            3 { $editionName = 'Foundation' }\n")
	script.WriteString("                                            default { $editionName = \"Edition_$editionInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($editionValue -is [enum]) {\n")
	script.WriteString("                                        $editionName = $editionStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $editionName = $editionStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $editionName = if ($license.Edition) { $license.Edition.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Convert Status enum to name\n")
	script.WriteString("                                $statusName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $statusValue = $license.Status\n")
	script.WriteString("                                    $statusStr = $statusValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $statusInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($statusStr, [ref]$statusInt)) {\n")
	script.WriteString("                                        switch ($statusInt) {\n")
	script.WriteString("                                            0 { $statusName = 'Valid' }\n")
	script.WriteString("                                            1 { $statusName = 'Expired' }\n")
	script.WriteString("                                            2 { $statusName = 'ExpiringSoon' }\n")
	script.WriteString("                                            3 { $statusName = 'Invalid' }\n")
	script.WriteString("                                            default { $statusName = \"Status_$statusInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($statusValue -is [enum]) {\n")
	script.WriteString("                                        $statusName = $statusStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $statusName = $statusStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $statusName = if ($license.Status) { $license.Status.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Convert Type enum to name\n")
	script.WriteString("                                $typeName = 'N/A'\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $typeValue = $license.Type\n")
	script.WriteString("                                    $typeStr = $typeValue.ToString()\n")
	script.WriteString("                                    # Try to parse as integer first\n")
	script.WriteString("                                    $typeInt = 0\n")
	script.WriteString("                                    if ([int]::TryParse($typeStr, [ref]$typeInt)) {\n")
	script.WriteString("                                        switch ($typeInt) {\n")
	script.WriteString("                                            0 { $typeName = 'Perpetual' }\n")
	script.WriteString("                                            1 { $typeName = 'Subscription' }\n")
	script.WriteString("                                            2 { $typeName = 'Rental' }\n")
	script.WriteString("                                            3 { $typeName = 'NFR' }\n")
	script.WriteString("                                            4 { $typeName = 'Trial' }\n")
	script.WriteString("                                            5 { $typeName = 'Free' }\n")
	script.WriteString("                                            default { $typeName = \"Type_$typeInt\" }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } elseif ($typeValue -is [enum]) {\n")
	script.WriteString("                                        $typeName = $typeStr\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        $typeName = $typeStr\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $typeName = if ($license.Type) { $license.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                $veeamInfo['license'] = @{\n")
	script.WriteString("                                    'licensedTo' = $license.LicensedTo\n")
	script.WriteString("                                    'edition' = $editionName\n")
	script.WriteString("                                    'expirationDate' = if ($license.ExpirationDate) { $license.ExpirationDate.ToString('yyyy-MM-dd HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                    'type' = $typeName\n")
	script.WriteString("                                    'status' = $statusName\n")
	script.WriteString("                                    'licensedSockets' = if ($license.SocketLicenseSummary) { $license.SocketLicenseSummary.LicensedSocketsNumber } else { 0 }\n")
	script.WriteString("                                    'usedSockets' = if ($license.SocketLicenseSummary) { $license.SocketLicenseSummary.UsedSocketsNumber } else { 0 }\n")
	script.WriteString("                                    'licensedInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.LicensedInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'usedInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.UsedInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'newInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.NewInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'rentalInstances' = if ($license.InstanceLicenseSummary) { $license.InstanceLicenseSummary.RentalInstancesNumber } else { 0 }\n")
	script.WriteString("                                    'licensedNas' = if ($license.CapacityLicenseSummary) { $license.CapacityLicenseSummary.LicensedCapacityTb } else { 0 }\n")
	script.WriteString("                                    'usedNas' = if ($license.CapacityLicenseSummary) { $license.CapacityLicenseSummary.UsedCapacityTb } else { 0 }\n")
	script.WriteString("                                    'supportExpirationDate' = if ($license.SupportExpirationDate) { $license.SupportExpirationDate.ToString('yyyy-MM-dd HH:mm:ss') } else { 'N/A' }\n")
	script.WriteString("                                    'cloudConnectEnabled' = if ($license.CloudConnect) { $license.CloudConnect.ToString() } else { 'Disabled' }\n")
	script.WriteString("                                    'supportId' = if ($license.SupportId) { $license.SupportId.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    'autoUpdateEnabled' = if ($license.AutoUpdateEnabled -ne $null) { $license.AutoUpdateEnabled.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    'freeAgentInstance' = if ($license.FreeAgentInstance -ne $null) { $license.FreeAgentInstance.ToString() } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Veeam Services Status\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Services Status\" -Status \"Checking Veeam service status and health\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $veeamServices = @()\n")
	script.WriteString("                            $allServices = Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*Veeam*' }\n")
	script.WriteString("                            if ($allServices) {\n")
	script.WriteString("                                foreach ($svc in $allServices) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $status = 'N/A'\n")
	script.WriteString("                                        if ($svc.Status) {\n")
	script.WriteString("                                            $status = $svc.Status.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        $veeamServices += @{\n")
	script.WriteString("                                            'displayName' = if ($svc.DisplayName) { $svc.DisplayName } else { 'N/A' }\n")
	script.WriteString("                                            'shortName' = if ($svc.Name) { $svc.Name } else { 'N/A' }\n")
	script.WriteString("                                            'status' = $status\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['servicesStatus'] = $veeamServices\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Enterprise Manager Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Enterprise Manager Information\" -Status \"Gathering Enterprise Manager connection details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $emInfo = @{}\n")
	script.WriteString("                            $emServerName = 'N/A'\n")
	script.WriteString("                            $emServerUrl = 'N/A'\n")
	script.WriteString("                            $emSkipLicensePush = 'N/A'\n")
	script.WriteString("                            $emIsConnected = 'No'\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 1: Try Get-VBREmServer\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $emServer = Get-VBREmServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($emServer) {\n")
	script.WriteString("                                    $emServerName = if ($emServer.Name) { $emServer.Name } else { 'N/A' }\n")
	script.WriteString("                                    $emServerUrl = if ($emServer.Url) { $emServer.Url } else { 'N/A' }\n")
	script.WriteString("                                    $emSkipLicensePush = if ($emServer.SkipLicensePush -ne $null) { $emServer.SkipLicensePush.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    $emIsConnected = if ($emServer.IsConnected -ne $null) { $emServer.IsConnected.ToString() } else { 'No' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 2: Try Get-VBREmConnection if Method 1 failed\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emConnection = Get-VBREmConnection -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($emConnection) {\n")
	script.WriteString("                                        if ($emServerName -eq 'N/A') { $emServerName = if ($emConnection.ServerName) { $emConnection.ServerName } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emServerUrl -eq 'N/A') { $emServerUrl = if ($emConnection.Url) { $emConnection.Url } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emSkipLicensePush -eq 'N/A') { $emSkipLicensePush = if ($emConnection.SkipLicensePush -ne $null) { $emConnection.SkipLicensePush.ToString() } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emIsConnected -eq 'No') { $emIsConnected = if ($emConnection.IsConnected -ne $null) { $emConnection.IsConnected.ToString() } else { 'No' } }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 3: Try .NET classes directly\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emServerObj = [Veeam.Backup.DBManager.CDBManager]::Instance.EmServer\n")
	script.WriteString("                                    if ($emServerObj) {\n")
	script.WriteString("                                        if ($emServerName -eq 'N/A') { $emServerName = if ($emServerObj.Name) { $emServerObj.Name } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emServerUrl -eq 'N/A') { $emServerUrl = if ($emServerObj.Url) { $emServerObj.Url } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emSkipLicensePush -eq 'N/A') { $emSkipLicensePush = if ($emServerObj.SkipLicensePush -ne $null) { $emServerObj.SkipLicensePush.ToString() } else { 'N/A' } }\n")
	script.WriteString("                                        if ($emIsConnected -eq 'No') { $emIsConnected = if ($emServerObj.IsConnected -ne $null) { $emServerObj.IsConnected.ToString() } else { 'No' } }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Method 4: Try registry\n")
	script.WriteString("                            if ($emServerName -eq 'N/A' -or $emServerUrl -eq 'N/A') {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $emRegPath = 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\EnterpriseManager'\n")
	script.WriteString("                                    if (Test-Path $emRegPath) {\n")
	script.WriteString("                                        $emReg = Get-ItemProperty -Path $emRegPath -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($emReg) {\n")
	script.WriteString("                                            if ($emServerName -eq 'N/A' -and $emReg.ServerName) { $emServerName = $emReg.ServerName }\n")
	script.WriteString("                                            if ($emServerUrl -eq 'N/A' -and $emReg.Url) { $emServerUrl = $emReg.Url }\n")
	script.WriteString("                                            if ($emSkipLicensePush -eq 'N/A' -and $emReg.SkipLicensePush -ne $null) { $emSkipLicensePush = $emReg.SkipLicensePush.ToString() }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $emInfo['serverName'] = $emServerName\n")
	script.WriteString("                            $emInfo['serverUrl'] = $emServerUrl\n")
	script.WriteString("                            $emInfo['skipLicensePush'] = $emSkipLicensePush\n")
	script.WriteString("                            $emInfo['isConnected'] = $emIsConnected\n")
	script.WriteString("                            $veeamInfo['enterpriseManager'] = $emInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Email Notification Settings\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Email Notification Settings\" -Status \"Getting email notification configuration\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $emailInfo = @{}\n")
	script.WriteString("                            $emailConfig = Get-VBRMailNotificationConfiguration -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($emailConfig) {\n")
	script.WriteString("                                $emailRecipient = if ($emailConfig.Recipient) { $emailConfig.Recipient } else { 'N/A' }\n")
	script.WriteString("                                $emailSender = if ($emailConfig.Sender) { $emailConfig.Sender } else { 'N/A' }\n")
	script.WriteString("                                $smtpServer = if ($emailConfig.SmtpServer) { $emailConfig.SmtpServer } else { 'N/A' }\n")
	script.WriteString("                                $emailSubject = if ($emailConfig.Subject) { $emailConfig.Subject } else { 'N/A' }\n")
	script.WriteString("                                $sslEnabled = if ($emailConfig.SSLEnabled -ne $null) { if ($emailConfig.SSLEnabled) { 'Yes' } else { 'No' } } else { 'N/A' }\n")
	script.WriteString("                                $authEnabled = if ($emailConfig.AuthEnabled -ne $null) { if ($emailConfig.AuthEnabled) { 'Yes' } else { 'No' } } else { 'N/A' }\n")
	script.WriteString("                                $credentials = if ($emailConfig.Credentials -and $emailConfig.Credentials.UserName) { $emailConfig.Credentials.UserName } elseif ($emailConfig.Credentials) { $emailConfig.Credentials.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $dailyReportsTime = if ($emailConfig.DailyReportsTime) { $emailConfig.DailyReportsTime.ToString('HH:mm') } else { 'N/A' }\n")
	script.WriteString("                                $smtpPort = if ($emailConfig.Port) { $emailConfig.Port.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $smtpTimeout = if ($emailConfig.Timeout) { $emailConfig.Timeout.ToString() } else { 'N/A' }\n")
	script.WriteString("                                $enabled = if ($emailConfig.Enabled -ne $null) { if ($emailConfig.Enabled) { 'Yes' } else { 'No' } } else { 'No' }\n")
	script.WriteString("                                $notifyOnSuccess = if ($emailConfig.NotifyOnSuccess -ne $null) { if ($emailConfig.NotifyOnSuccess) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnWarning = if ($emailConfig.NotifyOnWarning -ne $null) { if ($emailConfig.NotifyOnWarning) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnFailure = if ($emailConfig.NotifyOnFailure -ne $null) { if ($emailConfig.NotifyOnFailure) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                                $notifyOnLastRetryOnly = if ($emailConfig.NotifyOnLastRetryOnly -ne $null) { if ($emailConfig.NotifyOnLastRetryOnly) { 'True' } else { 'False' } } else { 'N/A' }\n")
	script.WriteString("                            } else {\n")
	script.WriteString("                                $emailRecipient = 'N/A'\n")
	script.WriteString("                                $emailSender = 'N/A'\n")
	script.WriteString("                                $smtpServer = 'N/A'\n")
	script.WriteString("                                $emailSubject = 'N/A'\n")
	script.WriteString("                                $sslEnabled = 'N/A'\n")
	script.WriteString("                                $authEnabled = 'N/A'\n")
	script.WriteString("                                $credentials = 'N/A'\n")
	script.WriteString("                                $dailyReportsTime = 'N/A'\n")
	script.WriteString("                                $smtpPort = 'N/A'\n")
	script.WriteString("                                $smtpTimeout = 'N/A'\n")
	script.WriteString("                                $enabled = 'No'\n")
	script.WriteString("                                $notifyOnSuccess = 'N/A'\n")
	script.WriteString("                                $notifyOnWarning = 'N/A'\n")
	script.WriteString("                                $notifyOnFailure = 'N/A'\n")
	script.WriteString("                                $notifyOnLastRetryOnly = 'N/A'\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Detect SMTP Server Type\n")
	script.WriteString("                            $smtpType = 'N/A'\n")
	script.WriteString("                            if ($smtpServer -ne 'N/A' -and $smtpServer) {\n")
	script.WriteString("                                $smtpLower = $smtpServer.ToLower()\n")
	script.WriteString("                                if ($smtpLower -like '*outlook*' -or $smtpLower -like '*office365*' -or $smtpLower -like '*office.com*' -or $smtpLower -like '*smtp.office365.com*') {\n")
	script.WriteString("                                    $smtpType = 'Office365'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*gmail*' -or $smtpLower -like '*google*' -or $smtpLower -like '*smtp.gmail.com*') {\n")
	script.WriteString("                                    $smtpType = 'Gmail'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*exchange*' -or $smtpLower -like '*mail.office365.com*') {\n")
	script.WriteString("                                    $smtpType = 'Exchange'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*azure*') {\n")
	script.WriteString("                                    $smtpType = 'Azure'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*yahoo*' -or $smtpLower -like '*smtp.mail.yahoo.com*') {\n")
	script.WriteString("                                    $smtpType = 'Yahoo'\n")
	script.WriteString("                                } elseif ($smtpLower -like '*smtp*') {\n")
	script.WriteString("                                    $smtpType = 'SMTP'\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $smtpType = 'Custom'\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $emailInfo['emailRecipient'] = $emailRecipient\n")
	script.WriteString("                            $emailInfo['emailSender'] = $emailSender\n")
	script.WriteString("                            $emailInfo['smtpServer'] = $smtpServer\n")
	script.WriteString("                            $emailInfo['smtpType'] = $smtpType\n")
	script.WriteString("                            $emailInfo['emailSubject'] = $emailSubject\n")
	script.WriteString("                            $emailInfo['sslEnabled'] = $sslEnabled\n")
	script.WriteString("                            $emailInfo['authEnabled'] = $authEnabled\n")
	script.WriteString("                            $emailInfo['credentials'] = $credentials\n")
	script.WriteString("                            $emailInfo['dailyReportsTime'] = $dailyReportsTime\n")
	script.WriteString("                            $emailInfo['smtpPort'] = $smtpPort\n")
	script.WriteString("                            $emailInfo['smtpTimeout'] = $smtpTimeout\n")
	script.WriteString("                            $emailInfo['enabled'] = $enabled\n")
	script.WriteString("                            $emailInfo['notifyOnSuccess'] = $notifyOnSuccess\n")
	script.WriteString("                            $emailInfo['notifyOnWarning'] = $notifyOnWarning\n")
	script.WriteString("                            $emailInfo['notifyOnFailure'] = $notifyOnFailure\n")
	script.WriteString("                            $emailInfo['notifyOnLastRetryOnly'] = $notifyOnLastRetryOnly\n")
	script.WriteString("                            $veeamInfo['emailNotification'] = $emailInfo\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Backup Repositories\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Repositories\" -Status \"Enumerating backup repositories\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $repositories = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $repoList = @()\n")
	script.WriteString("                            foreach ($repo in $repositories) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Convert Type enum to name\n")
	script.WriteString("                                    $typeName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $typeValue = $repo.Type\n")
	script.WriteString("                                        if ($typeValue -is [enum]) {\n")
	script.WriteString("                                            $typeName = $typeValue.ToString()\n")
	script.WriteString("                                        } elseif ($typeValue -is [int] -or $typeValue -is [System.Int32]) {\n")
	script.WriteString("                                            switch ([int]$typeValue) {\n")
	script.WriteString("                                                0 { $typeName = 'Windows' }\n")
	script.WriteString("                                                1 { $typeName = 'Linux' }\n")
	script.WriteString("                                                2 { $typeName = 'SharedFolder' }\n")
	script.WriteString("                                                3 { $typeName = 'DedupeStorage' }\n")
	script.WriteString("                                                4 { $typeName = 'Cloud' }\n")
	script.WriteString("                                                default { $typeName = \"Type_$typeValue\" }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $typeName = if ($typeValue) { $typeValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {\n")
	script.WriteString("                                        $typeName = if ($repo.Type) { $repo.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Convert Status enum to name\n")
	script.WriteString("                                    $statusName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $statusValue = $repo.Status\n")
	script.WriteString("                                        if ($statusValue -is [enum]) {\n")
	script.WriteString("                                            $statusName = $statusValue.ToString()\n")
	script.WriteString("                                        } elseif ($statusValue -is [int] -or $statusValue -is [System.Int32]) {\n")
	script.WriteString("                                            switch ([int]$statusValue) {\n")
	script.WriteString("                                                0 { $statusName = 'Available' }\n")
	script.WriteString("                                                1 { $statusName = 'Unavailable' }\n")
	script.WriteString("                                                2 { $statusName = 'Maintenance' }\n")
	script.WriteString("                                                default { $statusName = \"Status_$statusValue\" }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            $statusName = if ($statusValue) { $statusValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {\n")
	script.WriteString("                                        $statusName = if ($repo.Status) { $repo.Status.ToString() } else { 'N/A' }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Skip SOBR repositories\n")
	script.WriteString("                                    if ($repo.IsScaleOut -eq $true) { continue }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get space information\n")
	script.WriteString("                                    $cachedTotalSpaceGB = 0\n")
	script.WriteString("                                    $cachedFreeSpaceGB = 0\n")
	script.WriteString("                                    $freeSpacePercent = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $container = $repo.getcontainer()\n")
	script.WriteString("                                        if ($container) {\n")
	script.WriteString("                                            if ($container.CachedTotalSpace) {\n")
	script.WriteString("                                                $cachedTotalSpaceGB = [math]::Round($container.CachedTotalSpace.ingigabytes, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($container.CachedFreeSpace) {\n")
	script.WriteString("                                                $cachedFreeSpaceGB = [math]::Round($container.CachedFreeSpace.ingigabytes, 2)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($cachedTotalSpaceGB -gt 0) {\n")
	script.WriteString("                                                $freeSpacePercent = [math]::Round(($cachedFreeSpaceGB / $cachedTotalSpaceGB) * 100, 1)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Job Count\n")
	script.WriteString("                                    $jobCount = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($jobs) {\n")
	script.WriteString("                                            foreach ($job in $jobs) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    if ($job.TargetRepositoryId -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                    elseif ($job.TargetRepository -and $job.TargetRepository.Id -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                    elseif ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.TargetRepositoryId -eq $repo.Id) { $jobCount++ }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Set Tasks\n")
	script.WriteString("                                    $setTasks = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.ScheduleOptions -and $repo.ScheduleOptions.Enabled) { $setTasks = 1 }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Host information\n")
	script.WriteString("                                    $hostNames = @()\n")
	script.WriteString("                                    $hostName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Host) {\n")
	script.WriteString("                                            $hostName = $repo.Host.Name\n")
	script.WriteString("                                            $hostNames += $repo.Host.Name\n")
	script.WriteString("                                        } elseif ($repo.Hosts) {\n")
	script.WriteString("                                            foreach ($h in $repo.Hosts) {\n")
	script.WriteString("                                                if ($h.Name) { $hostNames += $h.Name }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $hostName = $hostNames -join ', '\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Path\n")
	script.WriteString("                                    $path = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Path) { $path = $repo.Path }\n")
	script.WriteString("                                        elseif ($repo.FriendlyPath) { $path = $repo.FriendlyPath }\n")
	script.WriteString("                                        elseif ($repo.RepositoryPath) { $path = $repo.RepositoryPath }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Cores and RAM from host\n")
	script.WriteString("                                    $cores = 0\n")
	script.WriteString("                                    $ram = 0\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Host) {\n")
	script.WriteString("                                            $hostInfo = $repo.Host\n")
	script.WriteString("                                            if ($hostInfo.CpuCount) { $cores = $hostInfo.CpuCount }\n")
	script.WriteString("                                            elseif ($hostInfo.Cores) { $cores = $hostInfo.Cores }\n")
	script.WriteString("                                            if ($hostInfo.Memory) { $ram = [math]::Round($hostInfo.Memory / 1GB, 0) }\n")
	script.WriteString("                                            elseif ($hostInfo.Ram) { $ram = [math]::Round($hostInfo.Ram / 1GB, 0) }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Auto Gateway\n")
	script.WriteString("                                    $autoGateway = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.AutoGateway) { $autoGateway = $repo.Options.AutoGateway }\n")
	script.WriteString("                                        elseif ($repo.AutoGateway) { $autoGateway = $repo.AutoGateway }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Per-VM\n")
	script.WriteString("                                    $perVM = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.UsePerVMBackupFiles) { $perVM = $repo.Options.UsePerVMBackupFiles }\n")
	script.WriteString("                                        elseif ($repo.UsePerVMBackupFiles) { $perVM = $repo.UsePerVMBackupFiles }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get DeCompress\n")
	script.WriteString("                                    $decompress = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.DecompressBeforeStorage) { $decompress = $repo.Options.DecompressBeforeStorage }\n")
	script.WriteString("                                        elseif ($repo.DecompressBeforeStorage) { $decompress = $repo.DecompressBeforeStorage }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Align Blocks\n")
	script.WriteString("                                    $alignBlocks = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.AlignDataBlocks) { $alignBlocks = $repo.Options.AlignDataBlocks }\n")
	script.WriteString("                                        elseif ($repo.AlignDataBlocks) { $alignBlocks = $repo.AlignDataBlocks }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Rotated Drives\n")
	script.WriteString("                                    $rotatedDrives = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.RotatedDrives) { $rotatedDrives = $repo.Options.RotatedDrives }\n")
	script.WriteString("                                        elseif ($repo.RotatedDrives) { $rotatedDrives = $repo.RotatedDrives }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Use Immutability\n")
	script.WriteString("                                    $useImmutability = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.Options -and $repo.Options.ImmutabilityEnabled) { $useImmutability = $repo.Options.ImmutabilityEnabled }\n")
	script.WriteString("                                        elseif ($repo.ImmutabilityEnabled) { $useImmutability = $repo.ImmutabilityEnabled }\n")
	script.WriteString("                                        elseif ($repo.IsImmutabilityEnabled) { $useImmutability = $repo.IsImmutabilityEnabled }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $repoList += @{\n")
	script.WriteString("                                        'Id' = $repo.Id\n")
	script.WriteString("                                        'Name' = $repo.Name\n")
	script.WriteString("                                        'Type' = $typeName\n")
	script.WriteString("                                        'Status' = $statusName\n")
	script.WriteString("                                        'IsUnavailable' = if ($repo.IsUnavailable -ne $null) { $repo.IsUnavailable } else { $false }\n")
	script.WriteString("                                        'CachedTotalSpaceGB' = $cachedTotalSpaceGB\n")
	script.WriteString("                                        'CachedFreeSpaceGB' = $cachedFreeSpaceGB\n")
	script.WriteString("                                        'FreeSpacePercent' = $freeSpacePercent\n")
	script.WriteString("                                        'JobCount' = $jobCount\n")
	script.WriteString("                                        'SetTasks' = $setTasks\n")
	script.WriteString("                                        'Cores' = $cores\n")
	script.WriteString("                                        'Ram' = $ram\n")
	script.WriteString("                                        'AutoGateway' = $autoGateway\n")
	script.WriteString("                                        'Host' = $hostName\n")
	script.WriteString("                                        'Hosts' = $hostNames\n")
	script.WriteString("                                        'Path' = $path\n")
	script.WriteString("                                        'PerVM' = $perVM\n")
	script.WriteString("                                        'Decompress' = $decompress\n")
	script.WriteString("                                        'AlignBlocks' = $alignBlocks\n")
	script.WriteString("                                        'RotatedDrives' = $rotatedDrives\n")
	script.WriteString("                                        'UseImmutability' = $useImmutability\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $repoList += @{\n")
	script.WriteString("                                        'Id' = $repo.Id\n")
	script.WriteString("                                        'Name' = $repo.Name\n")
	script.WriteString("                                        'Type' = 'N/A'\n")
	script.WriteString("                                        'Status' = 'N/A'\n")
	script.WriteString("                                        'Error' = 'Failed to collect detailed information'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['repositories'] = $repoList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Scale-Out Backup Repositories (SOBR)\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Scale-Out Backup Repositories\" -Status \"Enumerating SOBR repositories and policies\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $sobrs = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $sobrList = @()\n")
	script.WriteString("                            $sobrExtentsList = @()\n")
	script.WriteString("                            if ($sobrs) {\n")
	script.WriteString("                                foreach ($sobr in $sobrs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $sobrName = $sobr.Name\n")
	script.WriteString("                                        $sobrId = $sobr.Id\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $extentsCount = 0\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.Extents) { $extentsCount = $sobr.Extents.Count }\n")
	script.WriteString("                                            elseif ($sobr.GetExtents) { $extentsCount = ($sobr.GetExtents()).Count }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $jobCount = 0\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                                            if ($jobs) {\n")
	script.WriteString("                                                foreach ($job in $jobs) {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        if ($job.TargetRepositoryId -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                        elseif ($job.TargetRepository -and $job.TargetRepository.Id -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                        elseif ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.TargetRepositoryId -eq $sobrId) { $jobCount++ }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $policy = 'N/A'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.PolicyType) { $policy = $sobr.PolicyType.ToString() }\n")
	script.WriteString("                                            elseif ($sobr.Policy) { $policy = $sobr.Policy.ToString() }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $capacityTier = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.EnableCapacityTier) { $capacityTier = $sobr.EnableCapacityTier }\n")
	script.WriteString("                                            elseif ($sobr.CapacityTierEnabled) { $capacityTier = $sobr.CapacityTierEnabled }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $copyEnabled = $false\n")
	script.WriteString("                                        $moveEnabled = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions) {\n")
	script.WriteString("                                                $copyEnabled = $sobr.CapacityTierOptions.CopyEnabled\n")
	script.WriteString("                                                $moveEnabled = $sobr.CapacityTierOptions.MoveEnabled\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $archiveTier = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.ArchiveTierEnabled) { $archiveTier = $sobr.ArchiveTierEnabled }\n")
	script.WriteString("                                            elseif ($sobr.EnableArchiveTier) { $archiveTier = $sobr.EnableArchiveTier }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $perMachine = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.UsePerVMBackupFiles) { $perMachine = $sobr.UsePerVMBackupFiles }\n")
	script.WriteString("                                            elseif ($sobr.PerVMBackupFiles) { $perMachine = $sobr.PerVMBackupFiles }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $capTierType = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.TierType) {\n")
	script.WriteString("                                                $capTierType = $sobr.CapacityTierOptions.TierType.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $immutable = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.ImmutabilityEnabled) {\n")
	script.WriteString("                                                $immutable = $sobr.CapacityTierOptions.ImmutabilityEnabled\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $immutablePeriod = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.CapacityTierOptions -and $sobr.CapacityTierOptions.ImmutabilityPeriodDays) {\n")
	script.WriteString("                                                $immutablePeriod = $sobr.CapacityTierOptions.ImmutabilityPeriodDays\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sizeLimitEnabled = $false\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.SizeLimitEnabled) { $sizeLimitEnabled = $sobr.SizeLimitEnabled }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sizeLimit = ''\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($sobr.SizeLimit) {\n")
	script.WriteString("                                                $sizeLimit = [math]::Round($sobr.SizeLimit / 1GB, 0)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $sobrList += @{\n")
	script.WriteString("                                            'Id' = $sobrId\n")
	script.WriteString("                                            'Name' = $sobrName\n")
	script.WriteString("                                            'Extents' = $extentsCount\n")
	script.WriteString("                                            'JobCount' = $jobCount\n")
	script.WriteString("                                            'Policy' = $policy\n")
	script.WriteString("                                            'CapacityTier' = $capacityTier\n")
	script.WriteString("                                            'Copy' = $copyEnabled\n")
	script.WriteString("                                            'Move' = $moveEnabled\n")
	script.WriteString("                                            'ArchiveTier' = $archiveTier\n")
	script.WriteString("                                            'PerMachine' = $perMachine\n")
	script.WriteString("                                            'CapTierType' = $capTierType\n")
	script.WriteString("                                            'Immutable' = $immutable\n")
	script.WriteString("                                            'ImmutablePeriod' = $immutablePeriod\n")
	script.WriteString("                                            'SizeLimitEnabled' = $sizeLimitEnabled\n")
	script.WriteString("                                            'SizeLimit' = $sizeLimit\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $extents = $null\n")
	script.WriteString("                                            if ($sobr.Extents) { $extents = $sobr.Extents }\n")
	script.WriteString("                                            elseif ($sobr.GetExtents) { $extents = $sobr.GetExtents() }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            if ($extents) {\n")
	script.WriteString("                                                foreach ($extent in $extents) {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        $extentRepo = $null\n")
	script.WriteString("                                                        if ($extent.Repository) { $extentRepo = $extent.Repository }\n")
	script.WriteString("                                                        elseif ($extent.BackupRepository) { $extentRepo = $extent.BackupRepository }\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        if ($extentRepo) {\n")
	script.WriteString("                                                            $extentTotalSpaceGB = 0\n")
	script.WriteString("                                                            $extentFreeSpaceGB = 0\n")
	script.WriteString("                                                            $extentFreeSpacePercent = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $container = $extentRepo.getcontainer()\n")
	script.WriteString("                                                                if ($container) {\n")
	script.WriteString("                                                                    if ($container.CachedTotalSpace) {\n")
	script.WriteString("                                                                        $extentTotalSpaceGB = [math]::Round($container.CachedTotalSpace.ingigabytes, 2)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    if ($container.CachedFreeSpace) {\n")
	script.WriteString("                                                                        $extentFreeSpaceGB = [math]::Round($container.CachedFreeSpace.ingigabytes, 2)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    if ($extentTotalSpaceGB -gt 0) {\n")
	script.WriteString("                                                                        $extentFreeSpacePercent = [math]::Round(($extentFreeSpaceGB / $extentTotalSpaceGB) * 100, 1)\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentSetTasks = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.ScheduleOptions -and $extentRepo.ScheduleOptions.Enabled) { $extentSetTasks = 1 }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentHostNames = @()\n")
	script.WriteString("                                                            $extentHostName = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Host) {\n")
	script.WriteString("                                                                    $extentHostName = $extentRepo.Host.Name\n")
	script.WriteString("                                                                    $extentHostNames += $extentRepo.Host.Name\n")
	script.WriteString("                                                                } elseif ($extentRepo.Hosts) {\n")
	script.WriteString("                                                                    foreach ($h in $extentRepo.Hosts) {\n")
	script.WriteString("                                                                        if ($h.Name) { $extentHostNames += $h.Name }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    $extentHostName = $extentHostNames -join ', '\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentPath = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Path) { $extentPath = $extentRepo.Path }\n")
	script.WriteString("                                                                elseif ($extentRepo.FriendlyPath) { $extentPath = $extentRepo.FriendlyPath }\n")
	script.WriteString("                                                                elseif ($extentRepo.RepositoryPath) { $extentPath = $extentRepo.RepositoryPath }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentCores = 0\n")
	script.WriteString("                                                            $extentRam = 0\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Host) {\n")
	script.WriteString("                                                                    $hostInfo = $extentRepo.Host\n")
	script.WriteString("                                                                    if ($hostInfo.CpuCount) { $extentCores = $hostInfo.CpuCount }\n")
	script.WriteString("                                                                    elseif ($hostInfo.Cores) { $extentCores = $hostInfo.Cores }\n")
	script.WriteString("                                                                    if ($hostInfo.Memory) { $extentRam = [math]::Round($hostInfo.Memory / 1GB, 0) }\n")
	script.WriteString("                                                                    elseif ($hostInfo.Ram) { $extentRam = [math]::Round($hostInfo.Ram / 1GB, 0) }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentAutoGateway = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.AutoGateway) { $extentAutoGateway = $extentRepo.Options.AutoGateway }\n")
	script.WriteString("                                                                elseif ($extentRepo.AutoGateway) { $extentAutoGateway = $extentRepo.AutoGateway }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentDecompress = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.DecompressBeforeStorage) { $extentDecompress = $extentRepo.Options.DecompressBeforeStorage }\n")
	script.WriteString("                                                                elseif ($extentRepo.DecompressBeforeStorage) { $extentDecompress = $extentRepo.DecompressBeforeStorage }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentAlignBlocks = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.AlignDataBlocks) { $extentAlignBlocks = $extentRepo.Options.AlignDataBlocks }\n")
	script.WriteString("                                                                elseif ($extentRepo.AlignDataBlocks) { $extentAlignBlocks = $extentRepo.AlignDataBlocks }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentRotatedDrives = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.RotatedDrives) { $extentRotatedDrives = $extentRepo.Options.RotatedDrives }\n")
	script.WriteString("                                                                elseif ($extentRepo.RotatedDrives) { $extentRotatedDrives = $extentRepo.RotatedDrives }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentUseImmutability = $false\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                if ($extentRepo.Options -and $extentRepo.Options.ImmutabilityEnabled) { $extentUseImmutability = $extentRepo.Options.ImmutabilityEnabled }\n")
	script.WriteString("                                                                elseif ($extentRepo.ImmutabilityEnabled) { $extentUseImmutability = $extentRepo.ImmutabilityEnabled }\n")
	script.WriteString("                                                                elseif ($extentRepo.IsImmutabilityEnabled) { $extentUseImmutability = $extentRepo.IsImmutabilityEnabled }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $extentType = 'N/A'\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $extentTypeValue = $extentRepo.Type\n")
	script.WriteString("                                                                if ($extentTypeValue -is [enum]) {\n")
	script.WriteString("                                                                    $extentType = $extentTypeValue.ToString()\n")
	script.WriteString("                                                                } elseif ($extentTypeValue -is [int] -or $extentTypeValue -is [System.Int32]) {\n")
	script.WriteString("                                                                    switch ([int]$extentTypeValue) {\n")
	script.WriteString("                                                                        0 { $extentType = 'Windows' }\n")
	script.WriteString("                                                                        1 { $extentType = 'Linux' }\n")
	script.WriteString("                                                                        2 { $extentType = 'SharedFolder' }\n")
	script.WriteString("                                                                        3 { $extentType = 'DedupeStorage' }\n")
	script.WriteString("                                                                        4 { $extentType = 'AmazonS3Compatible' }\n")
	script.WriteString("                                                                        5 { $extentType = 'AzureBlob' }\n")
	script.WriteString("                                                                        6 { $extentType = 'AmazonS3' }\n")
	script.WriteString("                                                                        7 { $extentType = 'WasabiS3' }\n")
	script.WriteString("                                                                        default { $extentType = \"Type_$extentTypeValue\" }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $extentType = if ($extentTypeValue) { $extentTypeValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {\n")
	script.WriteString("                                                                $extentType = if ($extentRepo.Type) { $extentRepo.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            $sobrExtentsList += @{\n")
	script.WriteString("                                                                'Name' = $extentRepo.Name\n")
	script.WriteString("                                                                'SOBR' = $sobrName\n")
	script.WriteString("                                                                'SetTasks' = $extentSetTasks\n")
	script.WriteString("                                                                'Cores' = $extentCores\n")
	script.WriteString("                                                                'Ram' = $extentRam\n")
	script.WriteString("                                                                'AutoGateway' = $extentAutoGateway\n")
	script.WriteString("                                                                'Host' = $extentHostName\n")
	script.WriteString("                                                                'Hosts' = $extentHostNames\n")
	script.WriteString("                                                                'Path' = $extentPath\n")
	script.WriteString("                                                                'FreeSpaceGB' = $extentFreeSpaceGB\n")
	script.WriteString("                                                                'TotalSpaceGB' = $extentTotalSpaceGB\n")
	script.WriteString("                                                                'FreeSpacePercent' = $extentFreeSpacePercent\n")
	script.WriteString("                                                                'Decompress' = $extentDecompress\n")
	script.WriteString("                                                                'AlignBlocks' = $extentAlignBlocks\n")
	script.WriteString("                                                                'RotatedDrives' = $extentRotatedDrives\n")
	script.WriteString("                                                                'UseImmutability' = $extentUseImmutability\n")
	script.WriteString("                                                                'Type' = $extentType\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['sobrs'] = $sobrList\n")
	script.WriteString("                            $veeamInfo['sobrExtents'] = $sobrExtentsList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Security Credentials\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Security Credentials\" -Status \"Enumerating managed credentials\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $credentials = Get-VBRCredentials -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $credentialsList = @()\n")
	script.WriteString("                            if ($credentials) {\n")
	script.WriteString("                                foreach ($cred in $credentials) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $credName = if ($cred.Name) { $cred.Name } else { 'N/A' }\n")
	script.WriteString("                                        $credDescription = if ($cred.Description) { $cred.Description } else { 'N/A' }\n")
	script.WriteString("                                        $credentialsList += @{\n")
	script.WriteString("                                            'name' = $credName\n")
	script.WriteString("                                            'description' = $credDescription\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['securityCredentials'] = $credentialsList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Jobs with detailed information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Jobs\" -Status \"Enumerating backup, replica, and copy jobs\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $jobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $backupJobList = @()\n")
	script.WriteString("                            $replicaJobList = @()\n")
	script.WriteString("                            $fileCopyJobList = @()\n")
	script.WriteString("                            $backupCopyJobList = @()\n")
	script.WriteString("                            $fileBackupJobList = @()\n")
	script.WriteString("                            \n")
	script.WriteString("                            foreach ($job in $jobs) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Get repository name\n")
	script.WriteString("                                    $repositoryName = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($job.GetTargetRepository()) {\n")
	script.WriteString("                                            $repositoryName = $job.GetTargetRepository().Name\n")
	script.WriteString("                                        } elseif ($job.GetBackupRepository()) {\n")
	script.WriteString("                                            $repositoryName = $job.GetBackupRepository().Name\n")
	script.WriteString("                                        } elseif ($job.TargetDir) {\n")
	script.WriteString("                                            $repositoryName = $job.TargetDir\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get source size (for backup/replica/backup copy jobs)\n")
	script.WriteString("                                    $sourceSize = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Try multiple methods to get source size\n")
	script.WriteString("                                        $sourceSizeBytes = $null\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Method 1: GetSourceSize() method\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $sourceSizeBytes = $job.GetSourceSize()\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Method 2: Info.IncludedSize property\n")
	script.WriteString("                                        if (-not $sourceSizeBytes -or $sourceSizeBytes -eq 0) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Info -and $job.Info.IncludedSize) {\n")
	script.WriteString("                                                    $sourceSizeBytes = $job.Info.IncludedSize\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Method 3: Get last session source size\n")
	script.WriteString("                                        if (-not $sourceSizeBytes -or $sourceSizeBytes -eq 0) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                $lastSession = [Veeam.Backup.Core.CBackupSession]::GetByJob($job.Id) | Sort-Object -Property CreationTimeUTC -Descending | Select-Object -First 1\n")
	script.WriteString("                                                if ($lastSession -and $lastSession.Progress -and $lastSession.Progress.ProcessedSize) {\n")
	script.WriteString("                                                    $sourceSizeBytes = $lastSession.Progress.ProcessedSize\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Format the size\n")
	script.WriteString("                                        if ($sourceSizeBytes -and $sourceSizeBytes -gt 0) {\n")
	script.WriteString("                                            if ($sourceSizeBytes -gt 1TB) {\n")
	script.WriteString("                                                $sourceSize = \"$([math]::Round($sourceSizeBytes / 1TB, 2)) TB\"\n")
	script.WriteString("                                            } elseif ($sourceSizeBytes -gt 1GB) {\n")
	script.WriteString("                                                $sourceSize = \"$([math]::Round($sourceSizeBytes / 1GB, 2)) GB\"\n")
	script.WriteString("                                            } elseif ($sourceSizeBytes -gt 1MB) {\n")
	script.WriteString("                                                $sourceSize = \"$([math]::Round($sourceSizeBytes / 1MB, 2)) MB\"\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $sourceSize = \"$([math]::Round($sourceSizeBytes / 1KB, 2)) KB\"\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get job options\n")
	script.WriteString("                                    $retentionScheme = 'Days'\n")
	script.WriteString("                                    $restorePoints = 'N/A'\n")
	script.WriteString("                                    $encrypted = $false\n")
	script.WriteString("                                    $compressionLevel = 'N/A'\n")
	script.WriteString("                                    $blockSize = 'N/A'\n")
	script.WriteString("                                    $gfsEnabled = $false\n")
	script.WriteString("                                    $gfsRetention = ''\n")
	script.WriteString("                                    $activeFullEnabled = $false\n")
	script.WriteString("                                    $syntheticFullEnabled = $false\n")
	script.WriteString("                                    $backupChainType = 'N/A'\n")
	script.WriteString("                                    $indexingEnabled = $false\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($job.Options.BackupStorageOptions) {\n")
	script.WriteString("                                            $retentionScheme = if ($job.Options.BackupStorageOptions.RetentionPolicyType) { $job.Options.BackupStorageOptions.RetentionPolicyType.ToString() } else { 'Days' }\n")
	script.WriteString("                                            $restorePoints = if ($job.Options.BackupStorageOptions.RetainCycles) { $job.Options.BackupStorageOptions.RetainCycles } else { 'N/A' }\n")
	script.WriteString("                                            $encrypted = if ($job.Options.BackupStorageOptions.EncryptionEnabled) { $job.Options.BackupStorageOptions.EncryptionEnabled } else { $false }\n")
	script.WriteString("                                            # Convert CompressionLevel enum to name\n")
	script.WriteString("                                            $compressionLevelValue = $job.Options.BackupStorageOptions.CompressionLevel\n")
	script.WriteString("                                            if ($compressionLevelValue -is [enum]) {\n")
	script.WriteString("                                                $compressionLevel = $compressionLevelValue.ToString()\n")
	script.WriteString("                                            } elseif ($compressionLevelValue -is [int]) {\n")
	script.WriteString("                                                switch ($compressionLevelValue) {\n")
	script.WriteString("                                                    0 { $compressionLevel = 'None' }\n")
	script.WriteString("                                                    1 { $compressionLevel = 'DedupeFriendly' }\n")
	script.WriteString("                                                    2 { $compressionLevel = 'Optimal' }\n")
	script.WriteString("                                                    3 { $compressionLevel = 'High' }\n")
	script.WriteString("                                                    4 { $compressionLevel = 'Extreme' }\n")
	script.WriteString("                                                    default { $compressionLevel = \"Level_$compressionLevelValue\" }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $compressionLevel = if ($compressionLevelValue) { $compressionLevelValue.ToString() } else { 'N/A' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            # Convert BlockSize enum to name\n")
	script.WriteString("                                            $blockSizeValue = $null\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                # Try different property names\n")
	script.WriteString("                                                if ($job.Options.BackupStorageOptions.BlockSize) {\n")
	script.WriteString("                                                    $blockSizeValue = $job.Options.BackupStorageOptions.BlockSize\n")
	script.WriteString("                                                } elseif ($job.Options.BackupStorageOptions.StgBlockSize) {\n")
	script.WriteString("                                                    $blockSizeValue = $job.Options.BackupStorageOptions.StgBlockSize\n")
	script.WriteString("                                                } elseif ($job.Options.BlockSize) {\n")
	script.WriteString("                                                    $blockSizeValue = $job.Options.BlockSize\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            if ($blockSizeValue) {\n")
	script.WriteString("                                                $blockSizeStr = $blockSizeValue.ToString()\n")
	script.WriteString("                                                # Convert enum names to readable format\n")
	script.WriteString("                                                switch ($blockSizeStr) {\n")
	script.WriteString("                                                    'KbBlockSize512' { $blockSize = '512 KB' }\n")
	script.WriteString("                                                    'KbBlockSize1024' { $blockSize = '1 MB' }\n")
	script.WriteString("                                                    'KbBlockSize2048' { $blockSize = '2 MB' }\n")
	script.WriteString("                                                    'KbBlockSize4096' { $blockSize = '4 MB' }\n")
	script.WriteString("                                                    'KbBlockSize8192' { $blockSize = '8 MB' }\n")
	script.WriteString("                                                    'KbBlockSize256' { $blockSize = '256 KB' }\n")
	script.WriteString("                                                    default {\n")
	script.WriteString("                                                        # Try to parse as integer\n")
	script.WriteString("                                                        if ($blockSizeValue -is [int] -or $blockSizeValue -is [System.Int32]) {\n")
	script.WriteString("                                                            switch ([int]$blockSizeValue) {\n")
	script.WriteString("                                                                0 { $blockSize = '512 KB' }\n")
	script.WriteString("                                                                1 { $blockSize = '1 MB' }\n")
	script.WriteString("                                                                2 { $blockSize = '2 MB' }\n")
	script.WriteString("                                                                3 { $blockSize = '4 MB' }\n")
	script.WriteString("                                                                4 { $blockSize = '8 MB' }\n")
	script.WriteString("                                                                default { $blockSize = $blockSizeStr }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $blockSize = $blockSizeStr\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $blockSize = 'N/A'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($job.Options.BackupStorageOptions.GfsPolicy) {\n")
	script.WriteString("                                                $gfsEnabled = $job.Options.BackupStorageOptions.GfsPolicy.Enabled\n")
	script.WriteString("                                                if ($gfsEnabled) {\n")
	script.WriteString("                                                    $gfsRetention = @()\n")
	script.WriteString("                                                    if ($job.Options.BackupStorageOptions.GfsPolicy.WeeklyBackups) { $gfsRetention += \"Weekly: $($job.Options.BackupStorageOptions.GfsPolicy.WeeklyBackups)\" }\n")
	script.WriteString("                                                    if ($job.Options.BackupStorageOptions.GfsPolicy.MonthlyBackups) { $gfsRetention += \"Monthly: $($job.Options.BackupStorageOptions.GfsPolicy.MonthlyBackups)\" }\n")
	script.WriteString("                                                    if ($job.Options.BackupStorageOptions.GfsPolicy.YearlyBackups) { $gfsRetention += \"Yearly: $($job.Options.BackupStorageOptions.GfsPolicy.YearlyBackups)\" }\n")
	script.WriteString("                                                    $gfsRetention = $gfsRetention -join \"`n\"\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            # Get Active Full Enabled - try multiple methods\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Options.BackupStorageOptions.FullBackupScheduleOptions) {\n")
	script.WriteString("                                                    $activeFullEnabled = $job.Options.BackupStorageOptions.FullBackupScheduleOptions.Enabled\n")
	script.WriteString("                                                } elseif ($job.Options.BackupStorageOptions.EnableFullBackup) {\n")
	script.WriteString("                                                    $activeFullEnabled = $job.Options.BackupStorageOptions.EnableFullBackup\n")
	script.WriteString("                                                } elseif ($job.Options.BackupTargetOptions.FullBackupScheduleKind) {\n")
	script.WriteString("                                                    $activeFullEnabled = $true\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Get Synthetic Full Enabled - try multiple methods\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Options.BackupStorageOptions.SyntheticFullBackupScheduleOptions) {\n")
	script.WriteString("                                                    $syntheticFullEnabled = $job.Options.BackupStorageOptions.SyntheticFullBackupScheduleOptions.Enabled\n")
	script.WriteString("                                                } elseif ($job.Options.BackupTargetOptions.TransformIncrementsToSyntethic) {\n")
	script.WriteString("                                                    $syntheticFullEnabled = $job.Options.BackupTargetOptions.TransformIncrementsToSyntethic\n")
	script.WriteString("                                                } elseif ($job.Options.BackupTargetOptions.TransformFullToSyntethic) {\n")
	script.WriteString("                                                    $syntheticFullEnabled = $job.Options.BackupTargetOptions.TransformFullToSyntethic\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                            # Convert BackupMode enum to name\n")
	script.WriteString("                                            $backupModeValue = $null\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                # Try different property names\n")
	script.WriteString("                                                if ($job.Options.BackupStorageOptions.BackupMode) {\n")
	script.WriteString("                                                    $backupModeValue = $job.Options.BackupStorageOptions.BackupMode\n")
	script.WriteString("                                                } elseif ($job.Options.BackupTargetOptions.BackupMode) {\n")
	script.WriteString("                                                    $backupModeValue = $job.Options.BackupTargetOptions.BackupMode\n")
	script.WriteString("                                                } elseif ($job.Options.BackupTargetOptions.Algorithm) {\n")
	script.WriteString("                                                    $backupModeValue = $job.Options.BackupTargetOptions.Algorithm\n")
	script.WriteString("                                                } elseif ($job.Options.BackupMode) {\n")
	script.WriteString("                                                    $backupModeValue = $job.Options.BackupMode\n")
	script.WriteString("                                                } elseif ($job.BackupMode) {\n")
	script.WriteString("                                                    $backupModeValue = $job.BackupMode\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            if ($backupModeValue) {\n")
	script.WriteString("                                                $backupModeStr = $backupModeValue.ToString()\n")
	script.WriteString("                                                # Convert enum names and algorithm to readable format\n")
	script.WriteString("                                                switch ($backupModeStr) {\n")
	script.WriteString("                                                    'Increment' { $backupChainType = 'Forward Incremental' }\n")
	script.WriteString("                                                    'Syntethic' { $backupChainType = 'Reverse Incremental' }\n")
	script.WriteString("                                                    'Synthetic' { $backupChainType = 'Reverse Incremental' }\n")
	script.WriteString("                                                    'Forward' { $backupChainType = 'Forward Incremental' }\n")
	script.WriteString("                                                    'Reverse' { $backupChainType = 'Reverse Incremental' }\n")
	script.WriteString("                                                    'Full' { $backupChainType = 'Always Full' }\n")
	script.WriteString("                                                    default {\n")
	script.WriteString("                                                        # Try to parse as integer\n")
	script.WriteString("                                                        if ($backupModeValue -is [int] -or $backupModeValue -is [System.Int32]) {\n")
	script.WriteString("                                                            switch ([int]$backupModeValue) {\n")
	script.WriteString("                                                                0 { $backupChainType = 'Forward Incremental' }\n")
	script.WriteString("                                                                1 { $backupChainType = 'Reverse Incremental' }\n")
	script.WriteString("                                                                2 { $backupChainType = 'Always Full' }\n")
	script.WriteString("                                                                default { $backupChainType = $backupModeStr }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $backupChainType = $backupModeStr\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $backupChainType = 'N/A'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $indexingEnabled = if ($job.Options.BackupStorageOptions.EnableIndexing) { $job.Options.BackupStorageOptions.EnableIndexing } else { $false }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Job Is Enabled\n")
	script.WriteString("                                    $isEnabled = $false\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($job.IsScheduleEnabled -ne $null) {\n")
	script.WriteString("                                            $isEnabled = [bool]$job.IsScheduleEnabled\n")
	script.WriteString("                                        } elseif ($job.ScheduleOptions -and $job.ScheduleOptions.Enabled -ne $null) {\n")
	script.WriteString("                                            $isEnabled = [bool]$job.ScheduleOptions.Enabled\n")
	script.WriteString("                                        } elseif ($job.Enabled -ne $null) {\n")
	script.WriteString("                                            $isEnabled = [bool]$job.Enabled\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Last Run, Last Result, Next Run\n")
	script.WriteString("                                    $lastRun = 'N/A'\n")
	script.WriteString("                                    $lastResult = 'N/A'\n")
	script.WriteString("                                    $nextRun = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get LastRun from LatestRunLocal first (direct property from job)\n")
	script.WriteString("                                        if ($job.LatestRunLocal -and $job.LatestRunLocal -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $lastRun = $job.LatestRunLocal.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.ScheduleOptions -and $job.ScheduleOptions.LatestRunTime -and $job.ScheduleOptions.LatestRunTime -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $lastRun = $job.ScheduleOptions.LatestRunTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get NextRun from ScheduleOptions\n")
	script.WriteString("                                        if ($job.ScheduleOptions -and $job.ScheduleOptions.NextRun -and $job.ScheduleOptions.NextRun -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $nextRun = $job.ScheduleOptions.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.NextRun -and $job.NextRun -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $nextRun = $job.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.ScheduleOptions -and $job.ScheduleOptions.Options -and $job.ScheduleOptions.Options.NextRun -and $job.ScheduleOptions.Options.NextRun -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $nextRun = $job.ScheduleOptions.Options.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get last session for LastRun (if not already set) and LastResult\n")
	script.WriteString("                                        $lastSession = $null\n")
	script.WriteString("                                        if ($lastRun -eq 'N/A') {\n")
	script.WriteString("                                            # Only try to get LastRun from session if we don't have it from LatestRunLocal\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                # Try CBackupSession first (works for both VMware and Hyper-V)\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $lastSession = [Veeam.Backup.Core.CBackupSession]::GetByJob($job.Id) | Sort-Object -Property CreationTimeUTC -Descending | Select-Object -First 1\n")
	script.WriteString("                                                } catch {\n")
	script.WriteString("                                                    # Fallback: Try Get-VBRBackupSession\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        $lastSession = Get-VBRBackupSession -Job $job | Sort-Object -Property CreationTime -Descending | Select-Object -First 1\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                if ($lastSession) {\n")
	script.WriteString("                                                    # Get LastRun - try multiple properties\n")
	script.WriteString("                                                    if ($lastSession.CreationTimeUTC -and $lastSession.CreationTimeUTC -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                                        $lastRun = $lastSession.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                                    } elseif ($lastSession.CreationTime -and $lastSession.CreationTime -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                                        $lastRun = $lastSession.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                                    } elseif ($lastSession.EndTimeUTC -and $lastSession.EndTimeUTC -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                                        $lastRun = $lastSession.EndTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                                    } elseif ($lastSession.EndTime -and $lastSession.EndTime -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                                        $lastRun = $lastSession.EndTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            # If we have LastRun from LatestRunLocal, still try to get LastResult from session\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $lastSession = [Veeam.Backup.Core.CBackupSession]::GetByJob($job.Id) | Sort-Object -Property CreationTimeUTC -Descending | Select-Object -First 1\n")
	script.WriteString("                                                } catch {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        $lastSession = Get-VBRBackupSession -Job $job | Sort-Object -Property CreationTime -Descending | Select-Object -First 1\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get LastResult from session if available\n")
	script.WriteString("                                        if ($lastSession) {\n")
	script.WriteString("                                            # Get LastResult - try multiple properties\n")
	script.WriteString("                                            if ($lastSession.Result) {\n")
	script.WriteString("                                                $resultValue = $lastSession.Result\n")
	script.WriteString("                                                if ($resultValue -is [enum]) {\n")
	script.WriteString("                                                    $lastResult = $resultValue.ToString()\n")
	script.WriteString("                                                } else {\n")
	script.WriteString("                                                    $resultStr = $resultValue.ToString()\n")
	script.WriteString("                                                    if ($resultStr -eq 'Success' -or $resultStr -eq 'Ok' -or $resultStr -eq '0') {\n")
	script.WriteString("                                                        $lastResult = 'Success'\n")
	script.WriteString("                                                    } elseif ($resultStr -eq 'Warning' -or $resultStr -eq '1') {\n")
	script.WriteString("                                                        $lastResult = 'Warning'\n")
	script.WriteString("                                                    } elseif ($resultStr -eq 'Failed' -or $resultStr -eq 'Error' -or $resultStr -eq '2') {\n")
	script.WriteString("                                                        $lastResult = 'Failed'\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $lastResult = $resultStr\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($lastSession.State) {\n")
	script.WriteString("                                                # Fallback to State if Result is not available\n")
	script.WriteString("                                                $stateStr = $lastSession.State.ToString()\n")
	script.WriteString("                                                if ($stateStr -eq 'Success' -or $stateStr -eq 'Stopped') {\n")
	script.WriteString("                                                    $lastResult = 'Success'\n")
	script.WriteString("                                                } elseif ($stateStr -eq 'Warning') {\n")
	script.WriteString("                                                    $lastResult = 'Warning'\n")
	script.WriteString("                                                } elseif ($stateStr -eq 'Failed' -or $stateStr -eq 'Error') {\n")
	script.WriteString("                                                    $lastResult = 'Failed'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Creation Time\n")
	script.WriteString("                                    $creationTime = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Try multiple methods to get creation time\n")
	script.WriteString("                                        if ($job.Info -and $job.Info.CreationTimeUTC -and $job.Info.CreationTimeUTC -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $creationTime = $job.Info.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.CreationTimeUTC -and $job.CreationTimeUTC -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $creationTime = $job.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.CreationTime -and $job.CreationTime -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                            $creationTime = $job.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($job.GetType().GetProperty('CreationTimeUTC')) {\n")
	script.WriteString("                                            $prop = $job.GetType().GetProperty('CreationTimeUTC')\n")
	script.WriteString("                                            if ($prop) {\n")
	script.WriteString("                                                $ctValue = $prop.GetValue($job)\n")
	script.WriteString("                                                if ($ctValue -and $ctValue -ne [DateTime]::MinValue) {\n")
	script.WriteString("                                                    $creationTime = $ctValue.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get VM/Object Count and Details\n")
	script.WriteString("                                    $vmCount = 'N/A'\n")
	script.WriteString("                                    $vmList = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $objects = $null\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Try multiple methods to get objects\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($job.GetObjects()) {\n")
	script.WriteString("                                                $objects = $job.GetObjects()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if (-not $objects) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Objects) {\n")
	script.WriteString("                                                    $objects = $job.Objects\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if (-not $objects) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                $container = $job.GetContainer()\n")
	script.WriteString("                                                if ($container -and $container.GetObjects()) {\n")
	script.WriteString("                                                    $objects = $container.GetObjects()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Try to get from job options\n")
	script.WriteString("                                        if (-not $objects) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Options -and $job.Options.JobOptions -and $job.Options.JobOptions.IncludedVms) {\n")
	script.WriteString("                                                    $objects = $job.Options.JobOptions.IncludedVms\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Try to get from backup target options\n")
	script.WriteString("                                        if (-not $objects) {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($job.Options -and $job.Options.BackupTargetOptions -and $job.Options.BackupTargetOptions.VmIds) {\n")
	script.WriteString("                                                    # Get VM names from IDs\n")
	script.WriteString("                                                    $vmIds = $job.Options.BackupTargetOptions.VmIds\n")
	script.WriteString("                                                    $objects = @()\n")
	script.WriteString("                                                    foreach ($vmId in $vmIds) {\n")
	script.WriteString("                                                        try {\n")
	script.WriteString("                                                            $vm = Get-VBRServerObject -Id $vmId -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                            if ($vm) { $objects += $vm }\n")
	script.WriteString("                                                        } catch {}\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($objects) {\n")
	script.WriteString("                                            if ($objects -is [array]) {\n")
	script.WriteString("                                                $vmCount = $objects.Count\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $vmCount = 1\n")
	script.WriteString("                                                $objects = @($objects)\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Collect detailed VM/Object information\n")
	script.WriteString("                                            foreach ($obj in $objects) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $vmName = 'N/A'\n")
	script.WriteString("                                                    $vmResourceType = 'Virtual Machine'\n")
	script.WriteString("                                                    $vmRole = 'Include'\n")
	script.WriteString("                                                    $vmApproxSize = 'N/A'\n")
	script.WriteString("                                                    $vmDiskFilterMode = 'AllDisks'\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get name - try multiple properties and methods\n")
	script.WriteString("                                                    if ($obj.Name) { $vmName = $obj.Name }\n")
	script.WriteString("                                                    elseif ($obj.DisplayName) { $vmName = $obj.DisplayName }\n")
	script.WriteString("                                                    elseif ($obj.HostName) { $vmName = $obj.HostName }\n")
	script.WriteString("                                                    elseif ($obj.VmName) { $vmName = $obj.VmName }\n")
	script.WriteString("                                                    elseif ($obj.ObjectName) { $vmName = $obj.ObjectName }\n")
	script.WriteString("                                                    elseif ($obj.ToString()) {\n")
	script.WriteString("                                                        $objStr = $obj.ToString()\n")
	script.WriteString("                                                        if ($objStr -and $objStr -ne $obj.GetType().FullName) {\n")
	script.WriteString("                                                            $vmName = $objStr\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # If still no name, try to get from job name or other sources\n")
	script.WriteString("                                                    if ($vmName -eq 'N/A' -or $vmName -eq '') {\n")
	script.WriteString("                                                        # Try to get from job if it's a single object job\n")
	script.WriteString("                                                        if ($vmCount -eq 1) {\n")
	script.WriteString("                                                            $vmName = $job.Name\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get resource type\n")
	script.WriteString("                                                    if ($obj.Type) { $vmResourceType = $obj.Type.ToString() }\n")
	script.WriteString("                                                    elseif ($obj.ObjectType) { $vmResourceType = $obj.ObjectType.ToString() }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get role (Include/Exclude)\n")
	script.WriteString("                                                    if ($obj.IsExcluded) { $vmRole = 'Exclude' }\n")
	script.WriteString("                                                    elseif ($obj.Excluded) { $vmRole = 'Exclude' }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get approximate size\n")
	script.WriteString("                                                    if ($obj.Size) {\n")
	script.WriteString("                                                        $sizeBytes = $obj.Size\n")
	script.WriteString("                                                        if ($sizeBytes -gt 1TB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1TB, 2)) TB\" }\n")
	script.WriteString("                                                        elseif ($sizeBytes -gt 1GB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1GB, 2)) GB\" }\n")
	script.WriteString("                                                        elseif ($sizeBytes -gt 1MB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1MB, 2)) MB\" }\n")
	script.WriteString("                                                        else { $vmApproxSize = \"$([math]::Round($sizeBytes / 1KB, 2)) KB\" }\n")
	script.WriteString("                                                    } elseif ($obj.ApproxSize) {\n")
	script.WriteString("                                                        $sizeBytes = $obj.ApproxSize\n")
	script.WriteString("                                                        if ($sizeBytes -gt 1TB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1TB, 2)) TB\" }\n")
	script.WriteString("                                                        elseif ($sizeBytes -gt 1GB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1GB, 2)) GB\" }\n")
	script.WriteString("                                                        elseif ($sizeBytes -gt 1MB) { $vmApproxSize = \"$([math]::Round($sizeBytes / 1MB, 2)) MB\" }\n")
	script.WriteString("                                                        else { $vmApproxSize = \"$([math]::Round($sizeBytes / 1KB, 2)) KB\" }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get disk filter mode\n")
	script.WriteString("                                                    if ($obj.DiskFilterMode) { $vmDiskFilterMode = $obj.DiskFilterMode.ToString() }\n")
	script.WriteString("                                                    elseif ($obj.DiskFilter) { $vmDiskFilterMode = $obj.DiskFilter.ToString() }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    # Get Guest Processing information for this object\n")
	script.WriteString("                                                    $guestProcessingEnabled = $false\n")
	script.WriteString("                                                    $guestProcessingIgnoreErrors = $false\n")
	script.WriteString("                                                    $guestProxyAutoDetect = $false\n")
	script.WriteString("                                                    $defaultCredential = 'N/A'\n")
	script.WriteString("                                                    $objectCredential = 'N/A'\n")
	script.WriteString("                                                    $applicationProcessing = $false\n")
	script.WriteString("                                                    $transactionLogs = 'N/A'\n")
	script.WriteString("                                                    $usePersistentGuestAgent = $false\n")
	script.WriteString("                                                    $sqlTransactionLogsProcessing = 'N/A'\n")
	script.WriteString("                                                    $sqlBackupLogEvery = 'N/A'\n")
	script.WriteString("                                                    $sqlRetainLogBackups = 'N/A'\n")
	script.WriteString("                                                    $oracleAccountType = 'N/A'\n")
	script.WriteString("                                                    $oracleSysdbaCreds = 'N/A'\n")
	script.WriteString("                                                    $oracleBackupLogsEvery = 'N/A'\n")
	script.WriteString("                                                    $oracleArchiveLogs = 'N/A'\n")
	script.WriteString("                                                    $oracleRetainLogBackups = 'N/A'\n")
	script.WriteString("                                                    $fileExclusions = $false\n")
	script.WriteString("                                                    $fileExclusionsMode = 'N/A'\n")
	script.WriteString("                                                    $fileExclusionsPaths = 'N/A'\n")
	script.WriteString("                                                    $scripts = $false\n")
	script.WriteString("                                                    $scriptsMode = 'N/A'\n")
	script.WriteString("                                                    $linuxPreFreezeScript = 'N/A'\n")
	script.WriteString("                                                    $linuxPostThawScript = 'N/A'\n")
	script.WriteString("                                                    $windowsPreFreezeScript = 'N/A'\n")
	script.WriteString("                                                    $windowsPostThawScript = 'N/A'\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        # Get Guest Processing Options from job options\n")
	script.WriteString("                                                        if ($job.Options.GuestProcessingOptions) {\n")
	script.WriteString("                                                            $guestOpts = $job.Options.GuestProcessingOptions\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Check if guest processing is enabled for this object\n")
	script.WriteString("                                                            $guestProcessingEnabled = if ($guestOpts.Enabled) { $guestOpts.Enabled } else { $false }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get object-specific guest processing settings\n")
	script.WriteString("                                                            $objGuestOpts = $null\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                # Try to get object-specific options\n")
	script.WriteString("                                                                if ($guestOpts.GetObjectOptions($obj)) {\n")
	script.WriteString("                                                                    $objGuestOpts = $guestOpts.GetObjectOptions($obj)\n")
	script.WriteString("                                                                } elseif ($guestOpts.ObjectOptions) {\n")
	script.WriteString("                                                                    foreach ($opt in $guestOpts.ObjectOptions) {\n")
	script.WriteString("                                                                        if ($opt.Object -and ($opt.Object.Id -eq $obj.Id -or $opt.Object.Name -eq $vmName)) {\n")
	script.WriteString("                                                                            $objGuestOpts = $opt\n")
	script.WriteString("                                                                            break\n")
	script.WriteString("                                                                        }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Use object-specific options if available, otherwise use global options\n")
	script.WriteString("                                                            $currentOpts = if ($objGuestOpts) { $objGuestOpts } else { $guestOpts }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get basic guest processing settings\n")
	script.WriteString("                                                            $guestProcessingIgnoreErrors = if ($currentOpts.IgnoreErrors) { $currentOpts.IgnoreErrors } else { $false }\n")
	script.WriteString("                                                            $guestProxyAutoDetect = if ($currentOpts.GuestProxyAutoDetect) { $currentOpts.GuestProxyAutoDetect } else { $false }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get credentials\n")
	script.WriteString("                                                            if ($guestOpts.DefaultCredential) {\n")
	script.WriteString("                                                                $defCred = $guestOpts.DefaultCredential\n")
	script.WriteString("                                                                if ($defCred.Name) { $defaultCredential = $defCred.Name }\n")
	script.WriteString("                                                                elseif ($defCred -is [string]) { $defaultCredential = $defCred }\n")
	script.WriteString("                                                                else { $defaultCredential = $defCred.ToString() }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            if ($objGuestOpts -and $objGuestOpts.Credential) {\n")
	script.WriteString("                                                                $objCred = $objGuestOpts.Credential\n")
	script.WriteString("                                                                if ($objCred.Name) { $objectCredential = $objCred.Name }\n")
	script.WriteString("                                                                elseif ($objCred -is [string]) { $objectCredential = $objCred }\n")
	script.WriteString("                                                                else { $objectCredential = $objCred.ToString() }\n")
	script.WriteString("                                                            } else {\n")
	script.WriteString("                                                                $objectCredential = 'Default Credential'\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get Application Processing settings\n")
	script.WriteString("                                                            if ($currentOpts.VssOptions) {\n")
	script.WriteString("                                                                $vssOpts = $currentOpts.VssOptions\n")
	script.WriteString("                                                                $applicationProcessing = if ($vssOpts.Enabled) { $vssOpts.Enabled } else { $false }\n")
	script.WriteString("                                                                \n")
	script.WriteString("                                                                # Get Transaction Logs setting\n")
	script.WriteString("                                                                if ($vssOpts.TransactionLogsProcessing) {\n")
	script.WriteString("                                                                    $txnLogs = $vssOpts.TransactionLogsProcessing.ToString()\n")
	script.WriteString("                                                                    switch ($txnLogs) {\n")
	script.WriteString("                                                                        'Process' { $transactionLogs = 'Process Transaction Logs' }\n")
	script.WriteString("                                                                        'DoNotProcess' { $transactionLogs = 'Do not process transaction logs' }\n")
	script.WriteString("                                                                        default { $transactionLogs = $txnLogs }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $transactionLogs = 'Do not process transaction logs'\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                \n")
	script.WriteString("                                                                $usePersistentGuestAgent = if ($vssOpts.UsePersistentGuestAgent) { $vssOpts.UsePersistentGuestAgent } else { $false }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get SQL Transaction Logs Processing\n")
	script.WriteString("                                                            if ($currentOpts.SqlBackupOptions) {\n")
	script.WriteString("                                                                $sqlOpts = $currentOpts.SqlBackupOptions\n")
	script.WriteString("                                                                if ($sqlOpts.TransactionLogsProcessing) {\n")
	script.WriteString("                                                                    $sqlTxnLogs = $sqlOpts.TransactionLogsProcessing.ToString()\n")
	script.WriteString("                                                                    switch ($sqlTxnLogs) {\n")
	script.WriteString("                                                                        'BackupPeriodically' { $sqlTransactionLogsProcessing = 'Backup logs periodically' }\n")
	script.WriteString("                                                                        'DoNotTruncate' { $sqlTransactionLogsProcessing = 'Do not truncate logs' }\n")
	script.WriteString("                                                                        'Truncate' { $sqlTransactionLogsProcessing = 'Truncate logs' }\n")
	script.WriteString("                                                                        default { $sqlTransactionLogsProcessing = $sqlTxnLogs }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                $sqlBackupLogEvery = if ($sqlOpts.BackupLogEveryMinutes) { \"$($sqlOpts.BackupLogEveryMinutes) min\" } else { 'N/A' }\n")
	script.WriteString("                                                                if ($sqlOpts.RetainLogBackups) {\n")
	script.WriteString("                                                                    $sqlRetain = $sqlOpts.RetainLogBackups.ToString()\n")
	script.WriteString("                                                                    switch ($sqlRetain) {\n")
	script.WriteString("                                                                        'UntilImageBackupDeleted' { $sqlRetainLogBackups = 'Until the corresponding image-level backup is deleted' }\n")
	script.WriteString("                                                                        'KeepOnlyLastDays' { $sqlRetainLogBackups = \"Keep Only Last $($sqlOpts.RetainLogBackupsDays) days of log backups\" }\n")
	script.WriteString("                                                                        default { $sqlRetainLogBackups = $sqlRetain }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $sqlRetainLogBackups = 'N/A'\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get Oracle Transaction Logs Processing\n")
	script.WriteString("                                                            if ($currentOpts.OracleBackupOptions) {\n")
	script.WriteString("                                                                $oraOpts = $currentOpts.OracleBackupOptions\n")
	script.WriteString("                                                                if ($oraOpts.AccountType) {\n")
	script.WriteString("                                                                    $oracleAccountType = $oraOpts.AccountType.ToString()\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                if ($oraOpts.SysdbaCredential) {\n")
	script.WriteString("                                                                    $oraCred = $oraOpts.SysdbaCredential\n")
	script.WriteString("                                                                    if ($oraCred.Name) { $oracleSysdbaCreds = $oraCred.Name }\n")
	script.WriteString("                                                                    elseif ($oraCred -is [string]) { $oracleSysdbaCreds = $oraCred }\n")
	script.WriteString("                                                                    else { $oracleSysdbaCreds = 'Guest OS Credential' }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $oracleSysdbaCreds = 'Guest OS Credential'\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                $oracleBackupLogsEvery = if ($oraOpts.BackupLogsEveryMinutes) { \"$($oraOpts.BackupLogsEveryMinutes) min\" } else { 'N/A' }\n")
	script.WriteString("                                                                if ($oraOpts.ArchiveLogs) {\n")
	script.WriteString("                                                                    $oraArchive = $oraOpts.ArchiveLogs.ToString()\n")
	script.WriteString("                                                                    switch ($oraArchive) {\n")
	script.WriteString("                                                                        'DeleteOlderThanHours' { $oracleArchiveLogs = \"Delete Log Older Than $($oraOpts.ArchiveLogsOlderThanHours) hours\" }\n")
	script.WriteString("                                                                        'DeleteOverSizeGB' { $oracleArchiveLogs = \"Delete Log Over $($oraOpts.ArchiveLogsOverSizeGB) GB\" }\n")
	script.WriteString("                                                                        'DoNotDelete' { $oracleArchiveLogs = 'Do not delete logs' }\n")
	script.WriteString("                                                                        default { $oracleArchiveLogs = $oraArchive }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $oracleArchiveLogs = 'N/A'\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                                if ($oraOpts.RetainLogBackups) {\n")
	script.WriteString("                                                                    $oraRetain = $oraOpts.RetainLogBackups.ToString()\n")
	script.WriteString("                                                                    switch ($oraRetain) {\n")
	script.WriteString("                                                                        'UntilImageBackupDeleted' { $oracleRetainLogBackups = 'Until the corresponding image-level backup is deleted' }\n")
	script.WriteString("                                                                        'KeepOnlyLastDays' { $oracleRetainLogBackups = \"Keep Only Last $($oraOpts.RetainLogBackupsDays) days of log backups\" }\n")
	script.WriteString("                                                                        default { $oracleRetainLogBackups = $oraRetain }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } else {\n")
	script.WriteString("                                                                    $oracleRetainLogBackups = 'N/A'\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get File Exclusions\n")
	script.WriteString("                                                            if ($currentOpts.FileExclusions) {\n")
	script.WriteString("                                                                $fileExcl = $currentOpts.FileExclusions\n")
	script.WriteString("                                                                $fileExclusions = if ($fileExcl.Enabled) { $fileExcl.Enabled } else { $false }\n")
	script.WriteString("                                                                if ($fileExclusions) {\n")
	script.WriteString("                                                                    if ($fileExcl.ExcludeList) {\n")
	script.WriteString("                                                                        $fileExclusionsMode = 'Exclude the following file and folders'\n")
	script.WriteString("                                                                        $fileExclusionsPaths = ($fileExcl.ExcludeList | ForEach-Object { $_.ToString() }) -join ','\n")
	script.WriteString("                                                                    } elseif ($fileExcl.IncludeList) {\n")
	script.WriteString("                                                                        $fileExclusionsMode = 'Include only the following file and folders'\n")
	script.WriteString("                                                                        $fileExclusionsPaths = ($fileExcl.IncludeList | ForEach-Object { $_.ToString() }) -join ','\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            \n")
	script.WriteString("                                                            # Get Scripts\n")
	script.WriteString("                                                            if ($currentOpts.ScriptOptions) {\n")
	script.WriteString("                                                                $scriptOpts = $currentOpts.ScriptOptions\n")
	script.WriteString("                                                                $scripts = if ($scriptOpts.Enabled) { $scriptOpts.Enabled } else { $false }\n")
	script.WriteString("                                                                if ($scripts) {\n")
	script.WriteString("                                                                    if ($scriptOpts.ScriptMode) {\n")
	script.WriteString("                                                                        $scriptMode = $scriptOpts.ScriptMode.ToString()\n")
	script.WriteString("                                                                        switch ($scriptMode) {\n")
	script.WriteString("                                                                            'RequireSuccess' { $scriptsMode = 'Require successfull script execution' }\n")
	script.WriteString("                                                                            'IgnoreFailures' { $scriptsMode = 'Ignore script execution failures' }\n")
	script.WriteString("                                                                            default { $scriptsMode = $scriptMode }\n")
	script.WriteString("                                                                        }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                    $linuxPreFreezeScript = if ($scriptOpts.LinuxPreFreezeScript) { $scriptOpts.LinuxPreFreezeScript } else { 'N/A' }\n")
	script.WriteString("                                                                    $linuxPostThawScript = if ($scriptOpts.LinuxPostThawScript) { $scriptOpts.LinuxPostThawScript } else { 'N/A' }\n")
	script.WriteString("                                                                    $windowsPreFreezeScript = if ($scriptOpts.WindowsPreFreezeScript) { $scriptOpts.WindowsPreFreezeScript } else { 'N/A' }\n")
	script.WriteString("                                                                    $windowsPostThawScript = if ($scriptOpts.WindowsPostThawScript) { $scriptOpts.WindowsPostThawScript } else { 'N/A' }\n")
	script.WriteString("                                                                }\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    $vmList += @{\n")
	script.WriteString("                                                        'Name' = $vmName\n")
	script.WriteString("                                                        'ResourceType' = $vmResourceType\n")
	script.WriteString("                                                        'Role' = $vmRole\n")
	script.WriteString("                                                        'ApproxSize' = $vmApproxSize\n")
	script.WriteString("                                                        'DiskFilterMode' = $vmDiskFilterMode\n")
	script.WriteString("                                                        'GuestProcessingEnabled' = $guestProcessingEnabled\n")
	script.WriteString("                                                        'GuestProcessingIgnoreErrors' = $guestProcessingIgnoreErrors\n")
	script.WriteString("                                                        'GuestProxyAutoDetect' = $guestProxyAutoDetect\n")
	script.WriteString("                                                        'DefaultCredential' = $defaultCredential\n")
	script.WriteString("                                                        'ObjectCredential' = $objectCredential\n")
	script.WriteString("                                                        'ApplicationProcessing' = $applicationProcessing\n")
	script.WriteString("                                                        'TransactionLogs' = $transactionLogs\n")
	script.WriteString("                                                        'UsePersistentGuestAgent' = $usePersistentGuestAgent\n")
	script.WriteString("                                                        'SqlTransactionLogsProcessing' = $sqlTransactionLogsProcessing\n")
	script.WriteString("                                                        'SqlBackupLogEvery' = $sqlBackupLogEvery\n")
	script.WriteString("                                                        'SqlRetainLogBackups' = $sqlRetainLogBackups\n")
	script.WriteString("                                                        'OracleAccountType' = $oracleAccountType\n")
	script.WriteString("                                                        'OracleSysdbaCreds' = $oracleSysdbaCreds\n")
	script.WriteString("                                                        'OracleBackupLogsEvery' = $oracleBackupLogsEvery\n")
	script.WriteString("                                                        'OracleArchiveLogs' = $oracleArchiveLogs\n")
	script.WriteString("                                                        'OracleRetainLogBackups' = $oracleRetainLogBackups\n")
	script.WriteString("                                                        'FileExclusions' = $fileExclusions\n")
	script.WriteString("                                                        'FileExclusionsMode' = $fileExclusionsMode\n")
	script.WriteString("                                                        'FileExclusionsPaths' = $fileExclusionsPaths\n")
	script.WriteString("                                                        'Scripts' = $scripts\n")
	script.WriteString("                                                        'ScriptsMode' = $scriptsMode\n")
	script.WriteString("                                                        'LinuxPreFreezeScript' = $linuxPreFreezeScript\n")
	script.WriteString("                                                        'LinuxPostThawScript' = $linuxPostThawScript\n")
	script.WriteString("                                                        'WindowsPreFreezeScript' = $windowsPreFreezeScript\n")
	script.WriteString("                                                        'WindowsPostThawScript' = $windowsPostThawScript\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # If no objects were found, create a default entry with job name\n")
	script.WriteString("                                        if ($vmList.Count -eq 0) {\n")
	script.WriteString("                                            $vmList += @{\n")
	script.WriteString("                                                'Name' = $job.Name\n")
	script.WriteString("                                                'ResourceType' = 'Virtual Machine'\n")
	script.WriteString("                                                'Role' = 'Include'\n")
	script.WriteString("                                                'ApproxSize' = 'N/A'\n")
	script.WriteString("                                                'DiskFilterMode' = 'AllDisks'\n")
	script.WriteString("                                                'GuestProcessingEnabled' = $false\n")
	script.WriteString("                                                'GuestProcessingIgnoreErrors' = $false\n")
	script.WriteString("                                                'GuestProxyAutoDetect' = $false\n")
	script.WriteString("                                                'DefaultCredential' = 'N/A'\n")
	script.WriteString("                                                'ObjectCredential' = 'N/A'\n")
	script.WriteString("                                                'ApplicationProcessing' = $false\n")
	script.WriteString("                                                'TransactionLogs' = 'N/A'\n")
	script.WriteString("                                                'UsePersistentGuestAgent' = $false\n")
	script.WriteString("                                                'SqlTransactionLogsProcessing' = 'N/A'\n")
	script.WriteString("                                                'SqlBackupLogEvery' = 'N/A'\n")
	script.WriteString("                                                'SqlRetainLogBackups' = 'N/A'\n")
	script.WriteString("                                                'OracleAccountType' = 'N/A'\n")
	script.WriteString("                                                'OracleSysdbaCreds' = 'N/A'\n")
	script.WriteString("                                                'OracleBackupLogsEvery' = 'N/A'\n")
	script.WriteString("                                                'OracleArchiveLogs' = 'N/A'\n")
	script.WriteString("                                                'OracleRetainLogBackups' = 'N/A'\n")
	script.WriteString("                                                'FileExclusions' = $false\n")
	script.WriteString("                                                'FileExclusionsMode' = 'N/A'\n")
	script.WriteString("                                                'FileExclusionsPaths' = 'N/A'\n")
	script.WriteString("                                                'Scripts' = $false\n")
	script.WriteString("                                                'ScriptsMode' = 'N/A'\n")
	script.WriteString("                                                'LinuxPreFreezeScript' = 'N/A'\n")
	script.WriteString("                                                'LinuxPostThawScript' = 'N/A'\n")
	script.WriteString("                                                'WindowsPreFreezeScript' = 'N/A'\n")
	script.WriteString("                                                'WindowsPostThawScript' = 'N/A'\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $vmCount = 1\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Secondary Targets\n")
	script.WriteString("                                    $secondaryTargets = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($job.SecondaryTargets) {\n")
	script.WriteString("                                            foreach ($target in $job.SecondaryTargets) {\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $targetName = if ($target.Name) { $target.Name } elseif ($target.JobName) { $target.JobName } else { 'N/A' }\n")
	script.WriteString("                                                    $targetType = if ($target.Type) { $target.Type.ToString() } elseif ($target.JobType) { $target.JobType.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                    $targetState = if ($target.State) { $target.State.ToString() } elseif ($target.Status) { $target.Status.ToString() } else { 'N/A' }\n")
	script.WriteString("                                                    $targetDescription = if ($target.Description) { $target.Description } else { 'N/A' }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    $secondaryTargets += @{\n")
	script.WriteString("                                                        'Name' = $targetName\n")
	script.WriteString("                                                        'Type' = $targetType\n")
	script.WriteString("                                                        'State' = $targetState\n")
	script.WriteString("                                                        'Description' = $targetDescription\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Collect additional job information for detailed modal\n")
	script.WriteString("                                    $targetAddress = '--'\n")
	script.WriteString("                                    $targetFile = $job.Name\n")
	script.WriteString("                                    $modifiedBy = 'N/A'\n")
	script.WriteString("                                    $description = 'N/A'\n")
	script.WriteString("                                    $backupProxy = 'N/A'\n")
	script.WriteString("                                    $retentionType = 'Days'\n")
	script.WriteString("                                    $retainDaysToKeep = 'N/A'\n")
	script.WriteString("                                    $keepFirstFullBackup = $false\n")
	script.WriteString("                                    $enableFullBackup = $false\n")
	script.WriteString("                                    $integrityChecks = $false\n")
	script.WriteString("                                    $storageEncryption = $false\n")
	script.WriteString("                                    $backupMode = 'Incremental'\n")
	script.WriteString("                                    $activeFullBackupScheduleKind = 'N/A'\n")
	script.WriteString("                                    $activeFullBackupDays = 'N/A'\n")
	script.WriteString("                                    $transformFullToSynthetic = $false\n")
	script.WriteString("                                    $transformIncrementsToSynthetic = $false\n")
	script.WriteString("                                    $transformToSyntheticDays = 'N/A'\n")
	script.WriteString("                                    $storageLevelCorruptionGuard = $false\n")
	script.WriteString("                                    $slcgScheduleType = 'N/A'\n")
	script.WriteString("                                    $slcgScheduleDay = 'N/A'\n")
	script.WriteString("                                    $slcgBackupMonthlySchedule = 'N/A'\n")
	script.WriteString("                                    $defragmentAndCompactFullBackup = $false\n")
	script.WriteString("                                    $dcfbScheduleType = 'N/A'\n")
	script.WriteString("                                    $dcfbScheduleDay = 'N/A'\n")
	script.WriteString("                                    $dcfbBackupMonthlySchedule = 'N/A'\n")
	script.WriteString("                                    $removeDeletedItemDataAfter = 'N/A'\n")
	script.WriteString("                                    $inlineDataDeduplication = $false\n")
	script.WriteString("                                    $excludeSwapFilesBlock = $false\n")
	script.WriteString("                                    $excludeDeletedFilesBlock = $false\n")
	script.WriteString("                                    $storageOptimization = 'N/A'\n")
	script.WriteString("                                    $enabledBackupFileEncryption = $false\n")
	script.WriteString("                                    $encryptionKey = 'N/A'\n")
	script.WriteString("                                    $sendSnmpNotification = $false\n")
	script.WriteString("                                    $sendEmailNotification = $false\n")
	script.WriteString("                                    $emailNotificationAdditionalAddresses = 'N/A'\n")
	script.WriteString("                                    $emailNotifyTime = 'N/A'\n")
	script.WriteString("                                    $useCustomEmailNotificationOptions = $false\n")
	script.WriteString("                                    $useCustomNotificationSetting = 'N/A'\n")
	script.WriteString("                                    $notifyOnSuccess = $false\n")
	script.WriteString("                                    $notifyOnWarning = $false\n")
	script.WriteString("                                    $notifyOnError = $false\n")
	script.WriteString("                                    $suppressNotificationUntilLastRetry = $false\n")
	script.WriteString("                                    $setResultsToVmNotes = $false\n")
	script.WriteString("                                    $vmAttributeNoteValue = 'N/A'\n")
	script.WriteString("                                    $appendToExistingAttribute = $false\n")
	script.WriteString("                                    $enableVmwareToolsQuiescence = $false\n")
	script.WriteString("                                    $useChangeBlockTracking = $false\n")
	script.WriteString("                                    $enableCbtForAllProtectedVms = $false\n")
	script.WriteString("                                    $resetCbtOnEachActiveFullBackup = $false\n")
	script.WriteString("                                    $runTheFollowingScriptBefore = $false\n")
	script.WriteString("                                    $runScriptBeforeTheJob = 'N/A'\n")
	script.WriteString("                                    $runTheFollowingScriptAfter = $false\n")
	script.WriteString("                                    $runScriptAfterTheJob = 'N/A'\n")
	script.WriteString("                                    $runScriptFrequency = 'N/A'\n")
	script.WriteString("                                    $runScriptEveryBackupSession = 'N/A'\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Get Description and Modified By\n")
	script.WriteString("                                        if ($job.Description) { $description = $job.Description }\n")
	script.WriteString("                                        if ($job.Info -and $job.Info.Description) { $description = $job.Info.Description }\n")
	script.WriteString("                                        if ($job.ModifiedBy) { $modifiedBy = $job.ModifiedBy }\n")
	script.WriteString("                                        if ($job.Info -and $job.Info.ModifiedBy) { $modifiedBy = $job.Info.ModifiedBy }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Target File\n")
	script.WriteString("                                        if ($job.TargetFile) { $targetFile = $job.TargetFile }\n")
	script.WriteString("                                        elseif ($job.Info -and $job.Info.TargetFile) { $targetFile = $job.Info.TargetFile }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Backup Proxy\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($job.GetBackupProxy()) {\n")
	script.WriteString("                                                $proxy = $job.GetBackupProxy()\n")
	script.WriteString("                                                if ($proxy.Name) { $backupProxy = $proxy.Name }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Retention Type and Days\n")
	script.WriteString("                                        if ($job.Options.BackupStorageOptions) {\n")
	script.WriteString("                                            $retentionType = if ($job.Options.BackupStorageOptions.RetentionPolicyType) { $job.Options.BackupStorageOptions.RetentionPolicyType.ToString() } else { 'Days' }\n")
	script.WriteString("                                            $retainDaysToKeep = if ($job.Options.BackupStorageOptions.RetainCycles) { $job.Options.BackupStorageOptions.RetainCycles } else { 'N/A' }\n")
	script.WriteString("                                            $keepFirstFullBackup = if ($job.Options.BackupStorageOptions.KeepFirstFullBackup) { $job.Options.BackupStorageOptions.KeepFirstFullBackup } else { $false }\n")
	script.WriteString("                                            $enableFullBackup = if ($job.Options.BackupStorageOptions.EnableFullBackup) { $job.Options.BackupStorageOptions.EnableFullBackup } else { $activeFullEnabled }\n")
	script.WriteString("                                            $integrityChecks = if ($job.Options.BackupStorageOptions.EnableIntegrityChecks) { $job.Options.BackupStorageOptions.EnableIntegrityChecks } else { $false }\n")
	script.WriteString("                                            $storageEncryption = if ($job.Options.BackupStorageOptions.EncryptionEnabled) { $job.Options.BackupStorageOptions.EncryptionEnabled } else { $encrypted }\n")
	script.WriteString("                                            $backupMode = if ($backupChainType -ne 'N/A') { $backupChainType } else { 'Incremental' }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Get Active Full Backup Schedule\n")
	script.WriteString("                                            if ($job.Options.BackupStorageOptions.FullBackupScheduleOptions) {\n")
	script.WriteString("                                                $fullSchedule = $job.Options.BackupStorageOptions.FullBackupScheduleOptions\n")
	script.WriteString("                                                if ($fullSchedule.ScheduleKind) { $activeFullBackupScheduleKind = $fullSchedule.ScheduleKind.ToString() }\n")
	script.WriteString("                                                if ($fullSchedule.DailyOptions -and $fullSchedule.DailyOptions.Days) {\n")
	script.WriteString("                                                    $days = @()\n")
	script.WriteString("                                                    foreach ($day in $fullSchedule.DailyOptions.Days) {\n")
	script.WriteString("                                                        if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    $activeFullBackupDays = $days -join ', '\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Get Transform options\n")
	script.WriteString("                                            if ($job.Options.BackupTargetOptions) {\n")
	script.WriteString("                                                $transformFullToSynthetic = if ($job.Options.BackupTargetOptions.TransformFullToSyntethic) { $job.Options.BackupTargetOptions.TransformFullToSyntethic } else { $false }\n")
	script.WriteString("                                                $transformIncrementsToSynthetic = if ($job.Options.BackupTargetOptions.TransformIncrementsToSyntethic) { $job.Options.BackupTargetOptions.TransformIncrementsToSyntethic } else { $false }\n")
	script.WriteString("                                                if ($job.Options.BackupTargetOptions.TransformToSyntheticDays) {\n")
	script.WriteString("                                                    $days = @()\n")
	script.WriteString("                                                    foreach ($day in $job.Options.BackupTargetOptions.TransformToSyntheticDays) {\n")
	script.WriteString("                                                        if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    $transformToSyntheticDays = $days -join ', '\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Get Maintenance options\n")
	script.WriteString("                                            if ($job.Options.BackupStorageOptions.MaintenanceOptions) {\n")
	script.WriteString("                                                $maintenance = $job.Options.BackupStorageOptions.MaintenanceOptions\n")
	script.WriteString("                                                $storageLevelCorruptionGuard = if ($maintenance.StorageLevelCorruptionGuardEnabled) { $maintenance.StorageLevelCorruptionGuardEnabled } else { $false }\n")
	script.WriteString("                                                if ($maintenance.StorageLevelCorruptionGuardSchedule) {\n")
	script.WriteString("                                                    $slcgSchedule = $maintenance.StorageLevelCorruptionGuardSchedule\n")
	script.WriteString("                                                    if ($slcgSchedule.ScheduleKind) { $slcgScheduleType = $slcgSchedule.ScheduleKind.ToString() }\n")
	script.WriteString("                                                    if ($slcgSchedule.DailyOptions -and $slcgSchedule.DailyOptions.Days) {\n")
	script.WriteString("                                                        $days = @()\n")
	script.WriteString("                                                        foreach ($day in $slcgSchedule.DailyOptions.Days) { if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() } }\n")
	script.WriteString("                                                        $slcgScheduleDay = $days -join ', '\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    if ($slcgSchedule.MonthlyOptions) {\n")
	script.WriteString("                                                        $monthly = $slcgSchedule.MonthlyOptions\n")
	script.WriteString("                                                        $slcgBackupMonthlySchedule = \"Day Of Week: $(if ($monthly.DayOfWeek) { $monthly.DayOfWeek.ToString() } else { 'N/A' }), Day Number In Month: $(if ($monthly.DayNumberInMonth) { $monthly.DayNumberInMonth.ToString() } else { 'N/A' }), Day of Month: $(if ($monthly.DayOfMonth) { $monthly.DayOfMonth.ToString() } else { 'N/A' }), Months: $(if ($monthly.Months) { ($monthly.Months | ForEach-Object { if ($_ -is [enum]) { $_.ToString() } else { $_.ToString() } }) -join ' ' } else { 'N/A' })\"\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                $defragmentAndCompactFullBackup = if ($maintenance.DefragmentAndCompactFullBackupEnabled) { $maintenance.DefragmentAndCompactFullBackupEnabled } else { $false }\n")
	script.WriteString("                                                if ($maintenance.DefragmentAndCompactFullBackupSchedule) {\n")
	script.WriteString("                                                    $dcfbSchedule = $maintenance.DefragmentAndCompactFullBackupSchedule\n")
	script.WriteString("                                                    if ($dcfbSchedule.ScheduleKind) { $dcfbScheduleType = $dcfbSchedule.ScheduleKind.ToString() }\n")
	script.WriteString("                                                    if ($dcfbSchedule.DailyOptions -and $dcfbSchedule.DailyOptions.Days) {\n")
	script.WriteString("                                                        $days = @()\n")
	script.WriteString("                                                        foreach ($day in $dcfbSchedule.DailyOptions.Days) { if ($day -is [enum]) { $days += $day.ToString() } else { $days += $day.ToString() } }\n")
	script.WriteString("                                                        $dcfbScheduleDay = $days -join ', '\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    if ($dcfbSchedule.MonthlyOptions) {\n")
	script.WriteString("                                                        $monthly = $dcfbSchedule.MonthlyOptions\n")
	script.WriteString("                                                        $dcfbBackupMonthlySchedule = \"Day Of Week: $(if ($monthly.DayOfWeek) { $monthly.DayOfWeek.ToString() } else { 'N/A' }), Day Number In Month: $(if ($monthly.DayNumberInMonth) { $monthly.DayNumberInMonth.ToString() } else { 'N/A' }), Day of Month: $(if ($monthly.DayOfMonth) { $monthly.DayOfMonth.ToString() } else { 'N/A' }), Months: $(if ($monthly.Months) { ($monthly.Months | ForEach-Object { if ($_ -is [enum]) { $_.ToString() } else { $_.ToString() } }) -join ' ' } else { 'N/A' })\"\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                $removeDeletedItemDataAfter = if ($maintenance.RemoveDeletedItemsDataAfterDays) { $maintenance.RemoveDeletedItemsDataAfterDays } else { 'N/A' }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            \n")
	script.WriteString("                                            # Get Storage Advanced options\n")
	script.WriteString("                                            $inlineDataDeduplication = if ($job.Options.BackupStorageOptions.EnableDeduplication) { $job.Options.BackupStorageOptions.EnableDeduplication } else { $false }\n")
	script.WriteString("                                            $excludeSwapFilesBlock = if ($job.Options.BackupStorageOptions.ExcludeSwapFilesBlock) { $job.Options.BackupStorageOptions.ExcludeSwapFilesBlock } else { $false }\n")
	script.WriteString("                                            $excludeDeletedFilesBlock = if ($job.Options.BackupStorageOptions.ExcludeDeletedFilesBlock) { $job.Options.BackupStorageOptions.ExcludeDeletedFilesBlock } else { $false }\n")
	script.WriteString("                                            if ($job.Options.BackupStorageOptions.StorageOptimization) {\n")
	script.WriteString("                                                $storageOpt = $job.Options.BackupStorageOptions.StorageOptimization.ToString()\n")
	script.WriteString("                                                switch ($storageOpt) {\n")
	script.WriteString("                                                    'LocalTarget' { $storageOptimization = 'Local target (1MB)' }\n")
	script.WriteString("                                                    'WanTarget' { $storageOptimization = 'WAN target (256KB)' }\n")
	script.WriteString("                                                    'LanTarget' { $storageOptimization = 'LAN target (1MB)' }\n")
	script.WriteString("                                                    default { $storageOptimization = $storageOpt }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $enabledBackupFileEncryption = if ($job.Options.BackupStorageOptions.EncryptionEnabled) { $job.Options.BackupStorageOptions.EncryptionEnabled } else { $encrypted }\n")
	script.WriteString("                                            if ($job.Options.BackupStorageOptions.EncryptionKey) {\n")
	script.WriteString("                                                $encKey = $job.Options.BackupStorageOptions.EncryptionKey\n")
	script.WriteString("                                                if ($encKey.Name) { $encryptionKey = $encKey.Name }\n")
	script.WriteString("                                                elseif ($encKey -is [string]) { $encryptionKey = $encKey }\n")
	script.WriteString("                                                else { $encryptionKey = $encKey.ToString() }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Notification options\n")
	script.WriteString("                                        if ($job.Options.NotificationOptions) {\n")
	script.WriteString("                                            $notify = $job.Options.NotificationOptions\n")
	script.WriteString("                                            $sendSnmpNotification = if ($notify.SendSnmpNotification) { $notify.SendSnmpNotification } else { $false }\n")
	script.WriteString("                                            $sendEmailNotification = if ($notify.SendEmailNotification) { $notify.SendEmailNotification } else { $false }\n")
	script.WriteString("                                            $emailNotificationAdditionalAddresses = if ($notify.EmailAdditionalAddress) { $notify.EmailAdditionalAddress } else { 'N/A' }\n")
	script.WriteString("                                            $emailNotifyTime = if ($notify.EmailNotifyTime) { $notify.EmailNotifyTime.ToString('hh:mm tt') } else { 'N/A' }\n")
	script.WriteString("                                            $useCustomEmailNotificationOptions = if ($notify.UseCustomEmailNotificationOptions) { $notify.UseCustomEmailNotificationOptions } else { $false }\n")
	script.WriteString("                                            $useCustomNotificationSetting = if ($notify.EmailSubject) { $notify.EmailSubject } else { 'N/A' }\n")
	script.WriteString("                                            $notifyOnSuccess = if ($notify.NotifyOnSuccess) { $notify.NotifyOnSuccess } else { $false }\n")
	script.WriteString("                                            $notifyOnWarning = if ($notify.NotifyOnWarning) { $notify.NotifyOnWarning } else { $false }\n")
	script.WriteString("                                            $notifyOnError = if ($notify.NotifyOnError) { $notify.NotifyOnError } else { $false }\n")
	script.WriteString("                                            $suppressNotificationUntilLastRetry = if ($notify.SuppressNotificationUntilLastRetry) { $notify.SuppressNotificationUntilLastRetry } else { $false }\n")
	script.WriteString("                                            $setResultsToVmNotes = if ($notify.SetResultsToVmNotes) { $notify.SetResultsToVmNotes } else { $false }\n")
	script.WriteString("                                            $vmAttributeNoteValue = if ($notify.VmAttributeNoteValue) { $notify.VmAttributeNoteValue } else { 'N/A' }\n")
	script.WriteString("                                            $appendToExistingAttribute = if ($notify.AppendToExistingAttribute) { $notify.AppendToExistingAttribute } else { $false }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get vSphere options\n")
	script.WriteString("                                        if ($job.Options.ViSourceOptions) {\n")
	script.WriteString("                                            $viOptions = $job.Options.ViSourceOptions\n")
	script.WriteString("                                            $enableVmwareToolsQuiescence = if ($viOptions.VmQuiescence) { $viOptions.VmQuiescence } else { $false }\n")
	script.WriteString("                                            $useChangeBlockTracking = if ($viOptions.UseChangeTracking) { $viOptions.UseChangeTracking } else { $false }\n")
	script.WriteString("                                            $enableCbtForAllProtectedVms = if ($viOptions.EnableCbtForAllProtectedVms) { $viOptions.EnableCbtForAllProtectedVms } else { $false }\n")
	script.WriteString("                                            $resetCbtOnEachActiveFullBackup = if ($viOptions.ResetCbtOnEachActiveFullBackup) { $viOptions.ResetCbtOnEachActiveFullBackup } else { $false }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Script options\n")
	script.WriteString("                                        if ($job.Options.ScriptOptions) {\n")
	script.WriteString("                                            $scriptOpts = $job.Options.ScriptOptions\n")
	script.WriteString("                                            $runTheFollowingScriptBefore = if ($scriptOpts.RunScriptBeforeJob) { $scriptOpts.RunScriptBeforeJob } else { $false }\n")
	script.WriteString("                                            $runScriptBeforeTheJob = if ($scriptOpts.ScriptBeforeJob) { $scriptOpts.ScriptBeforeJob } else { 'N/A' }\n")
	script.WriteString("                                            $runTheFollowingScriptAfter = if ($scriptOpts.RunScriptAfterJob) { $scriptOpts.RunScriptAfterJob } else { $false }\n")
	script.WriteString("                                            $runScriptAfterTheJob = if ($scriptOpts.ScriptAfterJob) { $scriptOpts.ScriptAfterJob } else { 'N/A' }\n")
	script.WriteString("                                            $runScriptFrequency = if ($scriptOpts.ScriptFrequency) { $scriptOpts.ScriptFrequency.ToString() } else { 'N/A' }\n")
	script.WriteString("                                            $runScriptEveryBackupSession = if ($scriptOpts.ScriptEveryBackupSession) { $scriptOpts.ScriptEveryBackupSession } else { 'N/A' }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $jobConfig = @{\n")
	script.WriteString("                                        'Name' = $job.Name\n")
	script.WriteString("                                        'Repository' = $repositoryName\n")
	script.WriteString("                                        'SourceSize' = $sourceSize\n")
	script.WriteString("                                        'RetentionScheme' = $retentionScheme\n")
	script.WriteString("                                        'RestorePoints' = $restorePoints\n")
	script.WriteString("                                        'Encrypted' = $encrypted\n")
	script.WriteString("                                        'JobType' = $job.JobType.ToString()\n")
	script.WriteString("                                        'CompressionLevel' = $compressionLevel\n")
	script.WriteString("                                        'BlockSize' = $blockSize\n")
	script.WriteString("                                        'GfsEnabled' = $gfsEnabled\n")
	script.WriteString("                                        'GfsRetention' = $gfsRetention\n")
	script.WriteString("                                        'ActiveFullEnabled' = $activeFullEnabled\n")
	script.WriteString("                                        'SyntheticFullEnabled' = $syntheticFullEnabled\n")
	script.WriteString("                                        'BackupChainType' = $backupChainType\n")
	script.WriteString("                                        'IndexingEnabled' = $indexingEnabled\n")
	script.WriteString("                                        'IsEnabled' = $isEnabled\n")
	script.WriteString("                                        'IsScheduleEnabled' = $isEnabled\n")
	script.WriteString("                                        'LastRun' = $lastRun\n")
	script.WriteString("                                        'LastResult' = $lastResult\n")
	script.WriteString("                                        'NextRun' = $nextRun\n")
	script.WriteString("                                        'CreationTime' = $creationTime\n")
	script.WriteString("                                        'CreationTimeUTC' = $creationTime\n")
	script.WriteString("                                        'VMCount' = $vmCount\n")
	script.WriteString("                                        'Objects' = $vmList\n")
	script.WriteString("                                        'VMs' = $vmList\n")
	script.WriteString("                                        'VMList' = $vmList\n")
	script.WriteString("                                        'SecondaryTargets' = $secondaryTargets\n")
	script.WriteString("                                        'SecondaryTarget' = $secondaryTargets\n")
	script.WriteString("                                        'TargetAddress' = $targetAddress\n")
	script.WriteString("                                        'TargetFile' = $targetFile\n")
	script.WriteString("                                        'ModifiedBy' = $modifiedBy\n")
	script.WriteString("                                        'Description' = $description\n")
	script.WriteString("                                        'BackupProxy' = $backupProxy\n")
	script.WriteString("                                        'RetentionType' = $retentionType\n")
	script.WriteString("                                        'RetainDaysToKeep' = $retainDaysToKeep\n")
	script.WriteString("                                        'KeepFirstFullBackup' = $keepFirstFullBackup\n")
	script.WriteString("                                        'EnableFullBackup' = $enableFullBackup\n")
	script.WriteString("                                        'IntegrityChecks' = $integrityChecks\n")
	script.WriteString("                                        'StorageEncryption' = $storageEncryption\n")
	script.WriteString("                                        'BackupMode' = $backupMode\n")
	script.WriteString("                                        'ActiveFullBackupScheduleKind' = $activeFullBackupScheduleKind\n")
	script.WriteString("                                        'ActiveFullBackupDays' = $activeFullBackupDays\n")
	script.WriteString("                                        'TransformFullToSynthetic' = $transformFullToSynthetic\n")
	script.WriteString("                                        'TransformIncrementsToSynthetic' = $transformIncrementsToSynthetic\n")
	script.WriteString("                                        'TransformToSyntheticDays' = $transformToSyntheticDays\n")
	script.WriteString("                                        'StorageLevelCorruptionGuard' = $storageLevelCorruptionGuard\n")
	script.WriteString("                                        'SlcgScheduleType' = $slcgScheduleType\n")
	script.WriteString("                                        'SlcgScheduleDay' = $slcgScheduleDay\n")
	script.WriteString("                                        'SlcgBackupMonthlySchedule' = $slcgBackupMonthlySchedule\n")
	script.WriteString("                                        'DefragmentAndCompactFullBackup' = $defragmentAndCompactFullBackup\n")
	script.WriteString("                                        'DcfbScheduleType' = $dcfbScheduleType\n")
	script.WriteString("                                        'DcfbScheduleDay' = $dcfbScheduleDay\n")
	script.WriteString("                                        'DcfbBackupMonthlySchedule' = $dcfbBackupMonthlySchedule\n")
	script.WriteString("                                        'RemoveDeletedItemDataAfter' = $removeDeletedItemDataAfter\n")
	script.WriteString("                                        'InlineDataDeduplication' = $inlineDataDeduplication\n")
	script.WriteString("                                        'ExcludeSwapFilesBlock' = $excludeSwapFilesBlock\n")
	script.WriteString("                                        'ExcludeDeletedFilesBlock' = $excludeDeletedFilesBlock\n")
	script.WriteString("                                        'StorageOptimization' = $storageOptimization\n")
	script.WriteString("                                        'EnabledBackupFileEncryption' = $enabledBackupFileEncryption\n")
	script.WriteString("                                        'EncryptionKey' = $encryptionKey\n")
	script.WriteString("                                        'SendSnmpNotification' = $sendSnmpNotification\n")
	script.WriteString("                                        'SendEmailNotification' = $sendEmailNotification\n")
	script.WriteString("                                        'EmailNotificationAdditionalAddresses' = $emailNotificationAdditionalAddresses\n")
	script.WriteString("                                        'EmailNotifyTime' = $emailNotifyTime\n")
	script.WriteString("                                        'UseCustomEmailNotificationOptions' = $useCustomEmailNotificationOptions\n")
	script.WriteString("                                        'UseCustomNotificationSetting' = $useCustomNotificationSetting\n")
	script.WriteString("                                        'NotifyOnSuccess' = $notifyOnSuccess\n")
	script.WriteString("                                        'NotifyOnWarning' = $notifyOnWarning\n")
	script.WriteString("                                        'NotifyOnError' = $notifyOnError\n")
	script.WriteString("                                        'SuppressNotificationUntilLastRetry' = $suppressNotificationUntilLastRetry\n")
	script.WriteString("                                        'SetResultsToVmNotes' = $setResultsToVmNotes\n")
	script.WriteString("                                        'VmAttributeNoteValue' = $vmAttributeNoteValue\n")
	script.WriteString("                                        'AppendToExistingAttribute' = $appendToExistingAttribute\n")
	script.WriteString("                                        'EnableVmwareToolsQuiescence' = $enableVmwareToolsQuiescence\n")
	script.WriteString("                                        'UseChangeBlockTracking' = $useChangeBlockTracking\n")
	script.WriteString("                                        'EnableCbtForAllProtectedVms' = $enableCbtForAllProtectedVms\n")
	script.WriteString("                                        'ResetCbtOnEachActiveFullBackup' = $resetCbtOnEachActiveFullBackup\n")
	script.WriteString("                                        'RunTheFollowingScriptBefore' = $runTheFollowingScriptBefore\n")
	script.WriteString("                                        'RunScriptBeforeTheJob' = $runScriptBeforeTheJob\n")
	script.WriteString("                                        'RunTheFollowingScriptAfter' = $runTheFollowingScriptAfter\n")
	script.WriteString("                                        'RunScriptAfterTheJob' = $runScriptAfterTheJob\n")
	script.WriteString("                                        'RunScriptFrequency' = $runScriptFrequency\n")
	script.WriteString("                                        'RunScriptEveryBackupSession' = $runScriptEveryBackupSession\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Categorize by job type\n")
	script.WriteString("                                    $jobTypeStr = $job.JobType.ToString()\n")
	script.WriteString("                                    # Normalize job type name for display\n")
	script.WriteString("                                    # File Backup jobs can be NasBackup, ENasBackup, or FileBackup\n")
	script.WriteString("                                    if ($jobTypeStr -eq 'NasBackup' -or $jobTypeStr -eq 'ENasBackup' -or $jobTypeStr -eq 'FileBackup') {\n")
	script.WriteString("                                        $jobConfig['JobType'] = 'File Backup'\n")
	script.WriteString("                                        $fileBackupJobList += $jobConfig\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'Backup') {\n")
	script.WriteString("                                        # Use TypeToString property first (it shows \"Hyper-V Backup\" or \"VMware Backup\" directly)\n")
	script.WriteString("                                        $platformType = 'VMware Backup'\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            # Primary method: Use TypeToString property\n")
	script.WriteString("                                            if ($job.TypeToString) {\n")
	script.WriteString("                                                $typeStr = $job.TypeToString.ToString()\n")
	script.WriteString("                                                if ($typeStr -like '*Hyper-V*' -or $typeStr -like '*HyperV*') {\n")
	script.WriteString("                                                    $platformType = 'Hyper-V Backup'\n")
	script.WriteString("                                                } elseif ($typeStr -like '*VMware*' -or $typeStr -like '*ESX*') {\n")
	script.WriteString("                                                    $platformType = 'VMware Backup'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            # Fallback 1: Check SourceType property\n")
	script.WriteString("                                            if ($platformType -eq 'VMware Backup' -and $job.SourceType) {\n")
	script.WriteString("                                                $sourceTypeStr = $job.SourceType.ToString()\n")
	script.WriteString("                                                if ($sourceTypeStr -eq 'HyperV' -or $sourceTypeStr -eq 'Hyper-V') {\n")
	script.WriteString("                                                    $platformType = 'Hyper-V Backup'\n")
	script.WriteString("                                                } elseif ($sourceTypeStr -eq 'VMware' -or $sourceTypeStr -eq 'ESX') {\n")
	script.WriteString("                                                    $platformType = 'VMware Backup'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            # Fallback 2: Check BackupPlatform property\n")
	script.WriteString("                                            if ($platformType -eq 'VMware Backup' -and $job.BackupPlatform) {\n")
	script.WriteString("                                                $platformStr = $job.BackupPlatform.ToString()\n")
	script.WriteString("                                                if ($platformStr -eq 'EHyperV' -or $platformStr -like '*HyperV*') {\n")
	script.WriteString("                                                    $platformType = 'Hyper-V Backup'\n")
	script.WriteString("                                                } elseif ($platformStr -like '*VMware*' -or $platformStr -like '*ESX*') {\n")
	script.WriteString("                                                    $platformType = 'VMware Backup'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            # Fallback 3: Check Platform property (old method)\n")
	script.WriteString("                                            if ($platformType -eq 'VMware Backup' -and $job.Platform) {\n")
	script.WriteString("                                                $platformStr = $job.Platform.ToString()\n")
	script.WriteString("                                                if ($platformStr -eq 'HyperV' -or $platformStr -eq 'Hyper-V') {\n")
	script.WriteString("                                                    $platformType = 'Hyper-V Backup'\n")
	script.WriteString("                                                } elseif ($platformStr -eq 'VMware' -or $platformStr -eq 'ESX') {\n")
	script.WriteString("                                                    $platformType = 'VMware Backup'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        $jobConfig['JobType'] = $platformType\n")
	script.WriteString("                                        $backupJobList += $jobConfig\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'Replica') {\n")
	script.WriteString("                                        $jobConfig['JobType'] = 'Replica'\n")
	script.WriteString("                                        $replicaJobList += $jobConfig\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'FileCopy' -or $jobTypeStr -eq 'Copy') {\n")
	script.WriteString("                                        $jobConfig['JobType'] = 'File Copy'\n")
	script.WriteString("                                        $fileCopyJobList += $jobConfig\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'BackupCopy' -or $jobTypeStr -eq 'SimpleBackupCopyPolicy' -or $jobTypeStr -eq 'BackupSync' -or $jobTypeStr -eq 'SimpleBackupCopyWorker') {\n")
	script.WriteString("                                        $jobConfig['JobType'] = 'Backup Copy'\n")
	script.WriteString("                                        $backupCopyJobList += $jobConfig\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        # Unknown job type - add to backup jobs as fallback\n")
	script.WriteString("                                        $backupJobList += $jobConfig\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    # Fallback to basic info if detailed collection fails\n")
	script.WriteString("                                    $basicJob = @{\n")
	script.WriteString("                                        'Name' = $job.Name\n")
	script.WriteString("                                        'JobType' = $job.JobType.ToString()\n")
	script.WriteString("                                        'Error' = 'Failed to collect detailed information'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    $jobTypeStr = $job.JobType.ToString()\n")
	script.WriteString("                                    # Normalize job type name for display\n")
	script.WriteString("                                    # File Backup jobs can be NasBackup, ENasBackup, or FileBackup\n")
	script.WriteString("                                    if ($jobTypeStr -eq 'NasBackup' -or $jobTypeStr -eq 'ENasBackup' -or $jobTypeStr -eq 'FileBackup') {\n")
	script.WriteString("                                        $basicJob['JobType'] = 'File Backup'\n")
	script.WriteString("                                        $fileBackupJobList += $basicJob\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'Backup') {\n")
	script.WriteString("                                        $backupJobList += $basicJob\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'Replica') {\n")
	script.WriteString("                                        $replicaJobList += $basicJob\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'FileCopy' -or $jobTypeStr -eq 'Copy') {\n")
	script.WriteString("                                        $basicJob['JobType'] = 'File Copy'\n")
	script.WriteString("                                        $fileCopyJobList += $basicJob\n")
	script.WriteString("                                    } elseif ($jobTypeStr -eq 'BackupCopy' -or $jobTypeStr -eq 'SimpleBackupCopyPolicy' -or $jobTypeStr -eq 'BackupSync' -or $jobTypeStr -eq 'SimpleBackupCopyWorker') {\n")
	script.WriteString("                                        $basicJob['JobType'] = 'Backup Copy'\n")
	script.WriteString("                                        $backupCopyJobList += $basicJob\n")
	script.WriteString("                                    } else {\n")
	script.WriteString("                                        # Unknown job type - add to backup jobs as fallback\n")
	script.WriteString("                                        $backupJobList += $basicJob\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $veeamInfo['jobInfo'] = @{\n")
	script.WriteString("                                'backupJobs' = $backupJobList\n")
	script.WriteString("                                'replicaJobs' = $replicaJobList\n")
	script.WriteString("                                'fileCopyJobs' = $fileCopyJobList\n")
	script.WriteString("                                'backupCopyJobs' = $backupCopyJobList\n")
	script.WriteString("                                'fileBackupJobs' = $fileBackupJobList\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Tape Jobs with detailed information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Tape Jobs\" -Status \"Enumerating tape backup jobs and media pools\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $tapeJobs = Get-VBRTapeJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $tapeJobList = @()\n")
	script.WriteString("                            foreach ($tapeJob in $tapeJobs) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    # Initialize tape job variables\n")
	script.WriteString("                                    $mediaPoolFull = 'N/A'\n")
	script.WriteString("                                    $incrementalEnabled = $false\n")
	script.WriteString("                                    $mediaPoolIncremental = 'N/A'\n")
	script.WriteString("                                    $hardwareCompression = $false\n")
	script.WriteString("                                    $ejectMedium = $false\n")
	script.WriteString("                                    $exportMediaSet = $false\n")
	script.WriteString("                                    $jobIsEnabled = $false\n")
	script.WriteString("                                    $nextRun = 'N/A'\n")
	script.WriteString("                                    $lastTapeSessionResult = 'N/A'\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Media Pool - Full\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.MediaPool) {\n")
	script.WriteString("                                            $mediaPoolFull = $tapeJob.MediaPool.Name\n")
	script.WriteString("                                        } elseif ($tapeJob.FullMediaPool) {\n")
	script.WriteString("                                            $mediaPoolFull = $tapeJob.FullMediaPool.Name\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Incremental Enabled and Media Pool - Incremental\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.IncrementalMediaPool) {\n")
	script.WriteString("                                            $incrementalEnabled = $true\n")
	script.WriteString("                                            $mediaPoolIncremental = $tapeJob.IncrementalMediaPool.Name\n")
	script.WriteString("                                        } elseif ($tapeJob.Options -and $tapeJob.Options.IncrementalEnabled) {\n")
	script.WriteString("                                            $incrementalEnabled = $tapeJob.Options.IncrementalEnabled\n")
	script.WriteString("                                            if ($tapeJob.Options.IncrementalMediaPool) {\n")
	script.WriteString("                                                $mediaPoolIncremental = $tapeJob.Options.IncrementalMediaPool.Name\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Hardware Compression, Eject Medium, Export Media Set\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.Options) {\n")
	script.WriteString("                                            if ($tapeJob.Options.HardwareCompression -ne $null) {\n")
	script.WriteString("                                                $hardwareCompression = $tapeJob.Options.HardwareCompression\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($tapeJob.Options.EjectMedium -ne $null) {\n")
	script.WriteString("                                                $ejectMedium = $tapeJob.Options.EjectMedium\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($tapeJob.Options.ExportMediaSet -ne $null) {\n")
	script.WriteString("                                                $exportMediaSet = $tapeJob.Options.ExportMediaSet\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Job Is Enabled\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.IsScheduleEnabled -ne $null) {\n")
	script.WriteString("                                            $jobIsEnabled = $tapeJob.IsScheduleEnabled\n")
	script.WriteString("                                        } elseif ($tapeJob.ScheduleOptions -and $tapeJob.ScheduleOptions.Enabled -ne $null) {\n")
	script.WriteString("                                            $jobIsEnabled = $tapeJob.ScheduleOptions.Enabled\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Next Run\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.ScheduleOptions -and $tapeJob.ScheduleOptions.NextRun) {\n")
	script.WriteString("                                            $nextRun = $tapeJob.ScheduleOptions.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($tapeJob.NextRun) {\n")
	script.WriteString("                                            $nextRun = $tapeJob.NextRun.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get last session status for tape job\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        # Method 1: Try CTapeSession\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $tapeSessions = [Veeam.Backup.Core.CTapeSession]::GetByJob($tapeJob.Id) | Sort-Object -Property CreationTimeUTC -Descending | Select-Object -First 1\n")
	script.WriteString("                                            if ($tapeSessions) {\n")
	script.WriteString("                                                if ($tapeSessions -is [array] -and $tapeSessions.Count -gt 0) {\n")
	script.WriteString("                                                    $lastTapeSession = $tapeSessions[0]\n")
	script.WriteString("                                                } elseif ($tapeSessions -isnot [array]) {\n")
	script.WriteString("                                                    $lastTapeSession = $tapeSessions\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                if ($lastTapeSession -and $lastTapeSession.Result) {\n")
	script.WriteString("                                                    $resultValue = $lastTapeSession.Result\n")
	script.WriteString("                                                    if ($resultValue -is [enum]) {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Method 2: Try Get-VBRTapeSession\n")
	script.WriteString("                                        if (-not $lastTapeSessionResult -or $lastTapeSessionResult -eq 'N/A') {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                $sessions = Get-VBRTapeSession -Job $tapeJob -ErrorAction SilentlyContinue | Sort-Object -Property CreationTimeUTC -Descending | Select-Object -First 1\n")
	script.WriteString("                                                if ($sessions -and $sessions.Result) {\n")
	script.WriteString("                                                    $resultValue = $sessions.Result\n")
	script.WriteString("                                                    if ($resultValue -is [enum]) {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Method 3: Try LastResult property directly on tape job\n")
	script.WriteString("                                        if (-not $lastTapeSessionResult -or $lastTapeSessionResult -eq 'N/A') {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                if ($tapeJob.LastResult) {\n")
	script.WriteString("                                                    $resultValue = $tapeJob.LastResult\n")
	script.WriteString("                                                    if ($resultValue -is [enum]) {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $lastTapeSessionResult = $resultValue.ToString()\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get Creation Time for tape job\n")
	script.WriteString("                                    $creationTime = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.CreationTimeUTC) {\n")
	script.WriteString("                                            $creationTime = $tapeJob.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($tapeJob.CreationTime) {\n")
	script.WriteString("                                            $creationTime = $tapeJob.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        } elseif ($tapeJob.Info -and $tapeJob.Info.CreationTimeUTC) {\n")
	script.WriteString("                                            $creationTime = $tapeJob.Info.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get VM/Object Count for tape job\n")
	script.WriteString("                                    $vmCount = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($tapeJob.GetObjects()) {\n")
	script.WriteString("                                            $objects = $tapeJob.GetObjects()\n")
	script.WriteString("                                            if ($objects -is [array]) {\n")
	script.WriteString("                                                $vmCount = $objects.Count\n")
	script.WriteString("                                            } elseif ($objects) {\n")
	script.WriteString("                                                $vmCount = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } elseif ($tapeJob.Objects) {\n")
	script.WriteString("                                            if ($tapeJob.Objects -is [array]) {\n")
	script.WriteString("                                                $vmCount = $tapeJob.Objects.Count\n")
	script.WriteString("                                            } elseif ($tapeJob.Objects) {\n")
	script.WriteString("                                                $vmCount = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } elseif ($tapeJob.GetContainer()) {\n")
	script.WriteString("                                            $container = $tapeJob.GetContainer()\n")
	script.WriteString("                                            if ($container -and $container.GetObjects()) {\n")
	script.WriteString("                                                $objects = $container.GetObjects()\n")
	script.WriteString("                                                if ($objects -is [array]) {\n")
	script.WriteString("                                                    $vmCount = $objects.Count\n")
	script.WriteString("                                                } elseif ($objects) {\n")
	script.WriteString("                                                    $vmCount = 1\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $tapeJobConfig = @{\n")
	script.WriteString("                                        'Name' = $tapeJob.Name\n")
	script.WriteString("                                        'JobType' = 'Tape'\n")
	script.WriteString("                                        'MediaPoolFull' = $mediaPoolFull\n")
	script.WriteString("                                        'IncrementalEnabled' = $incrementalEnabled\n")
	script.WriteString("                                        'MediaPoolIncremental' = $mediaPoolIncremental\n")
	script.WriteString("                                        'HardwareCompression' = $hardwareCompression\n")
	script.WriteString("                                        'EjectMedium' = $ejectMedium\n")
	script.WriteString("                                        'ExportMediaSet' = $exportMediaSet\n")
	script.WriteString("                                        'IsEnabled' = $jobIsEnabled\n")
	script.WriteString("                                        'IsScheduleEnabled' = $jobIsEnabled\n")
	script.WriteString("                                        'NextRun' = $nextRun\n")
	script.WriteString("                                        'LastResult' = $lastTapeSessionResult\n")
	script.WriteString("                                        'CreationTime' = $creationTime\n")
	script.WriteString("                                        'VMCount' = $vmCount\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    $tapeJobList += $tapeJobConfig\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    $tapeJobList += @{\n")
	script.WriteString("                                        'Name' = $tapeJob.Name\n")
	script.WriteString("                                        'Error' = 'Failed to collect detailed information'\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            if (-not $veeamInfo['jobInfo']) {\n")
	script.WriteString("                                $veeamInfo['jobInfo'] = @{}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            $veeamInfo['jobInfo']['tapeJobs'] = $tapeJobList\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Job Session Summary (14 Days)\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Job Session Summary\" -Status \"Analyzing job sessions from last 14 days\"\n")
	script.WriteString("                        $jobSessionSummary = @()\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allJobsForSessions = @()\n")
	script.WriteString("                            if ($backupJobList) { $allJobsForSessions += $backupJobList }\n")
	script.WriteString("                            if ($replicaJobList) { $allJobsForSessions += $replicaJobList }\n")
	script.WriteString("                            if ($fileCopyJobList) { $allJobsForSessions += $fileCopyJobList }\n")
	script.WriteString("                            if ($backupCopyJobList) { $allJobsForSessions += $backupCopyJobList }\n")
	script.WriteString("                            if ($fileBackupJobList) { $allJobsForSessions += $fileBackupJobList }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $fourteenDaysAgo = (Get-Date).AddDays(-14)\n")
	script.WriteString("                            \n")
	script.WriteString("                            foreach ($jobInfo in $allJobsForSessions) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $jobName = $jobInfo.Name\n")
	script.WriteString("                                    if (-not $jobName) { continue }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get job object\n")
	script.WriteString("                                    $job = Get-VBRJob -Name $jobName -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if (-not $job) { continue }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get all sessions from last 14 days\n")
	script.WriteString("                                    $sessions = @()\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $sessions = [Veeam.Backup.Core.CBackupSession]::GetByJob($job.Id) | Where-Object { \n")
	script.WriteString("                                            $_.CreationTimeUTC -ge $fourteenDaysAgo \n")
	script.WriteString("                                        } | Sort-Object -Property CreationTimeUTC -Descending\n")
	script.WriteString("                                    } catch {\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            $sessions = Get-VBRBackupSession -Job $job | Where-Object { \n")
	script.WriteString("                                                $_.CreationTime -ge $fourteenDaysAgo \n")
	script.WriteString("                                            } | Sort-Object -Property CreationTime -Descending\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($sessions.Count -eq 0) { continue }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Store individual sessions for modal display\n")
	script.WriteString("                                    $sessionDetails = @()\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Calculate statistics\n")
	script.WriteString("                                    $totalSessions = $sessions.Count\n")
	script.WriteString("                                    $fails = 0\n")
	script.WriteString("                                    $retries = 0\n")
	script.WriteString("                                    $durations = @()\n")
	script.WriteString("                                    $backupSizes = @()\n")
	script.WriteString("                                    $dataSizes = @()\n")
	script.WriteString("                                    $changeRates = @()\n")
	script.WriteString("                                    $waitCounts = 0\n")
	script.WriteString("                                    $itemCount = 0\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    foreach ($session in $sessions) {\n")
	script.WriteString("                                        # Collect session details\n")
	script.WriteString("                                        $sessionResult = 'None'\n")
	script.WriteString("                                        $sessionResultStr = 'None'\n")
	script.WriteString("                                        $isRetry = $false\n")
	script.WriteString("                                        $sessionDuration = $null\n")
	script.WriteString("                                        $sessionBackupSize = 0\n")
	script.WriteString("                                        $sessionDataSize = 0\n")
	script.WriteString("                                        $sessionChangeRate = 0\n")
	script.WriteString("                                        $sessionCreationTime = 'N/A'\n")
	script.WriteString("                                        $sessionEndTime = 'N/A'\n")
	script.WriteString("                                        $sessionState = 'N/A'\n")
	script.WriteString("                                        $sessionProgress = 'N/A'\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check result\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.Result) {\n")
	script.WriteString("                                                $resultValue = $session.Result\n")
	script.WriteString("                                                if ($resultValue -is [enum]) {\n")
	script.WriteString("                                                    $resultStr = $resultValue.ToString().ToLower()\n")
	script.WriteString("                                                } else {\n")
	script.WriteString("                                                    $resultStr = $resultValue.ToString().ToLower()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                $sessionResult = $resultValue\n")
	script.WriteString("                                                $sessionResultStr = $resultStr\n")
	script.WriteString("                                                if ($resultStr -eq 'failed' -or $resultStr -eq 'error' -or $resultStr -eq 'failure' -or $resultStr -eq '2') {\n")
	script.WriteString("                                                    $fails++\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check retry\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.Info -and $session.Info.IsRetryMode) {\n")
	script.WriteString("                                                $isRetry = $true\n")
	script.WriteString("                                                $retries++\n")
	script.WriteString("                                            } elseif ($session.IsRetry) {\n")
	script.WriteString("                                                $isRetry = $true\n")
	script.WriteString("                                                $retries++\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get creation and end times\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.CreationTimeUTC) {\n")
	script.WriteString("                                                $sessionCreationTime = $session.CreationTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            } elseif ($session.CreationTime) {\n")
	script.WriteString("                                                $sessionCreationTime = $session.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($session.EndTimeUTC) {\n")
	script.WriteString("                                                $sessionEndTime = $session.EndTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            } elseif ($session.EndTime) {\n")
	script.WriteString("                                                $sessionEndTime = $session.EndTime.ToString('yyyy-MM-dd HH:mm:ss')\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get state and progress\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.State) {\n")
	script.WriteString("                                                $sessionState = $session.State.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($session.Progress) {\n")
	script.WriteString("                                                $sessionProgress = $session.Progress.ToString()\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get duration\n")
	script.WriteString("                                        $duration = $null\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.Progress -and $session.Progress.Duration) {\n")
	script.WriteString("                                                $duration = $session.Progress.Duration\n")
	script.WriteString("                                            } elseif ($session.Duration) {\n")
	script.WriteString("                                                $duration = $session.Duration\n")
	script.WriteString("                                            } elseif ($session.EndTimeUTC -and $session.CreationTimeUTC) {\n")
	script.WriteString("                                                $duration = $session.EndTimeUTC - $session.CreationTimeUTC\n")
	script.WriteString("                                            } elseif ($session.EndTime -and $session.CreationTime) {\n")
	script.WriteString("                                                $duration = $session.EndTime - $session.CreationTime\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            if ($duration) {\n")
	script.WriteString("                                                $sessionDuration = $duration\n")
	script.WriteString("                                                $durations += $duration.TotalMinutes\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get backup size\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.BackupStats -and $session.BackupStats.BackupSize) {\n")
	script.WriteString("                                                $backupSizeTB = [math]::Round($session.BackupStats.BackupSize / 1TB, 4)\n")
	script.WriteString("                                                $sessionBackupSize = $backupSizeTB\n")
	script.WriteString("                                                $backupSizes += $backupSizeTB\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get data size\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.BackupStats -and $session.BackupStats.DataSize) {\n")
	script.WriteString("                                                $dataSizeTB = [math]::Round($session.BackupStats.DataSize / 1TB, 4)\n")
	script.WriteString("                                                $sessionDataSize = $dataSizeTB\n")
	script.WriteString("                                                $dataSizes += $dataSizeTB\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get change rate\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.BackupStats -and $session.BackupStats.ChangeRate) {\n")
	script.WriteString("                                                $sessionChangeRate = $session.BackupStats.ChangeRate\n")
	script.WriteString("                                                $changeRates += $sessionChangeRate\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get item count (from session objects)\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($session.GetTaskSessions()) {\n")
	script.WriteString("                                                $taskSessions = $session.GetTaskSessions()\n")
	script.WriteString("                                                if ($taskSessions -is [array]) {\n")
	script.WriteString("                                                    $itemCount = [math]::Max($itemCount, $taskSessions.Count)\n")
	script.WriteString("                                                } else {\n")
	script.WriteString("                                                    $itemCount = [math]::Max($itemCount, 1)\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Format duration for display\n")
	script.WriteString("                                        $durationFormatted = '00:00:00'\n")
	script.WriteString("                                        if ($sessionDuration) {\n")
	script.WriteString("                                            $totalSeconds = [math]::Round($sessionDuration.TotalSeconds)\n")
	script.WriteString("                                            $hours = [math]::Floor($totalSeconds / 3600)\n")
	script.WriteString("                                            $mins = [math]::Floor(($totalSeconds % 3600) / 60)\n")
	script.WriteString("                                            $secs = $totalSeconds % 60\n")
	script.WriteString("                                            $durationFormatted = \"$($hours.ToString('00')):$($mins.ToString('00')):$($secs.ToString('00'))\"\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get failure/warning reason and message\n")
	script.WriteString("                                        $sessionReason = 'N/A'\n")
	script.WriteString("                                        $sessionMessage = 'N/A'\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Only collect reason and message for failed or warning sessions\n")
	script.WriteString("                                        if ($sessionResultStr -eq 'failed' -or $sessionResultStr -eq 'error' -or $sessionResultStr -eq 'failure' -or $sessionResultStr -eq 'warning' -or $sessionResultStr -eq '2' -or $sessionResultStr -eq '1') {\n")
	script.WriteString("                                            try {\n")
	script.WriteString("                                                # Try to get reason from session\n")
	script.WriteString("                                                if ($session.Reason) {\n")
	script.WriteString("                                                    $sessionReason = $session.Reason.ToString()\n")
	script.WriteString("                                                } elseif ($session.Info -and $session.Info.Reason) {\n")
	script.WriteString("                                                    $sessionReason = $session.Info.Reason.ToString()\n")
	script.WriteString("                                                } elseif ($session.FailureReason) {\n")
	script.WriteString("                                                    $sessionReason = $session.FailureReason.ToString()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # Try to get message/description from session\n")
	script.WriteString("                                                if ($session.Message) {\n")
	script.WriteString("                                                    $sessionMessage = $session.Message\n")
	script.WriteString("                                                } elseif ($session.Description) {\n")
	script.WriteString("                                                    $sessionMessage = $session.Description\n")
	script.WriteString("                                                } elseif ($session.Info -and $session.Info.Message) {\n")
	script.WriteString("                                                    $sessionMessage = $session.Info.Message\n")
	script.WriteString("                                                } elseif ($session.Info -and $session.Info.Description) {\n")
	script.WriteString("                                                    $sessionMessage = $session.Info.Description\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # Try to get error message from logs or task sessions\n")
	script.WriteString("                                                if ($sessionMessage -eq 'N/A' -or $sessionMessage -eq '') {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        # Get task sessions to find error messages\n")
	script.WriteString("                                                        $taskSessions = $null\n")
	script.WriteString("                                                        if ($session.GetTaskSessions()) {\n")
	script.WriteString("                                                            $taskSessions = $session.GetTaskSessions()\n")
	script.WriteString("                                                        } elseif ($session.TaskSessions) {\n")
	script.WriteString("                                                            $taskSessions = $session.TaskSessions\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        if ($taskSessions) {\n")
	script.WriteString("                                                            $errorMessages = @()\n")
	script.WriteString("                                                            foreach ($taskSession in $taskSessions) {\n")
	script.WriteString("                                                                try {\n")
	script.WriteString("                                                                    if ($taskSession.Result -and ($taskSession.Result.ToString().ToLower() -eq 'failed' -or $taskSession.Result.ToString().ToLower() -eq 'error' -or $taskSession.Result.ToString().ToLower() -eq 'warning')) {\n")
	script.WriteString("                                                                        if ($taskSession.Message) {\n")
	script.WriteString("                                                                            $errorMessages += $taskSession.Message\n")
	script.WriteString("                                                                        } elseif ($taskSession.Description) {\n")
	script.WriteString("                                                                            $errorMessages += $taskSession.Description\n")
	script.WriteString("                                                                        } elseif ($taskSession.Info -and $taskSession.Info.Message) {\n")
	script.WriteString("                                                                            $errorMessages += $taskSession.Info.Message\n")
	script.WriteString("                                                                        } elseif ($taskSession.Info -and $taskSession.Info.Description) {\n")
	script.WriteString("                                                                            $errorMessages += $taskSession.Info.Description\n")
	script.WriteString("                                                                        }\n")
	script.WriteString("                                                                    }\n")
	script.WriteString("                                                                } catch {}\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                            if ($errorMessages.Count -gt 0) {\n")
	script.WriteString("                                                                $sessionMessage = ($errorMessages | Select-Object -Unique) -join '; '\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # Try to get reason from logs if still not found\n")
	script.WriteString("                                                if ($sessionReason -eq 'N/A' -or $sessionReason -eq '') {\n")
	script.WriteString("                                                    try {\n")
	script.WriteString("                                                        # Check if there's a log file or log entry\n")
	script.WriteString("                                                        if ($session.Log -and $session.Log.LogPath) {\n")
	script.WriteString("                                                            $sessionReason = 'See log file: ' + $session.Log.LogPath\n")
	script.WriteString("                                                        } elseif ($session.LogPath) {\n")
	script.WriteString("                                                            $sessionReason = 'See log file: ' + $session.LogPath\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    } catch {}\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # If still no message, try to get from state or result\n")
	script.WriteString("                                                if ($sessionMessage -eq 'N/A' -or $sessionMessage -eq '') {\n")
	script.WriteString("                                                    if ($sessionState -and $sessionState -ne 'N/A') {\n")
	script.WriteString("                                                        $sessionMessage = \"State: $sessionState\"\n")
	script.WriteString("                                                    } elseif ($sessionResultStr -and $sessionResultStr -ne 'None') {\n")
	script.WriteString("                                                        $sessionMessage = \"Result: $sessionResultStr\"\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } catch {}\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Store session details\n")
	script.WriteString("                                        $sessionDetails += @{\n")
	script.WriteString("                                            'Result' = $sessionResultStr\n")
	script.WriteString("                                            'IsRetry' = $isRetry\n")
	script.WriteString("                                            'CreationTime' = $sessionCreationTime\n")
	script.WriteString("                                            'EndTime' = $sessionEndTime\n")
	script.WriteString("                                            'Duration' = $durationFormatted\n")
	script.WriteString("                                            'State' = $sessionState\n")
	script.WriteString("                                            'Progress' = $sessionProgress\n")
	script.WriteString("                                            'BackupSize' = $sessionBackupSize\n")
	script.WriteString("                                            'DataSize' = $sessionDataSize\n")
	script.WriteString("                                            'ChangeRate' = $sessionChangeRate\n")
	script.WriteString("                                            'Reason' = $sessionReason\n")
	script.WriteString("                                            'Message' = $sessionMessage\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Calculate averages and totals\n")
	script.WriteString("                                    $minTime = if ($durations.Count -gt 0) { [math]::Round(($durations | Measure-Object -Minimum).Minimum, 2) } else { 0 }\n")
	script.WriteString("                                    $maxTime = if ($durations.Count -gt 0) { [math]::Round(($durations | Measure-Object -Maximum).Maximum, 2) } else { 0 }\n")
	script.WriteString("                                    $avgTime = if ($durations.Count -gt 0) { [math]::Round(($durations | Measure-Object -Average).Average, 2) } else { 0 }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $successRate = if ($totalSessions -gt 0) { [math]::Round((($totalSessions - $fails) / $totalSessions) * 100, 2) } else { 0 }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $avgBackupSize = if ($backupSizes.Count -gt 0) { [math]::Round(($backupSizes | Measure-Object -Average).Average, 4) } else { 0 }\n")
	script.WriteString("                                    $maxBackupSize = if ($backupSizes.Count -gt 0) { [math]::Round(($backupSizes | Measure-Object -Maximum).Maximum, 4) } else { 0 }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $avgDataSize = if ($dataSizes.Count -gt 0) { [math]::Round(($dataSizes | Measure-Object -Average).Average, 4) } else { 0 }\n")
	script.WriteString("                                    $maxDataSize = if ($dataSizes.Count -gt 0) { [math]::Round(($dataSizes | Measure-Object -Maximum).Maximum, 4) } else { 0 }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $avgChangeRate = if ($changeRates.Count -gt 0) { [math]::Round(($changeRates | Measure-Object -Average).Average, 2) } else { 0 }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Format times as HH:MM:SS\n")
	script.WriteString("                                    function Format-TimeSpan {\n")
	script.WriteString("                                        param([double]$minutes)\n")
	script.WriteString("                                        if ($minutes -le 0) { return '00:00:00' }\n")
	script.WriteString("                                        $totalSeconds = [math]::Round($minutes * 60)\n")
	script.WriteString("                                        $hours = [math]::Floor($totalSeconds / 3600)\n")
	script.WriteString("                                        $mins = [math]::Floor(($totalSeconds % 3600) / 60)\n")
	script.WriteString("                                        $secs = $totalSeconds % 60\n")
	script.WriteString("                                        return \"$($hours.ToString('00')):$($mins.ToString('00')):$($secs.ToString('00'))\"\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $minTimeFormatted = Format-TimeSpan -minutes $minTime\n")
	script.WriteString("                                    $maxTimeFormatted = Format-TimeSpan -minutes $maxTime\n")
	script.WriteString("                                    $avgTimeFormatted = Format-TimeSpan -minutes $avgTime\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    # Get job type from the job object when it runs\n")
	script.WriteString("                                    $sessionJobType = 'N/A'\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($job.TypeToString) {\n")
	script.WriteString("                                            $sessionJobType = $job.TypeToString.ToString()\n")
	script.WriteString("                                        } elseif ($jobInfo.JobType) {\n")
	script.WriteString("                                            $sessionJobType = $jobInfo.JobType\n")
	script.WriteString("                                        } elseif ($job.SourceType) {\n")
	script.WriteString("                                            $sourceTypeStr = $job.SourceType.ToString()\n")
	script.WriteString("                                            if ($sourceTypeStr -eq 'HyperV' -or $sourceTypeStr -eq 'Hyper-V') {\n")
	script.WriteString("                                                $sessionJobType = 'Hyper-V Backup'\n")
	script.WriteString("                                            } elseif ($sourceTypeStr -eq 'VMware' -or $sourceTypeStr -eq 'ESX') {\n")
	script.WriteString("                                                $sessionJobType = 'VMware Backup'\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $sessionJobType = $sourceTypeStr\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } elseif ($job.Type) {\n")
	script.WriteString("                                            $typeStr = $job.Type.ToString()\n")
	script.WriteString("                                            if ($typeStr -eq 'Backup') {\n")
	script.WriteString("                                                # Check if it's VMware or Hyper-V by looking at objects\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $objects = $job.GetObjects()\n")
	script.WriteString("                                                    if ($objects) {\n")
	script.WriteString("                                                        $firstObj = if ($objects -is [array]) { $objects[0] } else { $objects }\n")
	script.WriteString("                                                        if ($firstObj -and $firstObj.Platform) {\n")
	script.WriteString("                                                            $platformStr = $firstObj.Platform.ToString()\n")
	script.WriteString("                                                            if ($platformStr -eq 'HyperV' -or $platformStr -eq 'Hyper-V') {\n")
	script.WriteString("                                                                $sessionJobType = 'Hyper-V Backup'\n")
	script.WriteString("                                                            } elseif ($platformStr -eq 'VMware' -or $platformStr -eq 'ESX') {\n")
	script.WriteString("                                                                $sessionJobType = 'VMware Backup'\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                if ($sessionJobType -eq 'N/A') {\n")
	script.WriteString("                                                    $sessionJobType = 'VMware Backup'\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($typeStr -eq 'Replica') {\n")
	script.WriteString("                                                $sessionJobType = 'Replica'\n")
	script.WriteString("                                            } elseif ($typeStr -eq 'FileCopy' -or $typeStr -eq 'Copy') {\n")
	script.WriteString("                                                $sessionJobType = 'File Copy'\n")
	script.WriteString("                                            } elseif ($typeStr -eq 'BackupCopy' -or $typeStr -eq 'SimpleBackupCopyPolicy' -or $typeStr -eq 'BackupSync') {\n")
	script.WriteString("                                                $sessionJobType = 'Backup Copy'\n")
	script.WriteString("                                            } elseif ($typeStr -eq 'NasBackup' -or $typeStr -eq 'ENasBackup' -or $typeStr -eq 'FileBackup') {\n")
	script.WriteString("                                                $sessionJobType = 'File Backup'\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $sessionJobType = $typeStr\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    $jobSessionSummary += @{\n")
	script.WriteString("                                        'JobName' = $jobName\n")
	script.WriteString("                                        'Items' = $itemCount\n")
	script.WriteString("                                        'MinTime' = $minTimeFormatted\n")
	script.WriteString("                                        'MaxTime' = $maxTimeFormatted\n")
	script.WriteString("                                        'AvgTime' = $avgTimeFormatted\n")
	script.WriteString("                                        'TotalSessions' = $totalSessions\n")
	script.WriteString("                                        'Fails' = $fails\n")
	script.WriteString("                                        'Retries' = $retries\n")
	script.WriteString("                                        'SuccessRate' = $successRate\n")
	script.WriteString("                                        'AvgBackupSize' = $avgBackupSize\n")
	script.WriteString("                                        'MaxBackupSize' = $maxBackupSize\n")
	script.WriteString("                                        'AvgDataSize' = $avgDataSize\n")
	script.WriteString("                                        'MaxDataSize' = $maxDataSize\n")
	script.WriteString("                                        'AvgChangeRate' = $avgChangeRate\n")
	script.WriteString("                                        'WaitCount' = $waitCounts\n")
	script.WriteString("                                        'MaxWait' = '00.00:00:00'\n")
	script.WriteString("                                        'AvgWait' = '00.00:00:00'\n")
	script.WriteString("                                        'JobType' = $sessionJobType\n")
	script.WriteString("                                        'Sessions' = $sessionDetails\n")
	script.WriteString("                                    }\n")
	script.WriteString("                                } catch {}\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $veeamInfo['jobSessionSummary'] = $jobSessionSummary\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Infrastructure Types & Count\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Infrastructure Types\" -Status \"Detecting infrastructure types and counts\"\n")
	script.WriteString("                        $infrastructureTypes = @{}\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $servers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($servers) {\n")
	script.WriteString("                                foreach ($server in $servers) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $serverType = $null\n")
	script.WriteString("                                        if ($server.Type) {\n")
	script.WriteString("                                            $serverType = $server.Type.ToString()\n")
	script.WriteString("                                        } elseif ($server.Info -and $server.Info.Type) {\n")
	script.WriteString("                                            $serverType = $server.Info.Type.ToString()\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        if ($serverType) {\n")
	script.WriteString("                                            if ($infrastructureTypes.ContainsKey($serverType)) {\n")
	script.WriteString("                                                $infrastructureTypes[$serverType]++\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $infrastructureTypes[$serverType] = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $infrastructureList = @()\n")
	script.WriteString("                        foreach ($key in $infrastructureTypes.Keys) {\n")
	script.WriteString("                            $infrastructureList += @{\n")
	script.WriteString("                                'name' = $key\n")
	script.WriteString("                                'count' = $infrastructureTypes[$key]\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $veeamInfo['infrastructureTypes'] = $infrastructureList\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Job Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Job Summary\" -Status \"Summarizing job types and totals\"\n")
	script.WriteString("                        $jobSummary = @{}\n")
	script.WriteString("                        $totalJobs = 0\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allJobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allJobs) {\n")
	script.WriteString("                                foreach ($job in $allJobs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $jobType = $null\n")
	script.WriteString("                                        if ($job.JobType) {\n")
	script.WriteString("                                            $jobTypeStr = $job.JobType.ToString()\n")
	script.WriteString("                                            # Normalize job types\n")
	script.WriteString("                                            if ($jobTypeStr -eq 'NasBackup' -or $jobTypeStr -eq 'ENasBackup' -or $jobTypeStr -eq 'FileBackup') {\n")
	script.WriteString("                                                $jobType = 'File Backup'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Backup') {\n")
	script.WriteString("                                                $jobType = 'Backup'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Replica') {\n")
	script.WriteString("                                                $jobType = 'Replica'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'FileCopy' -or $jobTypeStr -eq 'Copy') {\n")
	script.WriteString("                                                $jobType = 'File Copy'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'BackupCopy') {\n")
	script.WriteString("                                                $jobType = 'Backup Copy'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Tape') {\n")
	script.WriteString("                                                $jobType = 'Tape'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'Plugin') {\n")
	script.WriteString("                                                $jobType = 'Plugin'\n")
	script.WriteString("                                            } elseif ($jobTypeStr -eq 'UnmanagedAgent' -or $jobTypeStr -eq 'Agent') {\n")
	script.WriteString("                                                $jobType = 'Unmanaged Agent'\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $jobType = $jobTypeStr\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        if ($jobType) {\n")
	script.WriteString("                                            if ($jobSummary.ContainsKey($jobType)) {\n")
	script.WriteString("                                                $jobSummary[$jobType]++\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                $jobSummary[$jobType] = 1\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                            $totalJobs++\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $jobSummaryList = @()\n")
	script.WriteString("                        foreach ($key in $jobSummary.Keys | Sort-Object) {\n")
	script.WriteString("                            $jobSummaryList += @{\n")
	script.WriteString("                                'type' = $key\n")
	script.WriteString("                                'total' = $jobSummary[$key]\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $veeamInfo['jobSummary'] = @{\n")
	script.WriteString("                            'summary' = $jobSummaryList\n")
	script.WriteString("                            'totalJobs' = $totalJobs\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Protected Workloads\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Protected Workloads\" -Status \"Analyzing VMware, Hyper-V, and Physical workloads\"\n")
	script.WriteString("                        $protectedWorkloads = @{\n")
	script.WriteString("                            'vmware' = @{\n")
	script.WriteString("                                'viTotal' = 0\n")
	script.WriteString("                                'viProtected' = 0\n")
	script.WriteString("                                'viNotProt' = 0\n")
	script.WriteString("                                'viPotentialDupes' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                            'hyperv' = @{\n")
	script.WriteString("                                'hvTotal' = 0\n")
	script.WriteString("                                'hvProtected' = 0\n")
	script.WriteString("                                'hvUnprotected' = 0\n")
	script.WriteString("                                'hvDuplicates' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                            'physical' = @{\n")
	script.WriteString("                                'viProtectedAsPhysical' = 0\n")
	script.WriteString("                                'physTotal' = 0\n")
	script.WriteString("                                'phyProtected' = 0\n")
	script.WriteString("                                'physNotProt' = 0\n")
	script.WriteString("                            }\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # VMware Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $vmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'VMware Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $vmNames = $null\n")
	script.WriteString("                            if ($vmbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $vmNames = $vmbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $vmNames = $vmbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $allViEntities = Find-VBRViEntity -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allViEntities) {\n")
	script.WriteString("                                $protectedWorkloads['vmware']['viTotal'] = $allViEntities.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                    $protectedEntityInfo = Find-VBRViEntity -Name $vmNames.Name -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $unprotectedEntityInfo = Find-VBRViEntity | Where-Object { $_.Name -notin $vmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protectedEntityInfo) { $protectedWorkloads['vmware']['viProtected'] = $protectedEntityInfo.Count }\n")
	script.WriteString("                                    if ($unprotectedEntityInfo) { $protectedWorkloads['vmware']['viNotProt'] = $unprotectedEntityInfo.Count }\n")
	script.WriteString("                                    $protectedWorkloads['vmware']['viPotentialDupes'] = $vmNames.Count\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['vmware']['viNotProt'] = $allViEntities.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Hyper-V Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $hvvmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'Hyper-v Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $hvvmNames = $null\n")
	script.WriteString("                            if ($hvvmbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $hvvmNames = $hvvmbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $hvvmNames = $hvvmbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $allHvEntities = Find-VBRHvEntity -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allHvEntities) {\n")
	script.WriteString("                                $protectedWorkloads['hyperv']['hvTotal'] = $allHvEntities.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($hvvmNames -and $hvvmNames.Name) {\n")
	script.WriteString("                                    $protectedHvEntityInfo = Find-VBRHvEntity -Name $hvvmNames.Name -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $unprotectedHvEntityInfo = Find-VBRHvEntity | Where-Object { $_.Name -notin $hvvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protectedHvEntityInfo) { $protectedWorkloads['hyperv']['hvProtected'] = $protectedHvEntityInfo.Count }\n")
	script.WriteString("                                    if ($unprotectedHvEntityInfo) { $protectedWorkloads['hyperv']['hvUnprotected'] = $unprotectedHvEntityInfo.Count }\n")
	script.WriteString("                                    $protectedWorkloads['hyperv']['hvDuplicates'] = $hvvmNames.Count\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['hyperv']['hvUnprotected'] = $allHvEntities.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Physical Backups\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $physbackups = Get-VBRBackup | Where-Object { $_.TypeToString -like '*Agent*' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $pvmNames = $null\n")
	script.WriteString("                            if ($physbackups) {\n")
	script.WriteString("                                try {\n")
	script.WriteString("                                    $pvmNames = $physbackups.GetLastOibs($true)\n")
	script.WriteString("                                } catch {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $pvmNames = $physbackups.GetLastOibs()\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            $phys = Get-VBRComputer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($phys) {\n")
	script.WriteString("                                $protectedWorkloads['physical']['physTotal'] = $phys.Count\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($pvmNames -and $pvmNames.Name) {\n")
	script.WriteString("                                    $protected = $phys | Where-Object { $_.Name -in $pvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $notprotected = $phys | Where-Object { $_.Name -notin $pvmNames.Name } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    \n")
	script.WriteString("                                    if ($protected) { $protectedWorkloads['physical']['phyProtected'] = $protected.Count }\n")
	script.WriteString("                                    if ($notprotected) { $protectedWorkloads['physical']['physNotProt'] = $notprotected.Count }\n")
	script.WriteString("                                } else {\n")
	script.WriteString("                                    $protectedWorkloads['physical']['physNotProt'] = $phys.Count\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['protectedWorkloads'] = $protectedWorkloads\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Managed Server Info\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Managed Server Information\" -Status \"Gathering details for all managed servers\"\n")
	script.WriteString("                        $managedServers = @()\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allServers = Get-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $repos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $wanAccs = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($allServers) {\n")
	script.WriteString("                                foreach ($server in $allServers) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $serverInfo = @{\n")
	script.WriteString("                                            'name' = if ($server.Name) { $server.Name } else { 'N/A' }\n")
	script.WriteString("                                            'cores' = 0\n")
	script.WriteString("                                            'ram' = 0\n")
	script.WriteString("                                            'type' = if ($server.Type) { $server.Type.ToString() } else { 'N/A' }\n")
	script.WriteString("                                            'osInfo' = 'N/A'\n")
	script.WriteString("                                            'apiVersion' = ''\n")
	script.WriteString("                                            'protectedVMs' = 0\n")
	script.WriteString("                                            'notProtectedVMs' = 0\n")
	script.WriteString("                                            'totalVMs' = 0\n")
	script.WriteString("                                            'isProxy' = $false\n")
	script.WriteString("                                            'isRepo' = $false\n")
	script.WriteString("                                            'isWANAcc' = $false\n")
	script.WriteString("                                            'isUnavailable' = if ($server.IsUnavailable -ne $null) { $server.IsUnavailable } else { $false }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get API Version (try multiple methods)\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.ApiVersion) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.ApiVersion.ToString()\n")
	script.WriteString("                                            } elseif ($server.Info -and $server.Info.ApiVersion) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.Info.ApiVersion.ToString()\n")
	script.WriteString("                                            } elseif ($server.Version) {\n")
	script.WriteString("                                                $serverInfo['apiVersion'] = $server.Version.ToString()\n")
	script.WriteString("                                            } elseif ($server.GetPhysicalHost()) {\n")
	script.WriteString("                                                $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                if ($physHost -and $physHost.ApiVersion) {\n")
	script.WriteString("                                                    $serverInfo['apiVersion'] = $physHost.ApiVersion.ToString()\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get Cores and RAM\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.Type -eq 'Local' -or $server.Type -eq 'Windows') {\n")
	script.WriteString("                                                # For local/Windows servers, use WMI/CIM to get system info\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $computerSystem = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($computerSystem -and $computerSystem.TotalPhysicalMemory) {\n")
	script.WriteString("                                                        # Convert bytes to GB\n")
	script.WriteString("                                                        $serverInfo['ram'] = [math]::Round($computerSystem.TotalPhysicalMemory / 1GB, 2)\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $processor = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($processor) {\n")
	script.WriteString("                                                        $totalCores = ($processor | Measure-Object -Property NumberOfCores -Sum).Sum\n")
	script.WriteString("                                                        if ($totalCores -and $totalCores -gt 0) {\n")
	script.WriteString("                                                            $serverInfo['cores'] = $totalCores\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $totalLogical = ($processor | Measure-Object -Property NumberOfLogicalProcessors -Sum).Sum\n")
	script.WriteString("                                                            if ($totalLogical -and $totalLogical -gt 0) {\n")
	script.WriteString("                                                                $serverInfo['cores'] = $totalLogical\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                                \n")
	script.WriteString("                                                # Get OS Info for local server\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($os) {\n")
	script.WriteString("                                                        $serverInfo['osInfo'] = $os.Caption + ' ' + $os.OSArchitecture + ' (' + $os.Version + ' build:' + $os.BuildNumber + ')'\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            } else {\n")
	script.WriteString("                                                # For remote servers, use GetPhysicalHost\n")
	script.WriteString("                                                $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                if ($physHost -and $physHost.hardwareinfo) {\n")
	script.WriteString("                                                    if ($physHost.hardwareinfo.CoresCount) { $serverInfo['cores'] = $physHost.hardwareinfo.CoresCount }\n")
	script.WriteString("                                                    if ($physHost.hardwareinfo.PhysicalRamTotal) {\n")
	script.WriteString("                                                        # PhysicalRamTotal is in bytes, convert to GB\n")
	script.WriteString("                                                        $serverInfo['ram'] = [math]::Round($physHost.hardwareinfo.PhysicalRamTotal / 1GB, 2)\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get OS Info (fallback if not already set)\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($serverInfo['osInfo'] -eq 'N/A' -or -not $serverInfo['osInfo'] -or $serverInfo['osInfo'] -eq '') {\n")
	script.WriteString("                                                if ($server.Info -and $server.Info.Info) {\n")
	script.WriteString("                                                    $serverInfo['osInfo'] = $server.Info.Info\n")
	script.WriteString("                                                } elseif ($server.Info -and $server.Info.Name) {\n")
	script.WriteString("                                                    $serverInfo['osInfo'] = $server.Info.Name\n")
	script.WriteString("                                                } elseif ($server.GetPhysicalHost()) {\n")
	script.WriteString("                                                    $physHost = $server.GetPhysicalHost()\n")
	script.WriteString("                                                    if ($physHost -and $physHost.Info) {\n")
	script.WriteString("                                                        if ($physHost.Info.Info) {\n")
	script.WriteString("                                                            $serverInfo['osInfo'] = $physHost.Info.Info\n")
	script.WriteString("                                                        } elseif ($physHost.Info.Name) {\n")
	script.WriteString("                                                            $serverInfo['osInfo'] = $physHost.Info.Name\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a proxy\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($proxies) {\n")
	script.WriteString("                                                $isProxy = ($proxies | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isProxy'] = $isProxy\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a repository\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($repos) {\n")
	script.WriteString("                                                $isRepo = ($repos | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isRepo'] = $isRepo\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if server is a WAN Accelerator\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($wanAccs) {\n")
	script.WriteString("                                                $isWANAcc = ($wanAccs | Where-Object { $_.HostId -eq $server.Id }) -ne $null\n")
	script.WriteString("                                                $serverInfo['isWANAcc'] = $isWANAcc\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Get VM counts for ESXi/VC servers\n")
	script.WriteString("                                        try {\n")
	script.WriteString("                                            if ($server.Type -eq 'ESXi' -or $server.Type -eq 'VC') {\n")
	script.WriteString("                                                $viEntities = Find-VBRViEntity -Server $server -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                if ($viEntities) {\n")
	script.WriteString("                                                    $serverInfo['totalVMs'] = $viEntities.Count\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    $vmbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'VMware Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    $vmNames = $null\n")
	script.WriteString("                                                    if ($vmbackups) {\n")
	script.WriteString("                                                        try {\n")
	script.WriteString("                                                            $vmNames = $vmbackups.GetLastOibs($true)\n")
	script.WriteString("                                                        } catch {\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $vmNames = $vmbackups.GetLastOibs()\n")
	script.WriteString("                                                            } catch {}\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                    \n")
	script.WriteString("                                                    if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                                        $serverVMs = $viEntities | Where-Object { $_.Name -in $vmNames.Name }\n")
	script.WriteString("                                                        $serverInfo['protectedVMs'] = $serverVMs.Count\n")
	script.WriteString("                                                        $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs'] - $serverInfo['protectedVMs']\n")
	script.WriteString("                                                    } else {\n")
	script.WriteString("                                                        $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs']\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            } elseif ($server.Type -eq 'HvServer' -or $server.Type -eq 'HyperV') {\n")
	script.WriteString("                                                # Get VM counts for Hyper-V servers\n")
	script.WriteString("                                                try {\n")
	script.WriteString("                                                    $hvEntities = Find-VBRHvEntity -Server $server -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                    if ($hvEntities) {\n")
	script.WriteString("                                                        $serverInfo['totalVMs'] = $hvEntities.Count\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        $hvbackups = Get-VBRBackup | Where-Object { $_.TypeToString -eq 'Hyper-V Backup' } -ErrorAction SilentlyContinue\n")
	script.WriteString("                                                        $vmNames = $null\n")
	script.WriteString("                                                        if ($hvbackups) {\n")
	script.WriteString("                                                            try {\n")
	script.WriteString("                                                                $vmNames = $hvbackups.GetLastOibs($true)\n")
	script.WriteString("                                                            } catch {\n")
	script.WriteString("                                                                try {\n")
	script.WriteString("                                                                    $vmNames = $hvbackups.GetLastOibs()\n")
	script.WriteString("                                                                } catch {}\n")
	script.WriteString("                                                            }\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                        \n")
	script.WriteString("                                                        if ($vmNames -and $vmNames.Name) {\n")
	script.WriteString("                                                            $serverVMs = $hvEntities | Where-Object { $_.Name -in $vmNames.Name }\n")
	script.WriteString("                                                            $serverInfo['protectedVMs'] = $serverVMs.Count\n")
	script.WriteString("                                                            $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs'] - $serverInfo['protectedVMs']\n")
	script.WriteString("                                                        } else {\n")
	script.WriteString("                                                            $serverInfo['notProtectedVMs'] = $serverInfo['totalVMs']\n")
	script.WriteString("                                                        }\n")
	script.WriteString("                                                    }\n")
	script.WriteString("                                                } catch {}\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        } catch {}\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $managedServers += $serverInfo\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        $veeamInfo['managedServers'] = $managedServers\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Proxies\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Backup Proxies\" -Status \"Enumerating backup proxy servers\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $proxies = Get-VBRViProxy -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['proxies'] = @($proxies | Select-Object -Property Name, HostId, @{n='Host';e={$_.Host.Name}})\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get WAN Accelerators\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting WAN Accelerators\" -Status \"Enumerating WAN accelerator servers\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $wanAccelerators = Get-VBRWANAccelerator -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $veeamInfo['wanAccelerators'] = @($wanAccelerators | Select-Object -Property Name, HostId, @{n='Host';e={$_.Host.Name}})\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Database Information\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Database Configuration\" -Status \"Retrieving database connection details\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $dbType = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations' -Name 'SqlActiveConfiguration' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $dbServerPath = Get-ItemProperty -Path $veeamRegPath -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            $instancePath = Get-ItemProperty -Path $veeamRegPath -Name 'SqlInstanceName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($dbType) {\n")
	script.WriteString("                                $veeamInfo['database'] = @{\n")
	script.WriteString("                                    'type' = $dbType.SqlActiveConfiguration\n")
	script.WriteString("                                    'server' = if ($dbServerPath) { $dbServerPath.SqlServerName } else { 'N/A' }\n")
	script.WriteString("                                    'instance' = if ($instancePath) { $instancePath.SqlInstanceName } else { 'N/A' }\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                if ($dbType.SqlActiveConfiguration -eq 'PostgreSql') {\n")
	script.WriteString("                                    $pgDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlHostName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $pgDbDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\PostgreSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($pgDbHost) { $veeamInfo['database']['pgHost'] = $pgDbHost.SqlHostName }\n")
	script.WriteString("                                    if ($pgDbDbName) { $veeamInfo['database']['pgDb'] = $pgDbDbName.SqlDatabaseName }\n")
	script.WriteString("                                } elseif ($dbType.SqlActiveConfiguration -eq 'MsSql') {\n")
	script.WriteString("                                    $msDbHost = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlServerName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    $msDbName = Get-ItemProperty -Path 'HKLM:\\SOFTWARE\\Veeam\\Veeam Backup and Replication\\DatabaseConfigurations\\MsSql' -Name 'SqlDatabaseName' -ErrorAction SilentlyContinue\n")
	script.WriteString("                                    if ($msDbHost) { $veeamInfo['database']['msHost'] = $msDbHost.SqlServerName }\n")
	script.WriteString("                                    if ($msDbName) { $veeamInfo['database']['msDb'] = $msDbName.SqlDatabaseName }\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Security Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Security Summary\" -Status \"Analyzing security settings and encryption\"\n")
	script.WriteString("                        $securitySummary = @{\n")
	script.WriteString("                            'immutability' = $false\n")
	script.WriteString("                            'trafficEncryption' = $false\n")
	script.WriteString("                            'backupFileEncryption' = $false\n")
	script.WriteString("                            'configBackupEncryption' = $false\n")
	script.WriteString("                            'mfaEnabled' = $false\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Immutability (at least one repository with BackupImmutabilityEnabled)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allRepos = Get-VBRBackupRepository -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allRepos) {\n")
	script.WriteString("                                foreach ($repo in $allRepos) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($repo.BackupImmutabilityEnabled -eq $true) {\n")
	script.WriteString("                                            $securitySummary['immutability'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                            # Also check SOBR extents\n")
	script.WriteString("                            $sobrRepos = Get-VBRBackupRepository -ScaleOut -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($sobrRepos) {\n")
	script.WriteString("                                foreach ($sobr in $sobrRepos) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $extents = $sobr | Get-VBRCapacityExtent -ErrorAction SilentlyContinue\n")
	script.WriteString("                                        if ($extents) {\n")
	script.WriteString("                                            foreach ($extent in $extents) {\n")
	script.WriteString("                                                if ($extent.Repository -and $extent.Repository.BackupImmutabilityEnabled -eq $true) {\n")
	script.WriteString("                                                    $securitySummary['immutability'] = $true\n")
	script.WriteString("                                                    break\n")
	script.WriteString("                                                }\n")
	script.WriteString("                                            }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Traffic Encryption (at least one network traffic rule with EncryptionEnabled)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $trafficRules = Get-VBRNetworkTrafficRule -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($trafficRules) {\n")
	script.WriteString("                                foreach ($rule in $trafficRules) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        if ($rule.EncryptionEnabled -eq $true) {\n")
	script.WriteString("                                            $securitySummary['trafficEncryption'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Check Backup File Encryption (at least one job with PasswordKeyId not empty and not default)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $allJobs = Get-VBRJob -WarningAction SilentlyContinue -ErrorAction SilentlyContinue\n")
	script.WriteString("                            if ($allJobs) {\n")
	script.WriteString("                                foreach ($job in $allJobs) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $pwdKeyId = $null\n")
	script.WriteString("                                        if ($job.Options -and $job.Options.BackupStorageOptions -and $job.Options.BackupStorageOptions.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Options.BackupStorageOptions.Encryption.PasswordKeyId\n")
	script.WriteString("                                        } elseif ($job.Options -and $job.Options.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Options.Encryption.PasswordKeyId\n")
	script.WriteString("                                        } elseif ($job.Encryption) {\n")
	script.WriteString("                                            $pwdKeyId = $job.Encryption.PasswordKeyId\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($pwdKeyId -and $pwdKeyId -ne '' -and $pwdKeyId -ne '00000000-0000-0000-0000-000000000000') {\n")
	script.WriteString("                                            $securitySummary['backupFileEncryption'] = $true\n")
	script.WriteString("                                            break\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Config Backup Encryption (from configBackup.encrypted)\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            if ($veeamInfo['configBackup'] -and $veeamInfo['configBackup']['encrypted']) {\n")
	script.WriteString("                                $securitySummary['configBackupEncryption'] = $veeamInfo['configBackup']['encrypted']\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get MFA Setting (VBR 12+)\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting MFA Settings\" -Status \"Checking multi-factor authentication configuration\"\n")
	script.WriteString("                        try {\n")
	script.WriteString("                            $mfaGlobalSetting = [Veeam.Backup.Core.SBackupOptions]::get_GlobalMFA()\n")
	script.WriteString("                            $securitySummary['mfaEnabled'] = $mfaGlobalSetting\n")
	script.WriteString("                            $veeamInfo['mfaEnabled'] = $mfaGlobalSetting\n")
	script.WriteString("                        } catch {\n")
	script.WriteString("                            $securitySummary['mfaEnabled'] = $false\n")
	script.WriteString("                            $veeamInfo['mfaEnabled'] = 'N/A - Pre VBR 12'\n")
	script.WriteString("                        }\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['securitySummary'] = $securitySummary\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Get Compliance Summary\n")
	script.WriteString("                        Update-Progress -Step ($currentStep++) -Activity \"Collecting Compliance Summary\" -Status \"Analyzing best practices and compliance status\"\n")
	script.WriteString("                        $complianceSummary = @{\n")
	script.WriteString("                            'passed' = 0\n")
	script.WriteString("                            'notImplemented' = 0\n")
	script.WriteString("                            'unableToDetect' = 0\n")
	script.WriteString("                            'suppressed' = 0\n")
	script.WriteString("                        }\n")
	script.WriteString("                        $complianceTable = @()\n")
	script.WriteString("                        \n")
	script.WriteString("                        try {\n")
	script.WriteString("                            # Get VBR Version\n")
	script.WriteString("                            $vbrVersion = 12\n")
	script.WriteString("                            try {\n")
	script.WriteString("                                $vbrVersionObj = Get-VBRVersion -ErrorAction SilentlyContinue\n")
	script.WriteString("                                if ($vbrVersionObj) {\n")
	script.WriteString("                                    $vbrVersion = $vbrVersionObj.Major\n")
	script.WriteString("                                }\n")
	script.WriteString("                            } catch {}\n")
	script.WriteString("                            \n")
	script.WriteString("                            # Get Compliance Results\n")
	script.WriteString("                            $securityCompliances = $null\n")
	script.WriteString("                            if ($vbrVersion -ge 13) {\n")
	script.WriteString("                                # VBR 13+ uses Get-VBRSecurityComplianceAnalyzerResults cmdlet\n")
	script.WriteString("                                $securityCompliances = Get-VBRSecurityComplianceAnalyzerResults -ErrorAction SilentlyContinue\n")
	script.WriteString("                            } else {\n")
	script.WriteString("                                # VBR 12 uses database method\n")
	script.WriteString("                                $securityCompliances = [Veeam.Backup.DBManager.CDBManager]::Instance.BestPractices.GetAll()\n")
	script.WriteString("                            }\n")
	script.WriteString("                            \n")
	script.WriteString("                            if ($securityCompliances) {\n")
	script.WriteString("                                # Mapping of rule types to best practice names\n")
	script.WriteString("                                $ruleTypes = @{\n")
	script.WriteString("                                    'WindowsScriptHostDisabled' = 'Windows Script Host is disabled'\n")
	script.WriteString("                                    'BackupServicesUnderLocalSystem' = 'Backup services run under the LocalSystem account'\n")
	script.WriteString("                                    'OutdatedSslAndTlsDisabled' = 'Outdated SSL And TLS are Disabled'\n")
	script.WriteString("                                    'ManualLinuxHostAuthentication' = 'Unknown Linux servers are not trusted automatically'\n")
	script.WriteString("                                    'CSmbSigningAndEncryptionEnabled' = 'SMB v3 signing is enabled'\n")
	script.WriteString("                                    'ViProxyTrafficEncrypted' = 'Host to proxy traffic encryption should be enabled for the Network transport mode'\n")
	script.WriteString("                                    'JobsTargetingCloudRepositoriesEncrypted' = 'Backup jobs to cloud repositories is encrypted'\n")
	script.WriteString("                                    'LLMNRDisabled' = 'Link-Local Multicast Name Resolution (LLMNR) is disabled'\n")
	script.WriteString("                                    'ImmutableOrOfflineMediaPresence' = 'Immutable or offline media is used'\n")
	script.WriteString("                                    'OsBucketsInComplianceMode' = 'Os Buckets In Compliance Mode'\n")
	script.WriteString("                                    'BackupServerUpToDate' = 'Backup Server is Up To Date'\n")
	script.WriteString("                                    'BackupServerInProductionDomain' = 'Computer is Workgroup member'\n")
	script.WriteString("                                    'ReverseIncrementalInUse' = 'Reverse incremental backup mode is not used'\n")
	script.WriteString("                                    'ConfigurationBackupEncryptionEnabled' = 'Configuration backup encryption is enabled'\n")
	script.WriteString("                                    'WDigestNotStorePasswordsInMemory' = 'WDigest credentials caching is disabled'\n")
	script.WriteString("                                    'WebProxyAutoDiscoveryDisabled' = 'Web Proxy Auto-Discovery service (WinHttpAutoProxySvc) is disabled'\n")
	script.WriteString("                                    'ContainBackupCopies' = 'All backups have at least one copy (the 3-2-1 backup rule)'\n")
	script.WriteString("                                    'SMB1ProtocolDisabled' = 'SMB 1.0 is disabled'\n")
	script.WriteString("                                    'EmailNotificationsEnabled' = 'Email notifications are enabled'\n")
	script.WriteString("                                    'RemoteRegistryDisabled' = 'Remote registry service is disabled'\n")
	script.WriteString("                                    'PasswordsRotation' = 'Credentials and encryption passwords rotates annually'\n")
	script.WriteString("                                    'WinRmServiceDisabled' = 'Remote powershell is disabled (WinRM service)'\n")
	script.WriteString("                                    'MfaEnabledInBackupConsole' = 'MFA is enabled'\n")
	script.WriteString("                                    'HardenedRepositorySshDisabled' = 'Hardened repositories have SSH disabled'\n")
	script.WriteString("                                    'LinuxServersUsingSSHKeys' = 'Linux servers have password-based authentication disabled'\n")
	script.WriteString("                                    'RemoteDesktopServiceDisabled' = 'Remote desktop protocol is disabled'\n")
	script.WriteString("                                    'ConfigurationBackupEnabled' = 'Configuration backup is enabled'\n")
	script.WriteString("                                    'WindowsFirewallEnabled' = 'Windows firewall is enabled'\n")
	script.WriteString("                                    'FirewallEnabled' = 'Windows firewall is enabled'\n")
	script.WriteString("                                    'ConfigurationBackupEnabledAndEncrypted' = 'Configuration backup is enabled and use encryption'\n")
	script.WriteString("                                    'HardenedRepositoryNotVirtual' = 'Hardened repositories are not hosted in virtual machines'\n")
	script.WriteString("                                    'ConfigurationBackupRepositoryNotLocal' = 'The configuration backup is not stored on the backup server'\n")
	script.WriteString("                                    'PostgreSqlUseRecommendedSettings' = 'PostgreSQL server uses recommended settings'\n")
	script.WriteString("                                    'LossProtectionEnabled' = 'Password loss protection is enabled'\n")
	script.WriteString("                                    'TrafficEncryptionEnabled' = 'Encryption network rules added for LAN traffic'\n")
	script.WriteString("                                    'NetBiosDisabled' = 'NetBIOS protocol should be disabled on all network interfaces'\n")
	script.WriteString("                                    'HardenedRepositoryNotContainsNBDProxies' = 'Hardened repository should not be used as proxy'\n")
	script.WriteString("                                    'LsassProtectedProcess' = 'Local Security Authority Server Service (LSASS) running as protected process'\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                # Mapping of status values\n")
	script.WriteString("                                $statusObj = @{\n")
	script.WriteString("                                    'Ok' = 'Passed'\n")
	script.WriteString("                                    'Violation' = 'Not Implemented'\n")
	script.WriteString("                                    'UnableToCheck' = 'Unable to Detect'\n")
	script.WriteString("                                    'Suppressed' = 'Suppressed'\n")
	script.WriteString("                                }\n")
	script.WriteString("                                \n")
	script.WriteString("                                foreach ($compliance in $securityCompliances) {\n")
	script.WriteString("                                    try {\n")
	script.WriteString("                                        $complianceType = $null\n")
	script.WriteString("                                        $complianceStatus = $null\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($compliance.Type) {\n")
	script.WriteString("                                            $complianceType = $compliance.Type.ToString()\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        if ($compliance.Status) {\n")
	script.WriteString("                                            $complianceStatus = $compliance.Status.ToString()\n")
	script.WriteString("                                        } else {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if rule type exists in mapping\n")
	script.WriteString("                                        if (-not $ruleTypes.ContainsKey($complianceType)) {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Check if status exists in mapping\n")
	script.WriteString("                                        if (-not $statusObj.ContainsKey($complianceStatus)) {\n")
	script.WriteString("                                            continue\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        $bestPractice = $ruleTypes[$complianceType]\n")
	script.WriteString("                                        $status = $statusObj[$complianceStatus]\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Add to table\n")
	script.WriteString("                                        $complianceTable += @{\n")
	script.WriteString("                                            'bestPractice' = $bestPractice\n")
	script.WriteString("                                            'status' = $status\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                        \n")
	script.WriteString("                                        # Count by status\n")
	script.WriteString("                                        switch ($status) {\n")
	script.WriteString("                                            'Passed' { $complianceSummary['passed']++ }\n")
	script.WriteString("                                            'Not Implemented' { $complianceSummary['notImplemented']++ }\n")
	script.WriteString("                                            'Unable to Detect' { $complianceSummary['unableToDetect']++ }\n")
	script.WriteString("                                            'Suppressed' { $complianceSummary['suppressed']++ }\n")
	script.WriteString("                                        }\n")
	script.WriteString("                                    } catch {}\n")
	script.WriteString("                                }\n")
	script.WriteString("                            }\n")
	script.WriteString("                        } catch {}\n")
	script.WriteString("                        \n")
	script.WriteString("                        $veeamInfo['complianceSummary'] = $complianceSummary\n")
	script.WriteString("                        $veeamInfo['complianceTable'] = $complianceTable\n")
	script.WriteString("                        \n")
	script.WriteString("                        # Disconnect\n")
	script.WriteString("                        Disconnect-VBRServer -ErrorAction SilentlyContinue\n")
	script.WriteString("                    } catch {\n")
	script.WriteString("                        $veeamInfo['error'] = \"Failed to connect to VBR server: $($_.Exception.Message)\"\n")
	script.WriteString("                        $veeamInfo['connected'] = $false\n")
	script.WriteString("                    }\n")
	script.WriteString("                } catch {\n")
	script.WriteString("                    $veeamInfo['error'] = \"Veeam module loaded but commands failed: $($_.Exception.Message)\"\n")
	script.WriteString("                }\n")
	script.WriteString("            } else {\n")
	script.WriteString("                $veeamInfo['error'] = 'Veeam PowerShell module/snap-in not available'\n")
	script.WriteString("            }\n")
	script.WriteString("        }\n")
	script.WriteString("    } catch {\n")
	script.WriteString("        $veeamInfo['error'] = $_.Exception.Message\n")
	script.WriteString("    }\n")
	script.WriteString("    \n")
	script.WriteString("    $result['veeam'] = $veeamInfo\n\n")

	script.WriteString("    # Add metadata\n")
	script.WriteString("    $result['auditDate'] = (Get-Date).ToString('yyyy-MM-ddTHH:mm:ssZ')\n")
	script.WriteString("    $computer = Get-CimInstance Win32_ComputerSystem\n")
	script.WriteString("    $result['serverName'] = $computer.Name\n\n")

	script.WriteString("} catch {\n")
	script.WriteString("    $result['error'] = $_.Exception.Message\n")
	script.WriteString("    $result['errorDetails'] = $_.Exception.ToString()\n")
	script.WriteString("}\n\n")

	script.WriteString("Update-Progress -Step ($currentStep++) -Activity \"Finalizing\" -Status \"Converting data to JSON and saving\"\n")
	script.WriteString("Write-Host \"\"\n")
	script.WriteString("# Convert to JSON and save output\n")
	script.WriteString("$outputFile = \"VeeamAudit_$(Get-Date -Format 'yyyyMMdd_HHmmss').json\"\n")
	script.WriteString("$json = $result | ConvertTo-Json -Depth 10 -Compress\n")
	script.WriteString("# Use .NET method to write UTF-8 without BOM\n")
	script.WriteString("$utf8NoBom = New-Object System.Text.UTF8Encoding $false\n")
	script.WriteString("$fullPath = Join-Path (Get-Location).Path $outputFile\n")
	if encrypt {
		script.WriteString("$encryptedData = Encrypt-Data -Data $json -PublicKeyBase64 $pubKeyB64\n")
		script.WriteString("if (-not $encryptedData) {\n")
		script.WriteString("    Write-Error \"Failed to encrypt data\"\n")
		script.WriteString("    exit 1\n")
		script.WriteString("}\n")
		script.WriteString("try {\n")
		script.WriteString("    [System.IO.File]::WriteAllText($fullPath, $encryptedData, $utf8NoBom)\n")
		script.WriteString("} catch {\n")
		script.WriteString("    Write-Error \"Failed to save file: $_\"\n")
		script.WriteString("    exit 1\n")
		script.WriteString("}\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"========================================\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"  Audit Completed Successfully!\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"========================================\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"Encrypted report data saved to:\" -ForegroundColor Yellow\n")
		script.WriteString("Write-Host \"  $outputFile\" -ForegroundColor White\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"Full path:\" -ForegroundColor Cyan\n")
		script.WriteString("Write-Host \"  $(Resolve-Path $fullPath)\" -ForegroundColor White\n")
	} else {
		script.WriteString("try {\n")
		script.WriteString("    [System.IO.File]::WriteAllText($fullPath, $json, $utf8NoBom)\n")
		script.WriteString("} catch {\n")
		script.WriteString("    Write-Error \"Failed to save file: $_\"\n")
		script.WriteString("    exit 1\n")
		script.WriteString("}\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"========================================\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"  Audit Completed Successfully!\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"========================================\" -ForegroundColor Green\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"Plain report data saved to:\" -ForegroundColor Yellow\n")
		script.WriteString("Write-Host \"  $outputFile\" -ForegroundColor White\n")
		script.WriteString("Write-Host \"\"\n")
		script.WriteString("Write-Host \"Full path:\" -ForegroundColor Cyan\n")
		script.WriteString("Write-Host \"  $(Resolve-Path $fullPath)\" -ForegroundColor White\n")
	}
	script.WriteString("Write-Host \"\"\n")
	script.WriteString("$endTime = Get-Date\n")
	script.WriteString("$duration = $endTime - $startTime\n")
	script.WriteString("Write-Host \"Total execution time: $($duration.TotalSeconds.ToString('F2')) seconds\" -ForegroundColor Cyan\n")
	script.WriteString("Write-Host \"\"\n")

	return script.String()
}

// migrateVeeamReportsTable adds missing columns to veeam_reports table
func migrateVeeamReportsTable() error {
	var count int
	err := database.DB.QueryRow("SELECT COUNT(*) FROM pragma_table_info('veeam_reports') WHERE name='private_key'").Scan(&count)
	if err != nil || count == 0 {
		_, err = database.DB.Exec("ALTER TABLE veeam_reports ADD COLUMN private_key TEXT")
		if err != nil && !strings.Contains(err.Error(), "duplicate column") {
			return err
		}
		log.Printf("Added private_key column to veeam_reports table")
	}
	return nil
}
